(function (root) {
  'use strict';
  var TR = root.CALR_TRANS = root.CALR_TRANS || {};

  TR['CN-LAW-0088'] = {
    "lawId": "CN-LAW-0088",
    "sourceLang": "zh",
    "targetLang": "en",
    "engine": "llm",
    "model": "deepseek-v4.1-flash",
    "promptVersion": "calr-trans-v2",
    "translatedAt": "2026-10-14",
    "reviewed": "machine",
    "glossaryVersion": "calr-terms-2026-10-v2",
    "completenessNote": "逐条对译，共 41 条；条号与官方原文一一对应，未合并、未省略。",
    "articles": [
      {
        "no": 1,
        "text": {
          "en": "This Law is enacted for the purpose of promoting the sound development of the socialist market economy, encouraging and protecting fair competition, preventing and curbing acts of unfair competition, and protecting the lawful rights and interests of undertakings and consumers."
        },
        "noLabel": {
          "en": "Article 1."
        }
      },
      {
        "no": 2,
        "text": {
          "en": "In production and business activities, undertakings shall follow the principles of voluntariness, equality, fairness and good faith, comply with the law and business ethics, and participate fairly in market competition.\nThe term 'acts of unfair competition' as used in this Law refers to acts committed by undertakings in production and business activities that violate the provisions of this Law, disrupt the order of market competition, and harm the lawful rights and interests of other undertakings or consumers.\nThe term 'undertaking' as used in this Law refers to a natural person, legal person or unincorporated organisation that engages in the production or operation of goods or the provision of services (goods as referred to hereinafter include services)."
        },
        "noLabel": {
          "en": "Article 2."
        }
      },
      {
        "no": 3,
        "text": {
          "en": "Anti-unfair competition work shall adhere to the leadership of the Communist Party of China.\nThe State shall improve and perfect the rules and institutions for anti-unfair competition, strengthen law enforcement and judicial work in the field of anti-unfair competition, maintain the order of market competition, and improve a unified, open, competitive and orderly market system.\nThe State shall establish and improve the fair competition review system, strengthen fair competition review in accordance with the law, and ensure that all types of undertakings use production factors equally and participate fairly in market competition in accordance with the law."
        },
        "noLabel": {
          "en": "Article 3."
        }
      },
      {
        "no": 4,
        "text": {
          "en": "People's governments at all levels shall take measures to prevent and curb acts of unfair competition and to create a sound environment and conditions for fair competition.\nThe State Council shall establish and improve a coordination mechanism for anti-unfair competition work to coordinate and address major issues in maintaining the order of market competition."
        },
        "noLabel": {
          "en": "Article 4."
        }
      },
      {
        "no": 5,
        "text": {
          "en": "The department performing the functions of market supervision and administration under the people's government at or above the county level shall supervise and inspect acts of unfair competition; where laws and administrative regulations provide that other departments shall conduct supervision and inspection, those provisions shall prevail."
        },
        "noLabel": {
          "en": "Article 5."
        }
      },
      {
        "no": 6,
        "text": {
          "en": "The State encourages, supports and protects all organisations and individuals in exercising social supervision over acts of unfair competition.\nState organs and their staff members shall not support or shield acts of unfair competition.\nIndustry associations shall strengthen industry self-discipline, guide and regulate undertakings in their industries to compete in accordance with the law, and maintain the order of market competition."
        },
        "noLabel": {
          "en": "Article 6."
        }
      },
      {
        "no": 7,
        "text": {
          "en": "Undertakings shall not commit any of the following acts of confusion, causing others to mistake the goods for another's goods or to believe that a particular connection exists with another:\n(a) using without authorisation a mark that is identical or similar to the name, packaging, decoration or other mark of another's goods with a certain influence;\n(b) using without authorisation the name of another (including the abbreviated name, trade name, etc.) or the personal name of another (including pen name, stage name, online name, translated name, etc.) that has a certain influence;\n(c) using without authorisation the main part of a domain name, website name, web page, new media account name, application name or icon, etc. of another that has a certain influence;\n(d) other acts of confusion sufficient to cause others to mistake the goods for another's goods or to believe that a particular connection exists with another.\nUsing without authorisation another's registered trademark or unregistered well-known trademark as a trade name in an enterprise name, or setting another's goods name, enterprise name (including the abbreviated name, trade name, etc.), registered trademark, unregistered well-known trademark, etc. as search keywords, thereby causing others to mistake the goods for another's goods or to believe that a particular connection exists with another, shall constitute an act of confusion prescribed in the preceding paragraph.\nUndertakings shall not provide assistance to others in committing acts of confusion."
        },
        "noLabel": {
          "en": "Article 7."
        },
        "chapter": {
          "en": "Chapter II Acts of Unfair Competition"
        }
      },
      {
        "no": 8,
        "text": {
          "en": "Undertakings shall not offer property or adopt other means to bribe any of the following units or individuals in order to obtain trading opportunities or competitive advantages:\n(a) staff members of the trading counterparty;\n(b) units or individuals entrusted by the trading counterparty to handle the relevant affairs;\n(c) units or individuals that use their authority or influence to affect a transaction.\nUnits and individuals prescribed in the preceding paragraph shall not accept bribes.\nIn trading activities, an undertaking may pay a discount to the trading counterparty or a commission to an intermediary in an express manner. Where an undertaking pays a discount to the trading counterparty or a commission to an intermediary, it shall truthfully enter the payment in its accounts. An undertaking that accepts a discount or commission shall also truthfully enter it in its accounts.\nWhere a staff member of an undertaking commits bribery, the act shall be attributed to the undertaking; except where the undertaking has evidence proving that the act of the staff member is unrelated to obtaining trading opportunities or competitive advantages for the undertaking."
        },
        "noLabel": {
          "en": "Article 8."
        },
        "chapter": {
          "en": "Chapter II Acts of Unfair Competition"
        }
      },
      {
        "no": 9,
        "text": {
          "en": "Undertakings shall not make false or misleading commercial publicity in respect of the performance, functions, quality, sales status, user reviews, honours received or other aspects of their goods, thereby deceiving or misleading consumers and other undertakings.\nUndertakings shall not, by organising false transactions, false reviews or other means, provide assistance to other undertakings in making false or misleading commercial publicity."
        },
        "noLabel": {
          "en": "Article 9."
        },
        "chapter": {
          "en": "Chapter II Acts of Unfair Competition"
        }
      },
      {
        "no": 10,
        "text": {
          "en": "Undertakings shall not commit any of the following acts of infringement of trade secrets:\n(a) obtaining the trade secret of the right holder by theft, bribery, fraud, duress, electronic intrusion or other improper means;\n(b) disclosing, using or allowing others to use the trade secret of the right holder obtained by the means prescribed in the preceding subparagraph;\n(c) in breach of a duty of confidentiality or in breach of the right holder's requirements on keeping the trade secret confidential, disclosing, using or allowing others to use the trade secret in its possession;\n(d) instigating, inducing or assisting others to breach a duty of confidentiality or the right holder's requirements on keeping the trade secret confidential, so as to obtain, disclose, use or allow others to use the trade secret of the right holder.\nWhere natural persons, legal persons or unincorporated organisations other than undertakings commit any of the illegal acts listed in the preceding paragraph, the act shall be deemed an infringement of trade secrets.\nWhere a third party, knowing or that ought to know that an employee, former employee or other unit or individual of the trade secret right holder is committing an illegal act listed in paragraph 1 of this Article, still obtains, discloses, uses or allows others to use the trade secret, the act shall be deemed an infringement of trade secrets.\nThe term 'trade secret' as used in this Law refers to technical information, business information and other commercial information that is not known to the public, has commercial value, and in respect of which the right holder has taken corresponding measures to keep it confidential."
        },
        "noLabel": {
          "en": "Article 10."
        },
        "chapter": {
          "en": "Chapter II Acts of Unfair Competition"
        }
      },
      {
        "no": 11,
        "text": {
          "en": "Undertakings conducting prize-giving sales shall not be in any of the following circumstances:\n(a) the information on the prize-giving sales, such as the types of prizes offered, the conditions for claiming prizes, the amount of prize money or the prizes, is unclear and affects the claiming of prizes;\n(b) after the prize-giving sales activity begins, the information on the prize-giving sales, such as the types of prizes offered, the conditions for claiming prizes, the amount of prize money or the prizes, is changed without justified reasons;\n(c) prize-giving sales are conducted by deceptive means such as falsely claiming that prizes are offered or deliberately letting predetermined persons win prizes;\n(d) in lottery-attached prize-giving sales, the value of the highest prize exceeds RMB 50,000."
        },
        "noLabel": {
          "en": "Article 11."
        },
        "chapter": {
          "en": "Chapter II Acts of Unfair Competition"
        }
      },
      {
        "no": 12,
        "text": {
          "en": "Undertakings shall not fabricate or disseminate, or instruct others to fabricate or disseminate, false or misleading information to damage the business reputation or goods reputation of other undertakings."
        },
        "noLabel": {
          "en": "Article 12."
        },
        "chapter": {
          "en": "Chapter II Acts of Unfair Competition"
        }
      },
      {
        "no": 13,
        "text": {
          "en": "Undertakings that use networks to engage in production and business activities shall comply with the provisions of this Law.\nUndertakings shall not, by taking advantage of data and algorithms, technology, platform rules, etc., through affecting the user's choice or by other means, commit any of the following acts that obstruct or disrupt the normal operation of network products or services lawfully provided by other undertakings:\n(a) without the consent of another undertaking, inserting links into, or forcing target jumps in, the network products or services lawfully provided by that undertaking;\n(b) misleading, deceiving or compelling users to modify, close or uninstall network products or services lawfully provided by other undertakings;\n(c) maliciously implementing incompatibility with network products or services lawfully provided by other undertakings;\n(d) other acts that obstruct or disrupt the normal operation of network products or services lawfully provided by other undertakings.\nUndertakings shall not, by fraud, duress, circumventing or destroying technical management measures or other improper means, obtain or use data lawfully held by other undertakings, damage the lawful rights and interests of other undertakings, or disrupt the order of market competition.\nUndertakings shall not abuse platform rules to directly commit, or instruct others to commit, acts such as false transactions, false reviews or malicious returns against other undertakings, thereby damaging the lawful rights and interests of other undertakings and disrupting the order of market competition."
        },
        "noLabel": {
          "en": "Article 13."
        },
        "chapter": {
          "en": "Chapter II Acts of Unfair Competition"
        }
      },
      {
        "no": 14,
        "text": {
          "en": "Platform operators shall not compel, or compel in a disguised form, undertakings operating on the platform to sell goods at prices below cost in accordance with their pricing rules, thereby disrupting the order of market competition."
        },
        "noLabel": {
          "en": "Article 14."
        },
        "chapter": {
          "en": "Chapter II Acts of Unfair Competition"
        }
      },
      {
        "no": 15,
        "text": {
          "en": "Large enterprises and other undertakings shall not abuse their advantageous position in respect of capital, technology, trading channels, industry influence or other aspects to require small and medium-sized enterprises to accept obviously unreasonable trading conditions such as payment terms, payment methods, conditions and liability for breach of contract, or to delay payment of accounts for goods, projects or services owed to small and medium-sized enterprises."
        },
        "noLabel": {
          "en": "Article 15."
        },
        "chapter": {
          "en": "Chapter II Acts of Unfair Competition"
        }
      },
      {
        "no": 16,
        "text": {
          "en": "When investigating a suspected act of unfair competition, the department for supervision and inspection may take the following measures:\n(a) entering the business premises where the suspected act of unfair competition is committed to conduct an inspection;\n(b) questioning the investigated undertaking, interested parties and other relevant units or individuals, and requiring them to explain the relevant circumstances or provide other materials related to the investigated act;\n(c) consulting and copying agreements, accounting books, vouchers, documents, records, business correspondence and other materials related to the suspected act of unfair competition;\n(d) sealing up and seizing property related to the suspected act of unfair competition;\n(e) inquiring into the bank accounts of the undertaking suspected of committing the act of unfair competition.\nTo take the measures prescribed in the preceding paragraph, a written report shall be submitted to the principal person in charge of the department for supervision and inspection and approval shall be obtained. To take the measures prescribed in subparagraphs (d) and (e) of the preceding paragraph, a written report shall be submitted to the principal person in charge of the department for supervision and inspection under the people's government at or above the level of a city divided into districts and approval shall be obtained.\nWhen investigating a suspected act of unfair competition, the department for supervision and inspection shall comply with the provisions of the Administrative Compulsion Law of the People's Republic of China and other relevant laws and administrative regulations, and shall, in accordance with the law, promptly make the results of investigation and handling public."
        },
        "noLabel": {
          "en": "Article 16."
        },
        "chapter": {
          "en": "Chapter III Investigation of Suspected Acts of Unfair Competition"
        }
      },
      {
        "no": 17,
        "text": {
          "en": "When the department for supervision and inspection investigates a suspected act of unfair competition, the investigated undertaking, interested parties and other relevant units or individuals shall truthfully provide the relevant materials or information."
        },
        "noLabel": {
          "en": "Article 17."
        },
        "chapter": {
          "en": "Chapter III Investigation of Suspected Acts of Unfair Competition"
        }
      },
      {
        "no": 18,
        "text": {
          "en": "Where an undertaking is suspected of violating the provisions of this Law, the department for supervision and inspection may conduct a regulatory talk with its responsible persons, requiring them to explain the circumstances and propose corrective measures."
        },
        "noLabel": {
          "en": "Article 18."
        },
        "chapter": {
          "en": "Chapter III Investigation of Suspected Acts of Unfair Competition"
        }
      },
      {
        "no": 19,
        "text": {
          "en": "The department for supervision and inspection and its staff members shall, in accordance with the law, bear a duty of confidentiality in respect of trade secrets, personal privacy and personal information learned in the course of investigation."
        },
        "noLabel": {
          "en": "Article 19."
        },
        "chapter": {
          "en": "Chapter III Investigation of Suspected Acts of Unfair Competition"
        }
      },
      {
        "no": 20,
        "text": {
          "en": "In respect of a suspected act of unfair competition, any unit or individual shall be entitled to report it to the department for supervision and inspection, and the department for supervision and inspection shall, after receiving the report, handle it promptly in accordance with the law.\nThe department for supervision and inspection shall make public the telephone number, mailing address or email address for accepting reports, and shall keep the identity of informants confidential. Where a report is made under a real name and the relevant facts and evidence are provided, the department for supervision and inspection shall promptly inform the informant of the result of handling."
        },
        "noLabel": {
          "en": "Article 20."
        },
        "chapter": {
          "en": "Chapter III Investigation of Suspected Acts of Unfair Competition"
        }
      },
      {
        "no": 21,
        "text": {
          "en": "Platform operators shall specify the rules for fair competition on the platform in the platform service agreement and trading rules, establish mechanisms for receiving reports and complaints of unfair competition and for resolving disputes, and guide and regulate undertakings operating on the platform to compete fairly in accordance with the law; where they discover that an undertaking operating on the platform is committing an act of unfair competition, they shall promptly take the necessary disposal measures in accordance with the law, keep the relevant records, and report to the department for supervision and inspection under the people's government at or above the county level at the place of their domicile as required."
        },
        "noLabel": {
          "en": "Article 21."
        },
        "chapter": {
          "en": "Chapter III Investigation of Suspected Acts of Unfair Competition"
        }
      },
      {
        "no": 22,
        "text": {
          "en": "Where an undertaking violates the provisions of this Law and causes damage to others, it shall bear civil liability in accordance with the law.\nWhere the lawful rights and interests of an undertaking are damaged by an act of unfair competition, it may bring a lawsuit before the people's court.\nThe amount of compensation for an undertaking damaged by an act of unfair competition shall be determined on the basis of the actual loss suffered by it as a result of the infringement or the benefit obtained by the infringer from the infringement. Where an undertaking intentionally commits an act of infringement of trade secrets and the circumstances are serious, the amount of compensation may be determined at not less than one time but not more than five times the amount determined in accordance with the above methods. The amount of compensation shall also include the reasonable expenses paid by the undertaking to stop the infringement.\nWhere an undertaking violates Article 7 or Article 10 of this Law and the actual loss suffered by the right holder as a result of the infringement or the benefit obtained by the infringer from the infringement is difficult to determine, the people's court shall, in light of the circumstances of the infringement, make a judgment awarding compensation of not more than RMB 5,000,000 to the right holder."
        },
        "noLabel": {
          "en": "Article 22."
        },
        "chapter": {
          "en": "Chapter IV Legal Liability"
        }
      },
      {
        "no": 23,
        "text": {
          "en": "Where an undertaking, in violation of Article 7 of this Law, commits an act of confusion or assists others in committing an act of confusion, the department for supervision and inspection shall order it to cease the illegal act and confiscate the illegal goods. Where the illegal turnover is RMB 50,000 or more, a fine of not more than five times the illegal turnover may also be imposed; where there is no illegal turnover or the illegal turnover is less than RMB 50,000, a fine of not more than RMB 250,000 may also be imposed; where the circumstances are serious, its business licence shall also be revoked.\nWhere illegal goods prescribed in Article 7 of this Law are sold, the seller shall be penalised in accordance with the provisions of the preceding paragraph; where the seller does not know that the goods it sells are illegal goods and can prove that it lawfully obtained the goods and can identify the supplier, the department for supervision and inspection shall order it to cease selling the goods and shall not impose an administrative penalty.\nWhere the name registered by an undertaking violates Article 7 of this Law, it shall promptly complete the registration of a change of name; before the name is changed, the registration authority shall replace its name with the unified social credit code."
        },
        "noLabel": {
          "en": "Article 23."
        },
        "chapter": {
          "en": "Chapter IV Legal Liability"
        }
      },
      {
        "no": 24,
        "text": {
          "en": "Where a relevant unit, in violation of Article 8 of this Law, bribes another or accepts a bribe, the department for supervision and inspection shall confiscate its illegal gains and impose a fine of not less than RMB 100,000 but not more than RMB 1,000,000; where the circumstances are serious, a fine of not less than RMB 1,000,000 but not more than RMB 5,000,000 shall be imposed, and its business licence may also be revoked.\nWhere the legal representative, the principal person in charge or the person directly responsible of an undertaking bears personal responsibility for committing bribery, or where a relevant individual accepts a bribe, the department for supervision and inspection shall confiscate the illegal gains and impose a fine of not more than RMB 1,000,000."
        },
        "noLabel": {
          "en": "Article 24."
        },
        "chapter": {
          "en": "Chapter IV Legal Liability"
        }
      },
      {
        "no": 25,
        "text": {
          "en": "Where an undertaking, in violation of Article 9 of this Law, makes false or misleading commercial publicity in respect of its goods, or assists other undertakings in making false or misleading commercial publicity by organising false transactions, false reviews or other means, the department for supervision and inspection shall order it to cease the illegal act and impose a fine of not more than RMB 1,000,000; where the circumstances are serious, a fine of not less than RMB 1,000,000 but not more than RMB 2,000,000 shall be imposed, and its business licence may also be revoked.\nWhere an undertaking violates Article 9 of this Law and the act constitutes the publication of false advertising, it shall be penalised in accordance with the provisions of the Advertising Law of the People's Republic of China."
        },
        "noLabel": {
          "en": "Article 25."
        },
        "chapter": {
          "en": "Chapter IV Legal Liability"
        }
      },
      {
        "no": 26,
        "text": {
          "en": "Where an undertaking or any other natural person, legal person or unincorporated organisation, in violation of Article 10 of this Law, infringes a trade secret, the department for supervision and inspection shall order it to cease the illegal act, confiscate its illegal gains and impose a fine of not less than RMB 100,000 but not more than RMB 1,000,000; where the circumstances are serious, a fine of not less than RMB 1,000,000 but not more than RMB 5,000,000 shall be imposed."
        },
        "noLabel": {
          "en": "Article 26."
        },
        "chapter": {
          "en": "Chapter IV Legal Liability"
        }
      },
      {
        "no": 27,
        "text": {
          "en": "Where an undertaking, in violation of Article 11 of this Law, conducts prize-giving sales, the department for supervision and inspection shall order it to cease the illegal act and impose a fine of not less than RMB 50,000 but not more than RMB 500,000."
        },
        "noLabel": {
          "en": "Article 27."
        },
        "chapter": {
          "en": "Chapter IV Legal Liability"
        }
      },
      {
        "no": 28,
        "text": {
          "en": "Where an undertaking, in violation of Article 12 of this Law, damages the business reputation or goods reputation of another undertaking, the department for supervision and inspection shall order it to cease the illegal act and eliminate the effects, and impose a fine of not less than RMB 100,000 but not more than RMB 1,000,000; where the circumstances are serious, a fine of not less than RMB 1,000,000 but not more than RMB 5,000,000 shall be imposed."
        },
        "noLabel": {
          "en": "Article 28."
        },
        "chapter": {
          "en": "Chapter IV Legal Liability"
        }
      },
      {
        "no": 29,
        "text": {
          "en": "Where an undertaking, in violation of paragraph 2, paragraph 3 or paragraph 4 of Article 13 of this Law, uses networks to engage in unfair competition, the department for supervision and inspection shall order it to cease the illegal act and impose a fine of not less than RMB 100,000 but not more than RMB 1,000,000; where the circumstances are serious, a fine of not less than RMB 1,000,000 but not more than RMB 5,000,000 shall be imposed."
        },
        "noLabel": {
          "en": "Article 29."
        },
        "chapter": {
          "en": "Chapter IV Legal Liability"
        }
      },
      {
        "no": 30,
        "text": {
          "en": "Where a platform operator, in violation of Article 14 of this Law, compels, or compels in a disguised form, undertakings operating on the platform to sell goods at prices below cost, the department for supervision and inspection shall order it to cease the illegal act and impose a fine of not less than RMB 50,000 but not more than RMB 500,000; where the circumstances are serious, a fine of not less than RMB 500,000 but not more than RMB 2,000,000 shall be imposed."
        },
        "noLabel": {
          "en": "Article 30."
        },
        "chapter": {
          "en": "Chapter IV Legal Liability"
        }
      },
      {
        "no": 31,
        "text": {
          "en": "Where an undertaking, in violation of Article 15 of this Law, abuses its advantageous position, the department for supervision and inspection under the people's government at or above the provincial level shall order it to make corrections within a time limit; where it fails to make corrections within the time limit, a fine of not more than RMB 1,000,000 shall be imposed; where the circumstances are serious, a fine of not less than RMB 1,000,000 but not more than RMB 5,000,000 shall be imposed."
        },
        "noLabel": {
          "en": "Article 31."
        },
        "chapter": {
          "en": "Chapter IV Legal Liability"
        }
      },
      {
        "no": 32,
        "text": {
          "en": "Where an undertaking, in violation of the provisions of this Law, engages in unfair competition and there are statutory circumstances such as voluntarily eliminating or mitigating the harmful consequences of the illegal act, it shall be given a lighter or mitigated administrative penalty in accordance with the law; where the illegal act is minor and is corrected promptly and no harmful consequences are caused, no administrative penalty shall be imposed."
        },
        "noLabel": {
          "en": "Article 32."
        },
        "chapter": {
          "en": "Chapter IV Legal Liability"
        }
      },
      {
        "no": 33,
        "text": {
          "en": "Where an undertaking, in violation of the provisions of this Law, engages in unfair competition and is given an administrative penalty, the department for supervision and inspection shall record the matter in its credit record and make it public in accordance with the provisions of the relevant laws and administrative regulations."
        },
        "noLabel": {
          "en": "Article 33."
        },
        "chapter": {
          "en": "Chapter IV Legal Liability"
        }
      },
      {
        "no": 34,
        "text": {
          "en": "Where an undertaking violates the provisions of this Law and shall bear civil liability, administrative liability and criminal liability, and its property is insufficient to pay all of them, the property shall be applied first to bearing civil liability."
        },
        "noLabel": {
          "en": "Article 34."
        },
        "chapter": {
          "en": "Chapter IV Legal Liability"
        }
      },
      {
        "no": 35,
        "text": {
          "en": "Where a person obstructs the department for supervision and inspection in performing its duties in accordance with this Law and refuses or obstructs an investigation, the department for supervision and inspection shall order it to make corrections and may impose on an individual a fine of not more than RMB 10,000 and on a unit a fine of not more than RMB 100,000."
        },
        "noLabel": {
          "en": "Article 35."
        },
        "chapter": {
          "en": "Chapter IV Legal Liability"
        }
      },
      {
        "no": 36,
        "text": {
          "en": "Where a party is dissatisfied with a decision made by the department for supervision and inspection, it may apply for administrative reconsideration or initiate administrative litigation in accordance with the law."
        },
        "noLabel": {
          "en": "Article 36."
        },
        "chapter": {
          "en": "Chapter IV Legal Liability"
        }
      },
      {
        "no": 37,
        "text": {
          "en": "Where a staff member of the department for supervision and inspection abuses power, neglects duty, commits malpractices for personal gain, or discloses trade secrets, personal privacy or personal information learned in the course of investigation, sanctions shall be given in accordance with the law."
        },
        "noLabel": {
          "en": "Article 37."
        },
        "chapter": {
          "en": "Chapter IV Legal Liability"
        }
      },
      {
        "no": 38,
        "text": {
          "en": "Where the provisions of this Law are violated and the act constitutes a violation of public security administration, a public security administration penalty shall be imposed in accordance with the law; where a crime is constituted, criminal responsibility shall be pursued in accordance with the law."
        },
        "noLabel": {
          "en": "Article 38."
        },
        "chapter": {
          "en": "Chapter IV Legal Liability"
        }
      },
      {
        "no": 39,
        "text": {
          "en": "In civil trial proceedings concerning the infringement of a trade secret, where the trade secret right holder provides prima facie evidence proving that it has taken measures to keep the claimed trade secret confidential and reasonably indicating that the trade secret has been infringed, the suspected infringer shall prove that the trade secret claimed by the right holder is not a trade secret as referred to in this Law.\nWhere the trade secret right holder provides prima facie evidence reasonably indicating that the trade secret has been infringed and provides any of the following evidence, the suspected infringer shall prove that it has not committed an act of infringement of the trade secret:\n(a) evidence showing that the suspected infringer has a channel or opportunity to obtain the trade secret, and that the information used by it is substantially the same as the trade secret;\n(b) evidence showing that the trade secret has been disclosed or used by the suspected infringer, or is at risk of being disclosed or used;\n(c) other evidence showing that the trade secret has been infringed by the suspected infringer."
        },
        "noLabel": {
          "en": "Article 39."
        },
        "chapter": {
          "en": "Chapter IV Legal Liability"
        }
      },
      {
        "no": 40,
        "text": {
          "en": "Where an act of unfair competition prescribed in this Law is committed outside the territory of the People's Republic of China, disrupting the order of domestic market competition and damaging the lawful rights and interests of domestic undertakings or consumers, it shall be dealt with in accordance with this Law and the provisions of the relevant laws."
        },
        "noLabel": {
          "en": "Article 40."
        },
        "chapter": {
          "en": "Chapter V Supplementary Provisions"
        }
      },
      {
        "no": 41,
        "text": {
          "en": "This Law shall come into force on 15 October 2025."
        },
        "noLabel": {
          "en": "Article 41."
        },
        "chapter": {
          "en": "Chapter V Supplementary Provisions"
        }
      }
    ]
  };

  TR['CN-LAW-0093'] = {
    "lawId": "CN-LAW-0093",
    "sourceLang": "zh",
    "targetLang": "en",
    "engine": "llm",
    "model": "deepseek-v4.1-flash",
    "promptVersion": "calr-trans-v2",
    "translatedAt": "2026-10-14",
    "reviewed": "machine",
    "glossaryVersion": "calr-terms-2026-10-v2",
    "completenessNote": "逐条对译，共 70 条；条号与官方原文一一对应，未合并、未省略。",
    "articles": [
      {
        "no": 1,
        "text": {
          "en": "This Law is enacted for the purpose of preventing and curbing monopolistic conduct, protecting fair market competition, encouraging innovation, improving the efficiency of economic operation, safeguarding the interests of consumers and the public interest of society, and promoting the sound development of the socialist market economy."
        },
        "noLabel": {
          "en": "Article 1."
        }
      },
      {
        "no": 2,
        "text": {
          "en": "Monopolistic conduct in economic activities within the territory of the People's Republic of China shall be governed by this Law; monopolistic conduct outside the territory of the People's Republic of China that has the effect of eliminating or restricting competition in the domestic market shall also be governed by this Law."
        },
        "noLabel": {
          "en": "Article 2."
        }
      },
      {
        "no": 3,
        "text": {
          "en": "The monopolistic conduct prescribed by this Law includes:\n(a) undertakings reaching a monopoly agreement;\n(b) undertakings abusing a dominant market position;\n(c) concentration of undertakings that has or may have the effect of eliminating or restricting competition."
        },
        "noLabel": {
          "en": "Article 3."
        }
      },
      {
        "no": 4,
        "text": {
          "en": "Anti-monopoly work shall adhere to the leadership of the Communist Party of China.\nThe State shall adhere to the principles of market orientation and the rule of law, strengthen the fundamental position of competition policy, formulate and implement competition rules suited to the socialist market economy, improve macro-regulation, and develop a unified, open, competitive and orderly market system."
        },
        "noLabel": {
          "en": "Article 4."
        }
      },
      {
        "no": 5,
        "text": {
          "en": "The State shall establish and improve the fair competition review system.\nAdministrative organs and organisations authorised by laws and regulations to perform the function of administering public affairs shall conduct fair competition reviews when formulating provisions involving the economic activities of market entities."
        },
        "noLabel": {
          "en": "Article 5."
        }
      },
      {
        "no": 6,
        "text": {
          "en": "An undertaking may, through fair competition and voluntary association, implement a concentration in accordance with the law so as to expand the scale of its operations and enhance its market competitiveness."
        },
        "noLabel": {
          "en": "Article 6."
        }
      },
      {
        "no": 7,
        "text": {
          "en": "An undertaking with a dominant market position shall not abuse its dominant market position to eliminate or restrict competition."
        },
        "noLabel": {
          "en": "Article 7."
        }
      },
      {
        "no": 8,
        "text": {
          "en": "In respect of industries that are vital to the lifeline of the national economy and to national security and in which the State-owned economy occupies a controlling position, and industries in which exclusive operation and exclusive sale are practised in accordance with the law, the State shall protect the lawful business activities of the undertakings operating therein and shall, in accordance with the law, supervise and regulate the business conduct of such undertakings and the prices of their goods and services, so as to safeguard the interests of consumers and promote technological progress.\nUndertakings in the industries prescribed in the preceding paragraph shall operate in accordance with the law, act honestly and in good faith, exercise strict self-discipline and accept supervision by the public, and shall not take advantage of their controlling position or their position of exclusive operation and exclusive sale to harm the interests of consumers."
        },
        "noLabel": {
          "en": "Article 8."
        }
      },
      {
        "no": 9,
        "text": {
          "en": "Undertakings shall not take advantage of data, algorithms, technology, capital advantages, platform rules or other such means to engage in monopolistic conduct prohibited by this Law."
        },
        "noLabel": {
          "en": "Article 9."
        }
      },
      {
        "no": 10,
        "text": {
          "en": "Administrative organs and organisations authorised by laws and regulations to perform the function of administering public affairs shall not abuse administrative power to eliminate or restrict competition."
        },
        "noLabel": {
          "en": "Article 10."
        }
      },
      {
        "no": 11,
        "text": {
          "en": "The State shall improve and perfect anti-monopoly rules and institutions, strengthen anti-monopoly regulatory capacity, raise the level of regulatory capability and the modernisation of the regulatory system, strengthen anti-monopoly enforcement and judicial work, fairly and efficiently hear monopoly cases in accordance with the law, improve the mechanism for linking administrative enforcement with the administration of justice, and maintain the order of fair competition."
        },
        "noLabel": {
          "en": "Article 11."
        }
      },
      {
        "no": 12,
        "text": {
          "en": "The Anti-Monopoly Commission under the State Council shall be established to organise, coordinate and guide anti-monopoly work and shall perform the following duties:\n(a) studying and drafting relevant competition policies;\n(b) organising investigations and assessments of the overall state of market competition and publishing assessment reports;\n(c) formulating and publishing anti-monopoly guidelines;\n(d) coordinating administrative anti-monopoly enforcement work;\n(e) other duties prescribed by the State Council.\nThe composition and working rules of the Anti-Monopoly Commission under the State Council shall be prescribed by the State Council."
        },
        "noLabel": {
          "en": "Article 12."
        }
      },
      {
        "no": 13,
        "text": {
          "en": "The anti-monopoly enforcement authority under the State Council shall be responsible for unified anti-monopoly enforcement work.\nThe anti-monopoly enforcement authority under the State Council may, as required by its work, authorise the corresponding institutions of the people's governments of provinces, autonomous regions and municipalities directly under the Central Government to be responsible for the relevant anti-monopoly enforcement work in accordance with the provisions of this Law."
        },
        "noLabel": {
          "en": "Article 13."
        }
      },
      {
        "no": 14,
        "text": {
          "en": "Industry associations shall strengthen industry self-discipline, guide undertakings in their industries to compete in accordance with the law and to operate in compliance with the law, and maintain the order of market competition."
        },
        "noLabel": {
          "en": "Article 14."
        }
      },
      {
        "no": 15,
        "text": {
          "en": "The term 'undertaking' as used in this Law refers to a natural person, legal person or unincorporated organisation that engages in the production or operation of goods or the provision of services.\nThe term 'relevant market' as used in this Law refers to the scope of goods and the scope of territory within which undertakings compete in respect of particular goods or services (hereinafter collectively referred to as goods) during a certain period."
        },
        "noLabel": {
          "en": "Article 15."
        }
      },
      {
        "no": 16,
        "text": {
          "en": "The term 'monopoly agreement' as used in this Law refers to an agreement, decision or other concerted practice that eliminates or restricts competition."
        },
        "noLabel": {
          "en": "Article 16."
        },
        "chapter": {
          "en": "Chapter II Monopoly Agreements"
        }
      },
      {
        "no": 17,
        "text": {
          "en": "Undertakings that have a competitive relationship are prohibited from reaching the following monopoly agreements:\n(a) fixing or changing the prices of goods;\n(b) restricting the quantity of goods produced or sold;\n(c) dividing the sales market or the market for the procurement of raw materials;\n(d) restricting the purchase of new technology or new equipment, or restricting the development of new technology or new products;\n(e) jointly boycotting transactions;\n(f) other monopoly agreements as determined by the anti-monopoly enforcement authority under the State Council."
        },
        "noLabel": {
          "en": "Article 17."
        },
        "chapter": {
          "en": "Chapter II Monopoly Agreements"
        }
      },
      {
        "no": 18,
        "text": {
          "en": "Undertakings are prohibited from reaching the following monopoly agreements with their trading counterparties:\n(a) fixing the price at which goods are resold to a third party;\n(b) setting a minimum price at which goods are resold to a third party;\n(c) other monopoly agreements as determined by the anti-monopoly enforcement authority under the State Council.\nWhere an undertaking can prove that an agreement prescribed in subparagraphs (a) and (b) of the preceding paragraph does not have the effect of eliminating or restricting competition, the agreement shall not be prohibited.\nWhere an undertaking can prove that its market share in the relevant market is below the threshold prescribed by the anti-monopoly enforcement authority under the State Council and that it meets the other conditions prescribed by that authority, the agreement shall not be prohibited."
        },
        "noLabel": {
          "en": "Article 18."
        },
        "chapter": {
          "en": "Chapter II Monopoly Agreements"
        }
      },
      {
        "no": 19,
        "text": {
          "en": "Undertakings shall not organise other undertakings to reach a monopoly agreement or provide substantive assistance to other undertakings in reaching a monopoly agreement."
        },
        "noLabel": {
          "en": "Article 19."
        },
        "chapter": {
          "en": "Chapter II Monopoly Agreements"
        }
      },
      {
        "no": 20,
        "text": {
          "en": "Where an undertaking can prove that an agreement reached falls under any of the following circumstances, the provisions of Article 17, paragraph 1 of Article 18 and Article 19 of this Law shall not apply:\n(a) the agreement is for the purpose of improving technology or researching and developing new products;\n(b) the agreement is for the purpose of improving product quality, reducing costs or improving efficiency, unifying product specifications or standards, or implementing a specialisation of division of labour;\n(c) the agreement is for the purpose of improving the operating efficiency of small and medium-sized undertakings and enhancing their competitiveness;\n(d) the agreement is for the purpose of achieving public interests such as energy conservation, environmental protection, disaster relief and assistance;\n(e) in a period of economic downturn, the agreement serves to ease a serious decline in sales volume or obvious overproduction;\n(f) the agreement is for the purpose of safeguarding legitimate interests in foreign trade and foreign economic cooperation;\n(g) other circumstances prescribed by laws and by the State Council.\nWhere an agreement falls under any of the circumstances in subparagraphs (a) to (e) of the preceding paragraph and the provisions of Article 17, paragraph 1 of Article 18 and Article 19 of this Law are not applied, the undertaking shall also prove that the agreement will not seriously restrict competition in the relevant market and that consumers will be able to share in the benefits arising therefrom."
        },
        "noLabel": {
          "en": "Article 20."
        },
        "chapter": {
          "en": "Chapter II Monopoly Agreements"
        }
      },
      {
        "no": 21,
        "text": {
          "en": "Industry associations shall not organise undertakings in their industries to engage in monopolistic conduct prohibited by this Chapter."
        },
        "noLabel": {
          "en": "Article 21."
        },
        "chapter": {
          "en": "Chapter II Monopoly Agreements"
        }
      },
      {
        "no": 22,
        "text": {
          "en": "Undertakings with a dominant market position are prohibited from engaging in the following conduct of abusing a dominant market position:\n(a) selling goods at unfairly high prices or purchasing goods at unfairly low prices;\n(b) without justified reasons, selling goods at prices below cost;\n(c) without justified reasons, refusing to trade with a trading counterparty;\n(d) without justified reasons, restricting a trading counterparty to trading only with itself or only with undertakings designated by it;\n(e) without justified reasons, tying goods or imposing other unreasonable trading conditions in a transaction;\n(f) without justified reasons, applying differential treatment to trading counterparties with identical conditions in respect of trading prices and other trading conditions;\n(g) other conduct of abusing a dominant market position as determined by the anti-monopoly enforcement authority under the State Council.\nUndertakings with a dominant market position shall not take advantage of data, algorithms, technology, platform rules or other such means to engage in the conduct of abusing a dominant market position prescribed in the preceding paragraph.\nThe term 'dominant market position' as used in this Law refers to a market position in which an undertaking has the ability, in the relevant market, to control the prices, quantities or other trading conditions of goods, or to hinder or affect the ability of other undertakings to enter the relevant market."
        },
        "noLabel": {
          "en": "Article 22."
        },
        "chapter": {
          "en": "Chapter III Abuse of a Dominant Market Position"
        }
      },
      {
        "no": 23,
        "text": {
          "en": "In determining whether an undertaking has a dominant market position, the following factors shall be taken into account:\n(a) the market share of the undertaking in the relevant market and the state of competition in the relevant market;\n(b) the ability of the undertaking to control the sales market or the market for the procurement of raw materials;\n(c) the financial and technical conditions of the undertaking;\n(d) the degree of dependence of other undertakings on the undertaking in transactions;\n(e) the degree of difficulty for other undertakings to enter the relevant market;\n(f) other factors relevant to determining the dominant market position of the undertaking."
        },
        "noLabel": {
          "en": "Article 23."
        },
        "chapter": {
          "en": "Chapter III Abuse of a Dominant Market Position"
        }
      },
      {
        "no": 24,
        "text": {
          "en": "Under any of the following circumstances, an undertaking may be presumed to have a dominant market position:\n(a) the market share of one undertaking in the relevant market reaches one half;\n(b) the combined market share of two undertakings in the relevant market reaches two thirds;\n(c) the combined market share of three undertakings in the relevant market reaches three quarters.\nWhere the circumstances prescribed in subparagraphs (b) and (c) of the preceding paragraph exist and the market share of any of the undertakings is less than one tenth, that undertaking shall not be presumed to have a dominant market position.\nWhere an undertaking presumed to have a dominant market position proves, on the basis of evidence, that it does not have a dominant market position, it shall not be determined to have a dominant market position."
        },
        "noLabel": {
          "en": "Article 24."
        },
        "chapter": {
          "en": "Chapter III Abuse of a Dominant Market Position"
        }
      },
      {
        "no": 25,
        "text": {
          "en": "Concentration of undertakings means any of the following circumstances:\n(a) a merger of undertakings;\n(b) an undertaking acquiring control over another undertaking by acquiring equity or assets;\n(c) an undertaking acquiring control over another undertaking, or being able to exercise a decisive influence over another undertaking, by means of a contract or otherwise."
        },
        "noLabel": {
          "en": "Article 25."
        },
        "chapter": {
          "en": "Chapter IV Concentration of Undertakings"
        }
      },
      {
        "no": 26,
        "text": {
          "en": "Where a concentration of undertakings reaches the declaration threshold prescribed by the State Council, the undertakings shall declare the concentration to the anti-monopoly enforcement authority under the State Council in advance, and a concentration that has not been declared shall not be implemented.\nWhere a concentration of undertakings does not reach the declaration threshold prescribed by the State Council, but there is evidence proving that the concentration has or may have the effect of eliminating or restricting competition, the anti-monopoly enforcement authority under the State Council may require the undertakings to declare the concentration.\nWhere undertakings fail to declare in accordance with the provisions of the preceding two paragraphs, the anti-monopoly enforcement authority under the State Council shall conduct an investigation in accordance with the law."
        },
        "noLabel": {
          "en": "Article 26."
        },
        "chapter": {
          "en": "Chapter IV Concentration of Undertakings"
        }
      },
      {
        "no": 27,
        "text": {
          "en": "Where a concentration of undertakings falls under any of the following circumstances, it need not be declared to the anti-monopoly enforcement authority under the State Council:\n(a) one of the undertakings participating in the concentration holds 50 per cent or more of the voting shares or assets of each of the other undertakings;\n(b) 50 per cent or more of the voting shares or assets of each of the undertakings participating in the concentration are held by the same undertaking that does not participate in the concentration."
        },
        "noLabel": {
          "en": "Article 27."
        },
        "chapter": {
          "en": "Chapter IV Concentration of Undertakings"
        }
      },
      {
        "no": 28,
        "text": {
          "en": "An undertaking declaring a concentration to the anti-monopoly enforcement authority under the State Council shall submit the following documents and materials:\n(a) a declaration form;\n(b) an explanation of the impact of the concentration on competition in the relevant market;\n(c) the concentration agreement;\n(d) the financial and accounting reports of the undertakings participating in the concentration for the preceding accounting year, audited by an accounting firm;\n(e) other documents and materials prescribed by the anti-monopoly enforcement authority under the State Council.\nThe declaration form shall state the names, domiciles and scope of business of the undertakings participating in the concentration, the scheduled date for implementing the concentration and other matters prescribed by the anti-monopoly enforcement authority under the State Council."
        },
        "noLabel": {
          "en": "Article 28."
        },
        "chapter": {
          "en": "Chapter IV Concentration of Undertakings"
        }
      },
      {
        "no": 29,
        "text": {
          "en": "Where the documents and materials submitted by an undertaking are incomplete, the undertaking shall supplement the documents and materials within the time limit prescribed by the anti-monopoly enforcement authority under the State Council. Where an undertaking fails to supplement the documents and materials within the time limit, it shall be deemed not to have declared."
        },
        "noLabel": {
          "en": "Article 29."
        },
        "chapter": {
          "en": "Chapter IV Concentration of Undertakings"
        }
      },
      {
        "no": 30,
        "text": {
          "en": "The anti-monopoly enforcement authority under the State Council shall, within 30 days from the date of receipt of the documents and materials submitted by the undertakings that comply with the provisions of Article 28 of this Law, conduct a preliminary review of the declared concentration of undertakings, decide whether to conduct a further review, and notify the undertakings in writing. Before the anti-monopoly enforcement authority under the State Council makes a decision, the undertakings shall not implement the concentration.\nWhere the anti-monopoly enforcement authority under the State Council decides not to conduct a further review or fails to make a decision within the time limit, the undertakings may implement the concentration."
        },
        "noLabel": {
          "en": "Article 30."
        },
        "chapter": {
          "en": "Chapter IV Concentration of Undertakings"
        }
      },
      {
        "no": 31,
        "text": {
          "en": "Where the anti-monopoly enforcement authority under the State Council decides to conduct a further review, it shall complete the review within 90 days from the date of the decision, decide whether to prohibit the concentration of undertakings, and notify the undertakings in writing. Where it decides to prohibit the concentration of undertakings, it shall state the reasons. During the review period, the undertakings shall not implement the concentration.\nUnder any of the following circumstances, the anti-monopoly enforcement authority under the State Council may, after notifying the undertakings in writing, extend the review period prescribed in the preceding paragraph, provided that the extension shall not exceed 60 days:\n(a) the undertakings agree to an extension of the review period;\n(b) the documents and materials submitted by the undertakings are inaccurate and further verification is required;\n(c) major changes occur in the relevant circumstances after the declaration by the undertakings.\nWhere the anti-monopoly enforcement authority under the State Council fails to make a decision within the time limit, the undertakings may implement the concentration."
        },
        "noLabel": {
          "en": "Article 31."
        },
        "chapter": {
          "en": "Chapter IV Concentration of Undertakings"
        }
      },
      {
        "no": 32,
        "text": {
          "en": "Under any of the following circumstances, the anti-monopoly enforcement authority under the State Council may decide to suspend the calculation of the review period for a concentration of undertakings and notify the undertakings in writing:\n(a) the undertakings fail to submit documents and materials as required, so that the review cannot proceed;\n(b) new circumstances or new facts that have a significant impact on the review of the concentration of undertakings arise, and the failure to verify them would make the review impossible;\n(c) the restrictive conditions to be attached to the concentration of undertakings require further assessment and the undertakings make a request for suspension.\nThe review period shall continue to be calculated from the date on which the circumstances for suspending the calculation of the review period are eliminated, and the anti-monopoly enforcement authority under the State Council shall notify the undertakings in writing."
        },
        "noLabel": {
          "en": "Article 32."
        },
        "chapter": {
          "en": "Chapter IV Concentration of Undertakings"
        }
      },
      {
        "no": 33,
        "text": {
          "en": "In reviewing a concentration of undertakings, the following factors shall be taken into account:\n(a) the market shares of the undertakings participating in the concentration in the relevant market and their degree of control over the market;\n(b) the degree of market concentration in the relevant market;\n(c) the impact of the concentration of undertakings on market entry and technological progress;\n(d) the impact of the concentration of undertakings on consumers and other relevant undertakings;\n(e) the impact of the concentration of undertakings on the development of the national economy;\n(f) other factors affecting market competition that the anti-monopoly enforcement authority under the State Council considers should be taken into account."
        },
        "noLabel": {
          "en": "Article 33."
        },
        "chapter": {
          "en": "Chapter IV Concentration of Undertakings"
        }
      },
      {
        "no": 34,
        "text": {
          "en": "Where a concentration of undertakings has or may have the effect of eliminating or restricting competition, the anti-monopoly enforcement authority under the State Council shall decide to prohibit the concentration. However, where the undertakings can prove that the positive effects of the concentration on competition clearly outweigh the negative effects, or that the concentration is in the public interest, the anti-monopoly enforcement authority under the State Council may decide not to prohibit the concentration of undertakings."
        },
        "noLabel": {
          "en": "Article 34."
        },
        "chapter": {
          "en": "Chapter IV Concentration of Undertakings"
        }
      },
      {
        "no": 35,
        "text": {
          "en": "For a concentration of undertakings that is not prohibited, the anti-monopoly enforcement authority under the State Council may decide to attach restrictive conditions that reduce the negative effects of the concentration on competition."
        },
        "noLabel": {
          "en": "Article 35."
        },
        "chapter": {
          "en": "Chapter IV Concentration of Undertakings"
        }
      },
      {
        "no": 36,
        "text": {
          "en": "The anti-monopoly enforcement authority under the State Council shall promptly make public the decision to prohibit a concentration of undertakings or the decision to attach restrictive conditions to a concentration of undertakings."
        },
        "noLabel": {
          "en": "Article 36."
        },
        "chapter": {
          "en": "Chapter IV Concentration of Undertakings"
        }
      },
      {
        "no": 37,
        "text": {
          "en": "The anti-monopoly enforcement authority under the State Council shall improve the categorised and tiered review system for concentrations of undertakings, strengthen in accordance with the law the review of concentrations of undertakings in important fields such as those vital to the national economy and the people's livelihood, and improve the quality and efficiency of review."
        },
        "noLabel": {
          "en": "Article 37."
        },
        "chapter": {
          "en": "Chapter IV Concentration of Undertakings"
        }
      },
      {
        "no": 38,
        "text": {
          "en": "Where foreign investors acquire a domestic enterprise or participate in a concentration of undertakings in other ways and national security is involved, a national security review shall be conducted in accordance with the relevant provisions of the State in addition to the review of the concentration of undertakings in accordance with the provisions of this Law."
        },
        "noLabel": {
          "en": "Article 38."
        },
        "chapter": {
          "en": "Chapter IV Concentration of Undertakings"
        }
      },
      {
        "no": 39,
        "text": {
          "en": "Administrative organs and organisations authorised by laws and regulations to perform the function of administering public affairs shall not abuse administrative power to restrict, or restrict in a disguised form, units or individuals in dealing in, purchasing or using the goods supplied by undertakings designated by them."
        },
        "noLabel": {
          "en": "Article 39."
        },
        "chapter": {
          "en": "Chapter V Abuse of Administrative Power to Eliminate or Restrict Competition"
        }
      },
      {
        "no": 40,
        "text": {
          "en": "Administrative organs and organisations authorised by laws and regulations to perform the function of administering public affairs shall not abuse administrative power, by concluding cooperation agreements, memoranda of understanding or otherwise with undertakings, to hinder other undertakings from entering the relevant market or to accord unequal treatment to other undertakings, thereby eliminating or restricting competition."
        },
        "noLabel": {
          "en": "Article 40."
        },
        "chapter": {
          "en": "Chapter V Abuse of Administrative Power to Eliminate or Restrict Competition"
        }
      },
      {
        "no": 41,
        "text": {
          "en": "Administrative organs and organisations authorised by laws and regulations to perform the function of administering public affairs shall not abuse administrative power to commit the following acts that hinder the free flow of goods between regions:\n(a) imposing discriminatory charge items or discriminatory charge standards on goods from other regions, or setting discriminatory prices;\n(b) prescribing technical requirements or inspection standards for goods from other regions that differ from those for like goods of the local region, or adopting discriminatory technical measures such as repeated inspection or repeated certification for goods from other regions, thereby restricting the entry of goods from other regions into the local market;\n(c) adopting administrative licences specifically directed at goods from other regions, thereby restricting the entry of goods from other regions into the local market;\n(d) setting up checkpoints or adopting other means to obstruct the entry of goods from other regions or the transport of local goods out of the region;\n(e) other acts that hinder the free flow of goods between regions."
        },
        "noLabel": {
          "en": "Article 41."
        },
        "chapter": {
          "en": "Chapter V Abuse of Administrative Power to Eliminate or Restrict Competition"
        }
      },
      {
        "no": 42,
        "text": {
          "en": "Administrative organs and organisations authorised by laws and regulations to perform the function of administering public affairs shall not abuse administrative power, by setting discriminatory qualification requirements or evaluation standards or by failing to publish information in accordance with the law, to exclude or restrict undertakings from participating in tendering and bidding and other business activities."
        },
        "noLabel": {
          "en": "Article 42."
        },
        "chapter": {
          "en": "Chapter V Abuse of Administrative Power to Eliminate or Restrict Competition"
        }
      },
      {
        "no": 43,
        "text": {
          "en": "Administrative organs and organisations authorised by laws and regulations to perform the function of administering public affairs shall not abuse administrative power, by according unequal treatment compared with local undertakings or by other means, to exclude, restrict, compel or compel in a disguised form undertakings from other regions to invest or establish branches in the local region."
        },
        "noLabel": {
          "en": "Article 43."
        },
        "chapter": {
          "en": "Chapter V Abuse of Administrative Power to Eliminate or Restrict Competition"
        }
      },
      {
        "no": 44,
        "text": {
          "en": "Administrative organs and organisations authorised by laws and regulations to perform the function of administering public affairs shall not abuse administrative power to compel, or compel in a disguised form, undertakings to engage in monopolistic conduct prescribed by this Law."
        },
        "noLabel": {
          "en": "Article 44."
        },
        "chapter": {
          "en": "Chapter V Abuse of Administrative Power to Eliminate or Restrict Competition"
        }
      },
      {
        "no": 45,
        "text": {
          "en": "Administrative organs and organisations authorised by laws and regulations to perform the function of administering public affairs shall not abuse administrative power to formulate provisions containing content that eliminates or restricts competition."
        },
        "noLabel": {
          "en": "Article 45."
        },
        "chapter": {
          "en": "Chapter V Abuse of Administrative Power to Eliminate or Restrict Competition"
        }
      },
      {
        "no": 46,
        "text": {
          "en": "The anti-monopoly enforcement authority shall, in accordance with the law, investigate suspected monopolistic conduct.\nAny unit or individual shall be entitled to report suspected monopolistic conduct to the anti-monopoly enforcement authority. The anti-monopoly enforcement authority shall keep the identity of the informant confidential.\nWhere a report is made in writing and the relevant facts and evidence are provided, the anti-monopoly enforcement authority shall conduct the necessary investigation."
        },
        "noLabel": {
          "en": "Article 46."
        },
        "chapter": {
          "en": "Chapter VI Investigation of Suspected Monopolistic Conduct"
        }
      },
      {
        "no": 47,
        "text": {
          "en": "The anti-monopoly enforcement authority may take the following measures when investigating suspected monopolistic conduct:\n(a) entering the business premises of the investigated undertaking or other relevant premises to conduct an inspection;\n(b) questioning the investigated undertaking, interested parties or other relevant units or individuals, and requiring them to explain the relevant circumstances;\n(c) consulting and copying the relevant vouchers, agreements, accounting books, business correspondence, electronic data and other documents and materials of the investigated undertaking, interested parties or other relevant units or individuals;\n(d) sealing up and seizing the relevant evidence;\n(e) inquiring into the bank accounts of undertakings.\nThe measures prescribed in the preceding paragraph shall be reported in writing to the principal person in charge of the anti-monopoly enforcement authority and shall be subject to approval."
        },
        "noLabel": {
          "en": "Article 47."
        },
        "chapter": {
          "en": "Chapter VI Investigation of Suspected Monopolistic Conduct"
        }
      },
      {
        "no": 48,
        "text": {
          "en": "Where the anti-monopoly enforcement authority investigates suspected monopolistic conduct, the enforcement officers shall not be fewer than two in number and shall produce their enforcement credentials.\nWhere enforcement officers conduct questioning and investigation, they shall make records, which shall be signed by the persons questioned or investigated."
        },
        "noLabel": {
          "en": "Article 48."
        },
        "chapter": {
          "en": "Chapter VI Investigation of Suspected Monopolistic Conduct"
        }
      },
      {
        "no": 49,
        "text": {
          "en": "The anti-monopoly enforcement authority and its staff members shall, in accordance with the law, bear a duty of confidentiality in respect of trade secrets, personal privacy and personal information learned in the course of enforcement."
        },
        "noLabel": {
          "en": "Article 49."
        },
        "chapter": {
          "en": "Chapter VI Investigation of Suspected Monopolistic Conduct"
        }
      },
      {
        "no": 50,
        "text": {
          "en": "The investigated undertaking, interested parties or other relevant units or individuals shall cooperate with the anti-monopoly enforcement authority in performing its duties in accordance with the law, and shall not refuse or obstruct the investigation by the anti-monopoly enforcement authority."
        },
        "noLabel": {
          "en": "Article 50."
        },
        "chapter": {
          "en": "Chapter VI Investigation of Suspected Monopolistic Conduct"
        }
      },
      {
        "no": 51,
        "text": {
          "en": "The investigated undertaking and interested parties shall be entitled to state their views. The anti-monopoly enforcement authority shall verify the facts, reasons and evidence presented by the investigated undertaking and interested parties."
        },
        "noLabel": {
          "en": "Article 51."
        },
        "chapter": {
          "en": "Chapter VI Investigation of Suspected Monopolistic Conduct"
        }
      },
      {
        "no": 52,
        "text": {
          "en": "Where the anti-monopoly enforcement authority, after investigating and verifying suspected monopolistic conduct, considers that monopolistic conduct is constituted, it shall make a decision on handling in accordance with the law and may make the decision public."
        },
        "noLabel": {
          "en": "Article 52."
        },
        "chapter": {
          "en": "Chapter VI Investigation of Suspected Monopolistic Conduct"
        }
      },
      {
        "no": 53,
        "text": {
          "en": "Where, in respect of suspected monopolistic conduct investigated by the anti-monopoly enforcement authority, the investigated undertaking undertakes to take specific measures within a time limit recognised by the anti-monopoly enforcement authority to eliminate the consequences of the conduct, the anti-monopoly enforcement authority may decide to suspend the investigation. The decision to suspend the investigation shall state the specific content of the commitments of the investigated undertaking.\nWhere the anti-monopoly enforcement authority decides to suspend the investigation, it shall supervise the performance of the commitments by the undertaking. Where the undertaking performs its commitments, the anti-monopoly enforcement authority may decide to terminate the investigation.\nUnder any of the following circumstances, the anti-monopoly enforcement authority shall resume the investigation:\n(a) the undertaking fails to perform its commitments;\n(b) the facts on which the decision to suspend the investigation is based have undergone major changes;\n(c) the decision to suspend the investigation was made on the basis of incomplete or untrue information provided by the undertaking."
        },
        "noLabel": {
          "en": "Article 53."
        },
        "chapter": {
          "en": "Chapter VI Investigation of Suspected Monopolistic Conduct"
        }
      },
      {
        "no": 54,
        "text": {
          "en": "Where the anti-monopoly enforcement authority investigates suspected abuse of administrative power to eliminate or restrict competition in accordance with the law, the relevant units or individuals shall cooperate."
        },
        "noLabel": {
          "en": "Article 54."
        },
        "chapter": {
          "en": "Chapter VI Investigation of Suspected Monopolistic Conduct"
        }
      },
      {
        "no": 55,
        "text": {
          "en": "Where an undertaking, an administrative organ or an organisation authorised by laws and regulations to perform the function of administering public affairs is suspected of violating the provisions of this Law, the anti-monopoly enforcement authority may conduct a regulatory talk with its legal representative or person in charge, requiring it to propose corrective measures."
        },
        "noLabel": {
          "en": "Article 55."
        },
        "chapter": {
          "en": "Chapter VI Investigation of Suspected Monopolistic Conduct"
        }
      },
      {
        "no": 56,
        "text": {
          "en": "Where an undertaking, in violation of the provisions of this Law, reaches and implements a monopoly agreement, the anti-monopoly enforcement authority shall order it to cease the illegal act, confiscate its illegal gains, and impose a fine of between 1 per cent and 10 per cent of the sales volume of the preceding year; where there is no sales volume in the preceding year, a fine of not more than RMB 5,000,000 shall be imposed; where the monopoly agreement reached has not yet been implemented, a fine of not more than RMB 3,000,000 may be imposed. Where the legal representative, the principal person in charge and the persons directly responsible of an undertaking bear personal responsibility for reaching the monopoly agreement, a fine of not more than RMB 1,000,000 may be imposed on them.\nWhere an undertaking organises other undertakings to reach a monopoly agreement or provides substantive assistance to other undertakings in reaching a monopoly agreement, the provisions of the preceding paragraph shall apply.\nWhere an undertaking voluntarily reports to the anti-monopoly enforcement authority the relevant circumstances of reaching a monopoly agreement and provides important evidence, the anti-monopoly enforcement authority may, as it deems appropriate, mitigate or exempt the punishment of the undertaking (leniency).\nWhere an industry association, in violation of the provisions of this Law, organises undertakings in its industry to reach a monopoly agreement, the anti-monopoly enforcement authority shall order it to make corrections and may impose a fine of not more than RMB 3,000,000; where the circumstances are serious, the registration authority for social organisations may revoke its registration in accordance with the law."
        },
        "noLabel": {
          "en": "Article 56."
        },
        "chapter": {
          "en": "Chapter VII Legal Liability"
        }
      },
      {
        "no": 57,
        "text": {
          "en": "Where an undertaking, in violation of the provisions of this Law, abuses a dominant market position, the anti-monopoly enforcement authority shall order it to cease the illegal act, confiscate its illegal gains, and impose a fine of between 1 per cent and 10 per cent of the sales volume of the preceding year."
        },
        "noLabel": {
          "en": "Article 57."
        },
        "chapter": {
          "en": "Chapter VII Legal Liability"
        }
      },
      {
        "no": 58,
        "text": {
          "en": "Where an undertaking implements a concentration in violation of the provisions of this Law and the concentration has or may have the effect of eliminating or restricting competition, the anti-monopoly enforcement authority under the State Council shall order it to cease implementing the concentration, to dispose of its shares or assets within a time limit, to transfer its business within a time limit and to take other necessary measures to restore the state before the concentration, and shall impose a fine of not more than 10 per cent of the sales volume of the preceding year; where the concentration does not have the effect of eliminating or restricting competition, a fine of not more than RMB 5,000,000 shall be imposed."
        },
        "noLabel": {
          "en": "Article 58."
        },
        "chapter": {
          "en": "Chapter VII Legal Liability"
        }
      },
      {
        "no": 59,
        "text": {
          "en": "When determining the specific amount of a fine prescribed in Articles 56, 57 and 58 of this Law, the anti-monopoly enforcement authority shall take into account factors such as the nature, degree and duration of the illegal act and the circumstances of eliminating the consequences of the illegal act."
        },
        "noLabel": {
          "en": "Article 59."
        },
        "chapter": {
          "en": "Chapter VII Legal Liability"
        }
      },
      {
        "no": 60,
        "text": {
          "en": "Where an undertaking engages in monopolistic conduct and causes losses to others, it shall bear civil liability in accordance with the law.\nWhere an undertaking engages in monopolistic conduct and harms the public interest, the people's procuratorate at or above the level of a city divided into districts may, in accordance with the law, initiate civil public interest litigation before the people's court."
        },
        "noLabel": {
          "en": "Article 60."
        },
        "chapter": {
          "en": "Chapter VII Legal Liability"
        }
      },
      {
        "no": 61,
        "text": {
          "en": "Where an administrative organ or an organisation authorised by laws and regulations to perform the function of administering public affairs abuses administrative power and commits an act that eliminates or restricts competition, the authority at the higher level shall order it to make corrections; the person directly in charge and other persons directly responsible shall be given sanctions in accordance with the law. The anti-monopoly enforcement authority may propose to the relevant authority at the higher level that the matter be handled in accordance with the law. The administrative organ or organisation authorised by laws and regulations to perform the function of administering public affairs shall report the corrections in writing to the authority at the higher level and to the anti-monopoly enforcement authority.\nWhere laws and administrative regulations provide otherwise on the handling of abuse of administrative power by administrative organs or organisations authorised by laws and regulations to perform the function of administering public affairs to eliminate or restrict competition, those provisions shall apply."
        },
        "noLabel": {
          "en": "Article 61."
        },
        "chapter": {
          "en": "Chapter VII Legal Liability"
        }
      },
      {
        "no": 62,
        "text": {
          "en": "Where, in respect of a review or investigation conducted by the anti-monopoly enforcement authority in accordance with the law, a person refuses to provide the relevant materials or information, or provides false materials or information, or conceals, destroys or transfers evidence, or commits other acts of refusing or obstructing an investigation, the anti-monopoly enforcement authority shall order it to make corrections and shall impose on a unit a fine of not more than 1 per cent of the sales volume of the preceding year, or, where there is no sales volume in the preceding year or the sales volume is difficult to calculate, a fine of not more than RMB 5,000,000, and shall impose on an individual a fine of not more than RMB 500,000."
        },
        "noLabel": {
          "en": "Article 62."
        },
        "chapter": {
          "en": "Chapter VII Legal Liability"
        }
      },
      {
        "no": 63,
        "text": {
          "en": "Where the provisions of this Law are violated and the circumstances are especially serious, the impact is especially egregious and the consequences are especially serious, the anti-monopoly enforcement authority under the State Council may determine the specific amount of the fine at not less than two times and not more than five times the amount of the fine prescribed in Articles 56, 57, 58 and 62 of this Law."
        },
        "noLabel": {
          "en": "Article 63."
        },
        "chapter": {
          "en": "Chapter VII Legal Liability"
        }
      },
      {
        "no": 64,
        "text": {
          "en": "Where an undertaking is given an administrative penalty for violating the provisions of this Law, the matter shall be recorded in its credit record in accordance with the relevant provisions of the State and made public."
        },
        "noLabel": {
          "en": "Article 64."
        },
        "chapter": {
          "en": "Chapter VII Legal Liability"
        }
      },
      {
        "no": 65,
        "text": {
          "en": "Where a person is dissatisfied with a decision made by the anti-monopoly enforcement authority in accordance with Articles 34 and 35 of this Law, the person may first apply for administrative reconsideration in accordance with the law; where the person is dissatisfied with the decision on administrative reconsideration, the person may initiate administrative litigation in accordance with the law.\nWhere a person is dissatisfied with a decision made by the anti-monopoly enforcement authority other than those prescribed in the preceding paragraph, the person may apply for administrative reconsideration or initiate administrative litigation in accordance with the law."
        },
        "noLabel": {
          "en": "Article 65."
        },
        "chapter": {
          "en": "Chapter VII Legal Liability"
        }
      },
      {
        "no": 66,
        "text": {
          "en": "Where a staff member of the anti-monopoly enforcement authority abuses power, neglects duty, commits malpractices for personal gain, or discloses trade secrets, personal privacy or personal information learned in the course of enforcement, sanctions shall be given in accordance with the law."
        },
        "noLabel": {
          "en": "Article 66."
        },
        "chapter": {
          "en": "Chapter VII Legal Liability"
        }
      },
      {
        "no": 67,
        "text": {
          "en": "Where the provisions of this Law are violated and a crime is constituted, criminal responsibility shall be pursued in accordance with the law."
        },
        "noLabel": {
          "en": "Article 67."
        },
        "chapter": {
          "en": "Chapter VII Legal Liability"
        }
      },
      {
        "no": 68,
        "text": {
          "en": "The exercise of intellectual property (IP) rights by an undertaking in accordance with the provisions of laws and administrative regulations on intellectual property shall not be subject to this Law; however, the abuse of intellectual property rights by an undertaking to eliminate or restrict competition shall be subject to this Law."
        },
        "noLabel": {
          "en": "Article 68."
        },
        "chapter": {
          "en": "Chapter VIII Supplementary Provisions"
        }
      },
      {
        "no": 69,
        "text": {
          "en": "Joint or concerted conduct carried out by agricultural producers and rural economic organisations in business activities such as the production, processing, sale, transport and storage of agricultural products shall not be subject to this Law."
        },
        "noLabel": {
          "en": "Article 69."
        },
        "chapter": {
          "en": "Chapter VIII Supplementary Provisions"
        }
      },
      {
        "no": 70,
        "text": {
          "en": "This Law shall come into force on 1 August 2008."
        },
        "noLabel": {
          "en": "Article 70."
        },
        "chapter": {
          "en": "Chapter VIII Supplementary Provisions"
        }
      }
    ]
  };

  TR['CN-LAW-0148'] = {
    "lawId": "CN-LAW-0148",
    "sourceLang": "zh",
    "targetLang": "en",
    "engine": "llm",
    "model": "deepseek-v4.1-flash",
    "promptVersion": "calr-trans-v2",
    "translatedAt": "2026-10-14",
    "reviewed": "machine",
    "glossaryVersion": "calr-terms-2026-10-v2",
    "completenessNote": "逐条对译，共 310 条；条号与官方原文一一对应，未合并、未省略。",
    "articles": [
      {
        "no": 1,
        "text": {
          "en": "This Law is enacted for the purpose of regulating relations in maritime transport and relations concerning ships, protecting the lawful rights and interests of all parties concerned, strengthening the protection of the marine ecological environment and promoting the high-quality development of maritime transport and economic trade."
        },
        "noLabel": {
          "en": "Article 1."
        }
      },
      {
        "no": 2,
        "text": {
          "en": "For the purposes of this Law, maritime transport means the carriage of goods by sea and the carriage of passengers by sea, including direct transport between the sea and rivers and between rivers and the sea."
        },
        "noLabel": {
          "en": "Article 2."
        }
      },
      {
        "no": 3,
        "text": {
          "en": "For the purposes of this Law, ship means seagoing vessels and other mobile installations at sea, excluding vessels used for military or government official purposes and small craft of less than 20 gross tonnage. A ship includes its appurtenances."
        },
        "noLabel": {
          "en": "Article 3."
        }
      },
      {
        "no": 4,
        "text": {
          "en": "A ship that has acquired the nationality of the People's Republic of China through registration in accordance with the law shall have the right to fly the national flag of the People's Republic of China in navigation.\nWhere a ship navigates without flying the national flag of the People's Republic of China in accordance with the law, or flies the flag of another country, region or organisation in violation of the law, the relevant authority shall order correction and pursue legal liability in accordance with the law."
        },
        "noLabel": {
          "en": "Article 4."
        }
      },
      {
        "no": 5,
        "text": {
          "en": "Maritime transport and towage between ports of the People's Republic of China shall be operated by ships that have acquired the nationality of the People's Republic of China in accordance with the law, unless otherwise provided by laws or administrative regulations.\nWithout approval given in accordance with the law by the transport department under the State Council, no foreign ship may operate maritime transport or towage between ports of the People's Republic of China."
        },
        "noLabel": {
          "en": "Article 5."
        }
      },
      {
        "no": 6,
        "text": {
          "en": "The transport department under the State Council and the relevant local people's governments and their transport departments shall, in accordance with the law, exercise supervision and administration over maritime transport activities."
        },
        "noLabel": {
          "en": "Article 6."
        }
      },
      {
        "no": 7,
        "text": {
          "en": "Ownership of a ship means the right of the shipowner to possess, use, derive income from and dispose of the ship in accordance with the law."
        },
        "noLabel": {
          "en": "Article 7."
        },
        "chapter": {
          "en": "Section 1 Ownership of Ships"
        }
      },
      {
        "no": 8,
        "text": {
          "en": "The creation, modification, transfer and extinguishment of ownership of a ship shall be registered with the ship registration authority; without registration, it may not be asserted against a bona fide third party.\nThe ownership of a ship under financial leasing enjoyed by the lessor under a ship financial leasing contract may not, without registration, be asserted against a bona fide third party. The lessee shall pay the hire in accordance with the ship financial leasing contract. Where the lessee, after being urged, still fails to pay the hire within a reasonable period, the lessor may request payment of all the hire, or may terminate the ship financial leasing contract and take back the ship under financial leasing.\nThe transfer of ownership of a ship shall be made by a written contract."
        },
        "noLabel": {
          "en": "Article 8."
        },
        "chapter": {
          "en": "Section 1 Ownership of Ships"
        }
      },
      {
        "no": 9,
        "text": {
          "en": "Where a ship is co-owned by two or more legal persons, unincorporated organisations or natural persons, the co-ownership shall be registered with the ship registration authority; without registration, it may not be asserted against a bona fide third party.\nRights holders of the ship, interested parties and the relevant State organs may, in accordance with the law, inquire into the registration status of the ownership of the ship."
        },
        "noLabel": {
          "en": "Article 9."
        },
        "chapter": {
          "en": "Section 1 Ownership of Ships"
        }
      },
      {
        "no": 10,
        "text": {
          "en": "Where the parties have agreed on the ownership of a ship under construction, the agreement shall prevail; where there is no agreement or the agreement is unclear, the ownership shall vest in the shipbuilder."
        },
        "noLabel": {
          "en": "Article 10."
        },
        "chapter": {
          "en": "Section 1 Ownership of Ships"
        }
      },
      {
        "no": 11,
        "text": {
          "en": "A mortgage of a ship means the right of the mortgagee, in respect of a ship provided by the mortgagor as security for a debt, to be satisfied in priority out of the ship in accordance with the law where the debtor fails to perform the debt due or where the circumstances for enforcing the mortgage agreed upon by the parties occur."
        },
        "noLabel": {
          "en": "Article 11."
        },
        "chapter": {
          "en": "Section 2 Mortgage of Ships"
        }
      },
      {
        "no": 12,
        "text": {
          "en": "The shipowner or a person authorised by the shipowner may create a mortgage on a ship.\nThe creation of a mortgage on a ship shall be made by a written contract."
        },
        "noLabel": {
          "en": "Article 12."
        },
        "chapter": {
          "en": "Section 2 Mortgage of Ships"
        }
      },
      {
        "no": 13,
        "text": {
          "en": "The creation, modification, transfer and extinguishment of a mortgage on a ship shall be registered with the ship registration authority; without registration, it may not be asserted against a bona fide third party.\nThe registration of a mortgage on a ship shall be effected jointly by the mortgagee and the mortgagor with the ship registration authority.\nThe registration of a mortgage on a ship shall include the following main particulars:\n(a) the names and domiciles of the mortgagee and the mortgagor;\n(b) the name and nationality of the mortgaged ship, and the authority that issued the certificate of ownership of the ship and the number of the certificate;\n(c) the amount of the secured claim and the time limit for satisfaction;\n(d) the time of registration of the mortgage.\nThe registration status of a mortgage on a ship shall be open to public inquiry."
        },
        "noLabel": {
          "en": "Article 13."
        },
        "chapter": {
          "en": "Section 2 Mortgage of Ships"
        }
      },
      {
        "no": 14,
        "text": {
          "en": "A mortgage may be created on a ship under construction.\nTo register a mortgage on a ship under construction, the relevant documents shall be submitted to the ship registration authority in accordance with the relevant provisions."
        },
        "noLabel": {
          "en": "Article 14."
        },
        "chapter": {
          "en": "Section 2 Mortgage of Ships"
        }
      },
      {
        "no": 15,
        "text": {
          "en": "Unless otherwise agreed in the contract, the mortgagor shall insure the mortgaged ship; where the ship is not insured, the mortgagee shall have the right to insure the ship, and the insurance premium shall be borne by the mortgagor."
        },
        "noLabel": {
          "en": "Article 15."
        },
        "chapter": {
          "en": "Section 2 Mortgage of Ships"
        }
      },
      {
        "no": 16,
        "text": {
          "en": "Unless otherwise agreed by the co-owners of the ship, the creation of a mortgage on a co-owned ship shall be dealt with in the following circumstances:\n(a) where the ship is under co-ownership by shares, the consent of the co-owners holding not less than two thirds of the shares shall be obtained;\n(b) where the ship is under joint ownership, the consent of all the co-owners shall be obtained.\nA mortgage created by the co-owners of a ship shall not be affected by the partition of the co-ownership of the ship."
        },
        "noLabel": {
          "en": "Article 16."
        },
        "chapter": {
          "en": "Section 2 Mortgage of Ships"
        }
      },
      {
        "no": 17,
        "text": {
          "en": "After a mortgage on a ship is created, the mortgagor may transfer the mortgaged ship. Where the parties have agreed otherwise, their agreement shall prevail. Where the mortgaged ship is transferred, the mortgage on the ship shall not be affected."
        },
        "noLabel": {
          "en": "Article 17."
        },
        "chapter": {
          "en": "Section 2 Mortgage of Ships"
        }
      },
      {
        "no": 18,
        "text": {
          "en": "Where a claim secured by a mortgage on a ship is transferred, the mortgage shall be transferred together with it, unless otherwise provided by law or agreed by the parties."
        },
        "noLabel": {
          "en": "Article 18."
        },
        "chapter": {
          "en": "Section 2 Mortgage of Ships"
        }
      },
      {
        "no": 19,
        "text": {
          "en": "Where two or more mortgages are created on the same ship, the order of satisfaction shall be determined in the following circumstances:\n(a) where the mortgages on the ship have been registered, satisfaction shall be made in the order of the time of registration;\n(b) a registered mortgage on the ship shall be satisfied before an unregistered one;\n(c) where the mortgages on the ship have not been registered, satisfaction shall be made in proportion to the secured claims."
        },
        "noLabel": {
          "en": "Article 19."
        },
        "chapter": {
          "en": "Section 2 Mortgage of Ships"
        }
      },
      {
        "no": 20,
        "text": {
          "en": "Where the mortgaged ship is damaged, lost or expropriated, the mortgagee may be satisfied in priority out of the insurance money, compensation or indemnity obtained."
        },
        "noLabel": {
          "en": "Article 20."
        },
        "chapter": {
          "en": "Section 2 Mortgage of Ships"
        }
      },
      {
        "no": 21,
        "text": {
          "en": "A maritime lien means the right of a maritime claimant, who has a maritime claim under this Law against the shipowner, the bareboat charterer, the ship manager or the ship operator, to be satisfied in priority out of the ship in respect of which the maritime claim arose."
        },
        "noLabel": {
          "en": "Article 21."
        },
        "chapter": {
          "en": "Section 3 Maritime Liens"
        }
      },
      {
        "no": 22,
        "text": {
          "en": "The following maritime claims shall be secured by maritime liens:\n(a) claims for payment of wages, other labour remuneration, costs of repatriation of crew and social insurance contributions arising from work on board of the master, crew members and other persons serving on board the ship;\n(b) claims for compensation for personal injury or death occurring in the operation of the ship;\n(c) claims for payment of tonnage dues, pilotage dues and other port charges;\n(d) claims for payment of salvage remuneration for salvage at sea;\n(e) claims for property compensation arising from infringement in the operation of the ship, excluding claims for compensation for the loss of or damage to the goods, containers and passengers' luggage carried on board the ship.\nWhere civil liability insurance has been obtained or corresponding financial security has been provided in accordance with the international treaties concluded or acceded to by the People's Republic of China or the mandatory provisions of laws or administrative regulations, the maritime claims prescribed in subparagraphs (b) and (e) of the preceding paragraph shall not be secured by maritime liens to the extent of that insurance or financial security."
        },
        "noLabel": {
          "en": "Article 22."
        },
        "chapter": {
          "en": "Section 3 Maritime Liens"
        }
      },
      {
        "no": 23,
        "text": {
          "en": "The maritime claims listed in paragraph 1 of Article 22 of this Law shall be satisfied in the order set out. However, a maritime claim under subparagraph (d) that arises after those under subparagraphs (a) to (c) shall be satisfied before the claims under subparagraphs (a) to (c).\nWhere there are two or more maritime claims under subparagraph (a), (b), (c) or (e) of paragraph 1 of Article 22 of this Law, they shall be satisfied simultaneously without regard to the order of occurrence, and where the proceeds are insufficient, they shall be satisfied in proportion; where there are two or more maritime claims under subparagraph (d), the one arising later shall be satisfied first."
        },
        "noLabel": {
          "en": "Article 23."
        },
        "chapter": {
          "en": "Section 3 Maritime Liens"
        }
      },
      {
        "no": 24,
        "text": {
          "en": "The litigation costs arising from the enforcement of maritime liens, the expenses incurred in preserving, auctioning or selling the ship and in distributing the proceeds of the ship, and other expenses paid for the common benefit of the maritime claimants shall be deducted in advance from the proceeds of the auction or sale of the ship."
        },
        "noLabel": {
          "en": "Article 24."
        },
        "chapter": {
          "en": "Section 3 Maritime Liens"
        }
      },
      {
        "no": 25,
        "text": {
          "en": "A maritime lien shall not be extinguished by the transfer of ownership of the ship, except that, where the ship is transferred, the maritime lien is not enforced within 60 days from the date of the public announcement made by the court at the application of the transferee."
        },
        "noLabel": {
          "en": "Article 25."
        },
        "chapter": {
          "en": "Section 3 Maritime Liens"
        }
      },
      {
        "no": 26,
        "text": {
          "en": "Where a maritime claim secured by a maritime lien as prescribed in Article 22 of this Law is transferred or subrogated, the maritime lien shall be transferred together with it."
        },
        "noLabel": {
          "en": "Article 26."
        },
        "chapter": {
          "en": "Section 3 Maritime Liens"
        }
      },
      {
        "no": 27,
        "text": {
          "en": "A maritime lien shall be enforced by means of the arrest of the ship in respect of which the lien arose by a court."
        },
        "noLabel": {
          "en": "Article 27."
        },
        "chapter": {
          "en": "Section 3 Maritime Liens"
        }
      },
      {
        "no": 28,
        "text": {
          "en": "Except in the circumstances prescribed in Article 25 of this Law, a maritime lien shall be extinguished upon any of the following grounds:\n(a) not being enforced within one year from the date on which it arose;\n(b) the ship being auctioned or sold by a court in accordance with the law;\n(c) the loss of the ship.\nThe one-year period prescribed in subparagraph (a) of the preceding paragraph shall not be suspended or interrupted.\nThe one-year period for the maritime lien securing the maritime claim prescribed in subparagraph (a) of paragraph 1 of Article 22 of this Law shall be counted from the date on which the maritime claimant leaves the ship on which he or she served."
        },
        "noLabel": {
          "en": "Article 28."
        },
        "chapter": {
          "en": "Section 3 Maritime Liens"
        }
      },
      {
        "no": 29,
        "text": {
          "en": "The provisions of this Section shall not affect the application of the provisions of Chapter XI of this Law on limitation of liability for maritime claims."
        },
        "noLabel": {
          "en": "Article 29."
        },
        "chapter": {
          "en": "Section 3 Maritime Liens"
        }
      },
      {
        "no": 30,
        "text": {
          "en": "A lien on a ship means the right of the shipbuilder or shiprepairer, where the other party to the contract fails to pay the costs of building or repairing the ship as agreed, to retain the ship of which it is in lawful possession and to be satisfied in priority out of the ship.\nThe lien on a ship shall be extinguished when the shipbuilder or shiprepairer ceases to possess the ship under construction or repair.\nA lien on a ship shall be satisfied before a mortgage on the ship and after a maritime lien."
        },
        "noLabel": {
          "en": "Article 30."
        },
        "chapter": {
          "en": "Section 4 Possessory Lien on Ships"
        }
      },
      {
        "no": 31,
        "text": {
          "en": "Unless otherwise agreed, where 60 days have elapsed since a shipbuilder or shiprepairer retained a ship and the debtor still fails to perform its obligations, the shipbuilder or shiprepairer may agree with the debtor that the ship retained be converted into money at a valuation, or may be satisfied in priority out of the proceeds from the auction or sale of the ship retained."
        },
        "noLabel": {
          "en": "Article 31."
        },
        "chapter": {
          "en": "Section 4 Possessory Lien on Ships"
        }
      },
      {
        "no": 32,
        "text": {
          "en": "Where, during the period of retention, the ship is arrested by a court and auctioned or sold, the right of the holder of a lien on the ship to be satisfied in priority shall not be affected."
        },
        "noLabel": {
          "en": "Article 32."
        },
        "chapter": {
          "en": "Section 4 Possessory Lien on Ships"
        }
      },
      {
        "no": 33,
        "text": {
          "en": "\"Crew\" means all persons employed on board a ship, including the master."
        },
        "noLabel": {
          "en": "Article 33."
        },
        "chapter": {
          "en": "Section 1 General Provisions"
        }
      },
      {
        "no": 34,
        "text": {
          "en": "Chinese crew members shall, in accordance with the provisions of laws and administrative regulations on the management of crew, obtain the corresponding certificates of competency and health certificates for crew members.\nWhere foreign crew members work on board a ship of Chinese nationality, the provisions of laws and administrative regulations on the management of crew shall apply."
        },
        "noLabel": {
          "en": "Article 34."
        },
        "chapter": {
          "en": "Section 1 General Provisions"
        }
      },
      {
        "no": 35,
        "text": {
          "en": "Chinese crew members serving on board ships engaged in international voyages shall, in accordance with the law, hold the seafarer's certificate and other relevant certificates issued by the maritime administration authority of the People's Republic of China."
        },
        "noLabel": {
          "en": "Article 35."
        },
        "chapter": {
          "en": "Section 1 General Provisions"
        }
      },
      {
        "no": 36,
        "text": {
          "en": "The employer of crew members shall, in accordance with the provisions of relevant laws and administrative regulations and of the international treaties concerning crew labour and social security concluded or acceded to by the People's Republic of China, conclude labour contracts with the crew members.\nMatters concerning the engagement of crew members and the rights and obligations in respect of crew labour and social security that are not provided for in this Law shall be governed by the provisions of relevant laws and administrative regulations."
        },
        "noLabel": {
          "en": "Article 36."
        },
        "chapter": {
          "en": "Section 1 General Provisions"
        }
      },
      {
        "no": 37,
        "text": {
          "en": "The master shall be responsible for the management and command of the ship.\nOrders issued by the master within the scope of his authority shall be executed by the crew, the passengers and other persons on board.\nThe master shall take necessary measures to protect the ship and the persons on board, documents, mail, goods and other property, and to prevent and control pollution of the ecological environment by the ship."
        },
        "noLabel": {
          "en": "Article 37."
        },
        "chapter": {
          "en": "Section 2 The Master"
        }
      },
      {
        "no": 38,
        "text": {
          "en": "For the purpose of safeguarding the safety of the persons on board and of the ship, the master shall have the power to place in confinement, or to take other necessary measures against, any person on board who is suspected of engaging in illegal or criminal activities, and to prevent such person from concealing, destroying or forging evidence.\nWhere the master takes the measures specified in the preceding paragraph, he shall prepare a report on the case, which shall be signed by the master and not less than two persons on board and, together with the person suspected of engaging in illegal or criminal activities, be delivered to the competent authority for handling."
        },
        "noLabel": {
          "en": "Article 38."
        },
        "chapter": {
          "en": "Section 2 The Master"
        }
      },
      {
        "no": 39,
        "text": {
          "en": "The master shall record any birth or death occurring on board in the ship's log book and shall draw up a certificate in the presence of two witnesses. A death certificate shall be accompanied by an inventory of the effects of the deceased. Where the deceased has left a will, the master shall certify it. The death certificate and the will shall be kept in the custody of the master and delivered to the family members of the deceased or to the parties concerned."
        },
        "noLabel": {
          "en": "Article 39."
        },
        "chapter": {
          "en": "Section 2 The Master"
        }
      },
      {
        "no": 40,
        "text": {
          "en": "Where a maritime accident occurs to the ship and endangers the safety of the persons on board and of property, the master shall organise the crew and other persons on board to carry out rescue with all their efforts. Where the sinking or destruction of the ship is inevitable, the master shall have the power to decide to abandon the ship.\nIn abandoning the ship, the master shall take all measures to first organise the passengers to leave the ship safely and then arrange for the crew to leave the ship, and the master shall be the last to leave the ship. Before leaving the ship, the master shall direct the crew to make every effort to salvage the ship's log book, the engine log book, the oil record book, the radio log book, the nautical charts and documents used on the voyage, as well as valuables, mail and cash, and shall direct the crew to close valves of oil tanks and other equipment so as to prevent or reduce the occurrence of pollution."
        },
        "noLabel": {
          "en": "Article 40."
        },
        "chapter": {
          "en": "Section 2 The Master"
        }
      },
      {
        "no": 41,
        "text": {
          "en": "The responsibility of the master for the management and command of the ship shall not be discharged by reason of the ship being piloted by a pilot."
        },
        "noLabel": {
          "en": "Article 41."
        },
        "chapter": {
          "en": "Section 2 The Master"
        }
      },
      {
        "no": 42,
        "text": {
          "en": "Where the master dies in the course of the voyage or is unable for any reason to perform his duties, the officer of the highest rank among the officers shall act in place of the master; before the ship sails from the next port, the shipowner, the ship operator or the ship manager shall appoint a new master to take over."
        },
        "noLabel": {
          "en": "Article 42."
        },
        "chapter": {
          "en": "Section 2 The Master"
        }
      },
      {
        "no": 43,
        "text": {
          "en": "\"Contract of carriage of goods by sea\" means a contract under which the carrier, against payment of freight, undertakes to carry the goods consigned by the shipper from one port to another by sea, including contracts of international carriage of goods by sea and contracts of domestic carriage of goods by sea between ports of the People's Republic of China."
        },
        "noLabel": {
          "en": "Article 43."
        },
        "chapter": {
          "en": "Section 1 General Provisions"
        }
      },
      {
        "no": 44,
        "text": {
          "en": "The following terms used in this Chapter have the meanings set out below:\n(a) \"Carrier\" means a person who concludes a contract of carriage of goods by sea with the shipper in his own name or through another person entrusted to act in his own name.\n(b) \"Actual carrier\" means a person who, having accepted the entrustment of the carrier or a sub-entrustment, actually performs all or part of the carrier's obligations specified in Article 49 of this Law.\n(c) \"Shipper\" means:\n1. a person who concludes a contract of carriage of goods by sea with the carrier in his own name, or through another person entrusted to act in his own name, or through another person entrusted to act for him;\n2. a person who delivers the goods to the carrier under the contract of carriage of goods by sea in his own name, or through another person entrusted to act in his own name, or through another person entrusted to act for him.\n(d) \"Consignee\" means a person entitled to take delivery of the goods.\n(e) \"Goods\" includes live animals and the containers, pallets, vehicles or similar articles of transport provided by the shipper for consolidating the goods.\n(f) \"Transport document\" means a bill of lading, a sea waybill or any other document which evidences a contract of carriage of goods by sea and the taking over or loading of the goods by the carrier.\n(g) \"Bill of lading\" means a document which evidences a contract of carriage of goods by sea and the taking over or loading of the goods by the carrier, and by which the carrier undertakes to deliver the goods."
        },
        "noLabel": {
          "en": "Article 44."
        },
        "chapter": {
          "en": "Section 1 General Provisions"
        }
      },
      {
        "no": 45,
        "text": {
          "en": "Any stipulation in a contract of carriage of goods by sea, or in a bill of lading or other transport document evidencing such contract, that is in violation of the provisions of this Chapter, and any stipulation assigning the insurable interest in the goods to the carrier or any similar stipulation, shall be invalid. The invalidity of such stipulation shall not affect the validity of the other stipulations of the contract, the bill of lading or the other transport document."
        },
        "noLabel": {
          "en": "Article 45."
        },
        "chapter": {
          "en": "Section 1 General Provisions"
        }
      },
      {
        "no": 46,
        "text": {
          "en": "The provisions of Article 45 of this Law shall not affect any increase by the carrier of its liabilities and obligations beyond those specified in this Chapter."
        },
        "noLabel": {
          "en": "Article 46."
        },
        "chapter": {
          "en": "Section 1 General Provisions"
        }
      },
      {
        "no": 47,
        "text": {
          "en": "The period of responsibility of the carrier for goods carried in containers means the entire period during which the goods are in the custody of the carrier, from the time the goods are received at the port of loading until the time they are delivered at the port of discharge. The period of responsibility of the carrier for goods not carried in containers means the entire period during which the goods are in the custody of the carrier, from the time the goods are loaded on board the ship until the time they are discharged from the ship. Where the goods are lost or damaged during the period of responsibility of the carrier, the carrier shall be liable for compensation, unless otherwise provided for in this Section.\nThe provisions of the preceding paragraph shall not affect any agreement on the liability borne by the carrier for goods not carried in containers before loading and after discharge."
        },
        "noLabel": {
          "en": "Article 47."
        },
        "chapter": {
          "en": "Section 2 Carrier’s Responsibilities"
        }
      },
      {
        "no": 48,
        "text": {
          "en": "Before and at the time of departure of the ship, the carrier shall exercise due diligence to make the ship seaworthy, to properly man, equip and supply the ship, and to make the holds, the other cargo spaces of the ship and the containers for the carriage of goods provided by the carrier fit and safe for the reception, carriage and preservation of the goods.\nThe carrier of domestic carriage of goods by sea shall also perform the obligations specified in the preceding paragraph during the voyage."
        },
        "noLabel": {
          "en": "Article 48."
        },
        "chapter": {
          "en": "Section 2 Carrier’s Responsibilities"
        }
      },
      {
        "no": 49,
        "text": {
          "en": "The carrier shall properly and carefully receive, load, handle, stow, carry, keep, care for, discharge and deliver the goods carried."
        },
        "noLabel": {
          "en": "Article 49."
        },
        "chapter": {
          "en": "Section 2 Carrier’s Responsibilities"
        }
      },
      {
        "no": 50,
        "text": {
          "en": "The carrier shall carry the goods to the port of discharge by the agreed, customary or geographically appropriate route.\nAny deviation of the ship on the sea or in navigable waters connected therewith for the purpose of saving or attempting to save human life or property, or any other reasonable deviation, shall not constitute a breach of the provisions of the preceding paragraph."
        },
        "noLabel": {
          "en": "Article 50."
        },
        "chapter": {
          "en": "Section 2 Carrier’s Responsibilities"
        }
      },
      {
        "no": 51,
        "text": {
          "en": "Where the goods are not delivered at the agreed port of discharge within the time expressly agreed upon, such non-delivery constitutes delay in delivery; in domestic carriage of goods by sea, where the goods are not delivered within a reasonable time, such non-delivery also constitutes delay in delivery.\nExcept in the circumstances where the carrier is not liable for compensation in accordance with the provisions of this Chapter, where the goods are lost or damaged or other economic loss is suffered as a result of delay in delivery due to the fault of the carrier, the carrier shall be liable for compensation.\nWhere the carrier fails to deliver the goods within 60 days after the expiry of the time limit specified in paragraph 1 of this Article, the person entitled to claim for the loss of the goods may treat the goods as lost."
        },
        "noLabel": {
          "en": "Article 51."
        },
        "chapter": {
          "en": "Section 2 Carrier’s Responsibilities"
        }
      },
      {
        "no": 52,
        "text": {
          "en": "Where the loss of or damage to the goods, or the delay in delivery, occurring during the period of responsibility is caused by any of the following causes, the carrier shall not be liable for compensation:\n(a) the fault of the master, a crew member, a pilot or other servants of the carrier in the navigation or management of the ship;\n(b) fire on board the ship, except where caused by the fault of the carrier himself;\n(c) act of God, perils or accidents on the sea or in navigable waters connected therewith;\n(d) war or armed conflict, piracy or terrorist activities;\n(e) an act of the government or of a competent department, quarantine restrictions, or judicial seizure not arising from any cause attributable to the carrier, the actual carrier or their servants or agents;\n(f) strike, lockout or restriction of labour;\n(g) saving or attempting to save human life or property at sea or in navigable waters connected therewith;\n(h) an act of the shipper, the owner of the goods, the consignee or their servants or agents;\n(i) the natural properties or the inherent defect of the goods;\n(j) improper packing of the goods, or insufficiency or illegibility of the marks;\n(k) latent defect of the ship not discoverable despite the exercise of due diligence;\n(l) any other cause not arising from the fault of the carrier, the actual carrier or their servants or agents.\nSubparagraphs (a) and (b) of the preceding paragraph shall not apply to domestic carriage of goods by sea.\nWhere the carrier is exempted from liability for compensation in accordance with the provisions of paragraph 1 of this Article, it shall bear the burden of proof, except in the case of the cause specified in subparagraph (b)."
        },
        "noLabel": {
          "en": "Article 52."
        },
        "chapter": {
          "en": "Section 2 Carrier’s Responsibilities"
        }
      },
      {
        "no": 53,
        "text": {
          "en": "Where the loss of or damage to live animals or the delay in delivery is caused by the special risks inherent in the carriage of live animals, the carrier shall not be liable for compensation. However, the carrier shall prove that it has performed the special requirements of the shipper concerning the carriage of live animals and that, in the actual circumstances, the loss, damage or delay in delivery was caused by the special risks inherent in the carriage of live animals."
        },
        "noLabel": {
          "en": "Article 53."
        },
        "chapter": {
          "en": "Section 2 Carrier’s Responsibilities"
        }
      },
      {
        "no": 54,
        "text": {
          "en": "The carrier shall carry goods on deck only where it has reached an agreement with the shipper, or where such carriage conforms to the custom of the trade or to the provisions of relevant laws and administrative regulations.\nWhere the carrier loads the goods on deck in accordance with the provisions of the preceding paragraph, it shall not be liable for compensation for the loss of or damage to the goods or the delay in delivery caused by the special risks of such carriage.\nWhere the carrier and the shipper have agreed to carry the goods on deck, this shall be stated in the bill of lading; if it is not so stated, it may not be asserted against a bona fide third party."
        },
        "noLabel": {
          "en": "Article 54."
        },
        "chapter": {
          "en": "Section 2 Carrier’s Responsibilities"
        }
      },
      {
        "no": 55,
        "text": {
          "en": "Where the loss of or damage to the goods or the delay in delivery is caused jointly by a cause for which the carrier, or the servants or agents of the carrier, cannot be exempted from liability and by other causes, the carrier shall be liable only to the extent that it cannot be exempted from liability; however, the carrier shall bear the burden of proof in respect of the loss, damage or delay in delivery caused by the other causes."
        },
        "noLabel": {
          "en": "Article 55."
        },
        "chapter": {
          "en": "Section 2 Carrier’s Responsibilities"
        }
      },
      {
        "no": 56,
        "text": {
          "en": "The amount of compensation for the loss of the goods shall be calculated on the basis of the actual value of the goods; the amount of compensation for damage to the goods shall be calculated on the basis of the difference between the actual values of the goods before and after the damage or on the basis of the cost of repairing the goods.\nThe actual value of the goods shall be calculated on the basis of the market price at the place of delivery at the time of delivery; where the market price at the place of delivery at the time of delivery cannot be determined, it shall be calculated on the basis of the value of the goods at the time of shipment plus insurance premium plus freight.\nThe actual value of the goods specified in the preceding paragraph shall, in calculating compensation, be reduced by the relevant charges saved or not incurred as a result of the loss of or damage to the goods."
        },
        "noLabel": {
          "en": "Article 56."
        },
        "chapter": {
          "en": "Section 2 Carrier’s Responsibilities"
        }
      },
      {
        "no": 57,
        "text": {
          "en": "The limit of liability of the carrier for the loss of or damage to the goods shall be calculated on the basis of the number of packages or other shipping units, at 666.67 units of account per package or other shipping unit, or on the basis of the gross weight of the goods, at 2 units of account per kilogram, whichever limit of liability is the higher. However, this does not apply where the shipper has declared the nature and value of the goods before shipment and the declaration is stated in the bill of lading, or where the carrier and the shipper have otherwise agreed on a limit of liability higher than that specified in this Article.\nWhere the goods are consolidated in containers, pallets, vehicles or similar articles of transport, the number of packages or other shipping units of the goods packed in such articles of transport stated in the bill of lading shall be deemed to be the number of packages or other shipping units specified in the preceding paragraph; where no such number is stated, each article of transport shall be deemed to be one package or one other shipping unit.\nWhere an article of transport is not owned by the carrier or is not provided by the carrier, the article of transport itself shall be deemed to be one package or one other shipping unit."
        },
        "noLabel": {
          "en": "Article 57."
        },
        "chapter": {
          "en": "Section 2 Carrier’s Responsibilities"
        }
      },
      {
        "no": 58,
        "text": {
          "en": "The limit of liability of the carrier for economic loss caused by the delay in delivery of the goods shall be the amount of the freight for the goods so delayed. Where the loss of, damage to and delay in delivery of the goods occur concurrently, the limit of liability of the carrier shall be the limit specified in paragraph 1 of Article 57 of this Law."
        },
        "noLabel": {
          "en": "Article 58."
        },
        "chapter": {
          "en": "Section 2 Carrier’s Responsibilities"
        }
      },
      {
        "no": 59,
        "text": {
          "en": "Any claim for compensation brought against the carrier by means of litigation, arbitration or otherwise in respect of the loss of or damage to the goods or the delay in delivery covered by a contract of carriage of goods by sea shall be subject to the provisions of this Chapter concerning the defences and the limits of liability of the carrier, whether or not the maritime claimant is a party to the contract and whether the claim is founded on contract or on tort.\nWhere a claim for compensation referred to in the preceding paragraph is brought against a servant or agent of the carrier, the provisions of the preceding paragraph shall apply if the servant or agent proves that his act was within the scope of his employment or entrustment."
        },
        "noLabel": {
          "en": "Article 59."
        },
        "chapter": {
          "en": "Section 2 Carrier’s Responsibilities"
        }
      },
      {
        "no": 60,
        "text": {
          "en": "Where it is proved that the loss of or damage to the goods or the delay in delivery resulted from an act or omission of the carrier done with intent to cause such loss, or recklessly and with knowledge that such loss would probably result, the carrier shall not be entitled to invoke the provisions of Article 57 or Article 58 of this Law limiting its liability.\nWhere it is proved that the loss of or damage to the goods or the delay in delivery resulted from an act or omission of a servant or agent of the carrier done with intent to cause such loss, or recklessly and with knowledge that such loss would probably result, the servant or agent shall not be entitled to invoke the provisions of Article 57 or Article 58 of this Law limiting liability."
        },
        "noLabel": {
          "en": "Article 60."
        },
        "chapter": {
          "en": "Section 2 Carrier’s Responsibilities"
        }
      },
      {
        "no": 61,
        "text": {
          "en": "Where the carrier entrusts the carriage of the goods, or part of the carriage, to an actual carrier for performance, the carrier shall remain responsible for the entire carriage in accordance with the provisions of this Chapter. In respect of the carriage performed by the actual carrier, the carrier shall be responsible for the acts of the actual carrier or of the servants or agents of the actual carrier within the scope of their employment or entrustment.\nNotwithstanding the provisions of the preceding paragraph, where a contract of carriage of goods by sea expressly provides that a specified part of the carriage covered by the contract shall be performed by a nominated actual carrier other than the carrier, the contract may also provide that the carrier shall not be liable for compensation for the loss of or damage to the goods or the delay in delivery occurring while the goods are in the charge of the nominated actual carrier. However, such provision shall be stated in the bill of lading; if it is not so stated, it may not be asserted against a bona fide third party."
        },
        "noLabel": {
          "en": "Article 61."
        },
        "chapter": {
          "en": "Section 2 Carrier’s Responsibilities"
        }
      },
      {
        "no": 62,
        "text": {
          "en": "The provisions of this Chapter concerning the liability of the carrier shall apply to the actual carrier. Where a claim for compensation is brought against a servant or agent of the actual carrier, the provisions of paragraph 2 of Article 59 and paragraph 2 of Article 60 of this Law shall apply."
        },
        "noLabel": {
          "en": "Article 62."
        },
        "chapter": {
          "en": "Section 2 Carrier’s Responsibilities"
        }
      },
      {
        "no": 63,
        "text": {
          "en": "Any special agreement whereby the carrier assumes obligations not provided for in this Chapter or waives rights conferred by this Chapter shall take effect in respect of the actual carrier where the actual carrier has expressly consented thereto in writing; whether or not the actual carrier consents shall not affect the effect of such special agreement in respect of the carrier."
        },
        "noLabel": {
          "en": "Article 63."
        },
        "chapter": {
          "en": "Section 2 Carrier’s Responsibilities"
        }
      },
      {
        "no": 64,
        "text": {
          "en": "Where both the carrier and the actual carrier are liable for compensation, they shall bear joint and several liability within the scope of such liability."
        },
        "noLabel": {
          "en": "Article 64."
        },
        "chapter": {
          "en": "Section 2 Carrier’s Responsibilities"
        }
      },
      {
        "no": 65,
        "text": {
          "en": "Where claims for compensation are brought separately against the carrier, the actual carrier and their servants or agents in respect of the loss of or damage to the goods or the delay in delivery, the total amount of compensation shall not exceed the limit specified in Article 57 or Article 58 of this Law."
        },
        "noLabel": {
          "en": "Article 65."
        },
        "chapter": {
          "en": "Section 2 Carrier’s Responsibilities"
        }
      },
      {
        "no": 66,
        "text": {
          "en": "The provisions of Articles 61 to 65 of this Law shall not affect the right of recourse between the carrier and the actual carrier."
        },
        "noLabel": {
          "en": "Article 66."
        },
        "chapter": {
          "en": "Section 2 Carrier’s Responsibilities"
        }
      },
      {
        "no": 67,
        "text": {
          "en": "The shipper shall deliver the goods to the carrier for carriage in accordance with the agreement in the contract of carriage of goods by sea, and shall guarantee that the goods delivered for carriage are fit for the agreed carriage."
        },
        "noLabel": {
          "en": "Article 67."
        },
        "chapter": {
          "en": "Section 3 Shipper’s Responsibilities"
        }
      },
      {
        "no": 68,
        "text": {
          "en": "In consigning the goods, the shipper shall pack the goods properly and shall guarantee to the carrier the accuracy of the description, marks, number of packages or pieces, weight or volume of the goods as provided at the time of loading; where loss is caused to the carrier by improper packing or by the inaccuracy of the said particulars, the shipper shall be liable for compensation.\nThe right of indemnity enjoyed by the carrier under the provisions of the preceding paragraph shall not affect the liability borne by the carrier, under the contract of carriage of goods by sea, towards persons other than the shipper."
        },
        "noLabel": {
          "en": "Article 68."
        },
        "chapter": {
          "en": "Section 3 Shipper’s Responsibilities"
        }
      },
      {
        "no": 69,
        "text": {
          "en": "The shipper shall, in good time, complete with the port, the customs and other competent authorities the various formalities required for the carriage of the goods, and shall deliver to the carrier the documents evidencing the completion of such formalities; where the interests of the carrier are prejudiced by the failure to complete such formalities in good time, or by their being incomplete or incorrect, the shipper shall be liable for compensation."
        },
        "noLabel": {
          "en": "Article 69."
        },
        "chapter": {
          "en": "Section 3 Shipper’s Responsibilities"
        }
      },
      {
        "no": 70,
        "text": {
          "en": "Where the shipper consigns dangerous goods, it shall, in accordance with the provisions on the carriage of dangerous goods by sea, pack the goods properly, mark and label them as dangerous goods, and notify the carrier in writing of the proper name and nature of the goods and of the preventive measures against hazards and the emergency response measures to be taken; where the shipper fails to give such notice or gives an erroneous notice, the carrier may, at any time and at any place, discharge, destroy or render innocuous the goods as the circumstances may require, without being liable for compensation. The shipper shall be liable for compensation for the loss suffered by the carrier by reason of the carriage of such goods.\nWhere the carrier knows the nature of the dangerous goods and has agreed to their shipment, it may nevertheless, when such goods constitute an actual danger to the ship, to persons or to other goods, discharge, destroy or render innocuous the goods without being liable for compensation. However, the provisions of this paragraph shall not affect contribution in general average."
        },
        "noLabel": {
          "en": "Article 70."
        },
        "chapter": {
          "en": "Section 3 Shipper’s Responsibilities"
        }
      },
      {
        "no": 71,
        "text": {
          "en": "The shipper shall pay freight to the carrier as agreed.\nThe shipper and the carrier may agree that the freight shall be paid by the consignee; however, such agreement shall be stated in the transport document."
        },
        "noLabel": {
          "en": "Article 71."
        },
        "chapter": {
          "en": "Section 3 Shipper’s Responsibilities"
        }
      },
      {
        "no": 72,
        "text": {
          "en": "The shipper shall not be liable for compensation for any loss suffered by the carrier or the actual carrier or for any damage suffered by the ship, unless such loss or damage is caused by the fault of the shipper or of the servants or agents of the shipper.\nThe servants or agents of the shipper shall not be liable for compensation for any loss suffered by the carrier or the actual carrier or for any damage suffered by the ship, unless such loss or damage is caused by the fault of such servants or agents."
        },
        "noLabel": {
          "en": "Article 72."
        },
        "chapter": {
          "en": "Section 3 Shipper’s Responsibilities"
        }
      },
      {
        "no": 73,
        "text": {
          "en": "After the goods have been received or loaded by the carrier, the carrier shall, at the request of the shipper, issue a bill of lading. A bill of lading may be issued by a person authorised by the carrier; where it is issued by the master of the ship on which the goods are loaded, it shall be deemed to have been issued on behalf of the carrier."
        },
        "noLabel": {
          "en": "Article 73."
        },
        "chapter": {
          "en": "Section 4 Transport Documents"
        }
      },
      {
        "no": 74,
        "text": {
          "en": "A bill of lading shall include the following particulars:\n(a) the description, marks, number of packages or pieces, weight or volume of the goods and, where dangerous goods are carried, a statement of their dangerous nature;\n(b) the name and principal place of business of the carrier;\n(c) the name of the ship;\n(d) the name of the shipper;\n(e) the name of the consignee or instructions concerning the consignee;\n(f) the port of loading;\n(g) the port of discharge;\n(h) in the case of a combined transport bill of lading, the place of receipt and the place of delivery of the goods;\n(i) the date and place of issue of the bill of lading and the number of copies issued;\n(j) the payment of freight;\n(k) the signature of the carrier or of its representative.\nThe absence of one or more of the particulars specified in the preceding paragraph shall not affect the nature of the bill of lading; however, the bill of lading shall comply with the provisions of subparagraph (g) of Article 44 of this Law."
        },
        "noLabel": {
          "en": "Article 74."
        },
        "chapter": {
          "en": "Section 4 Transport Documents"
        }
      },
      {
        "no": 75,
        "text": {
          "en": "Where, before the goods are loaded, the carrier has, at the request of the shipper, issued a received-for-shipment bill of lading or other document, the shipper may, after the loading of the goods is completed, return the received-for-shipment bill of lading or other document to the carrier in exchange for a shipped bill of lading; the carrier may also annotate the received-for-shipment bill of lading with the name of the carrying ship and the date of shipment, and the bill of lading so annotated shall be deemed to be a shipped bill of lading."
        },
        "noLabel": {
          "en": "Article 75."
        },
        "chapter": {
          "en": "Section 4 Transport Documents"
        }
      },
      {
        "no": 76,
        "text": {
          "en": "Where the carrier, or a person issuing a bill of lading on its behalf, knows or has reasonable grounds to suspect that the description, marks, number of packages or pieces, weight or volume of the goods stated in the bill of lading do not correspond to the goods actually received or, in the case of the issue of a shipped bill of lading, do not correspond to the goods loaded on board, or has no adequate means of verifying the particulars stated in the bill of lading, it may make a note on the bill of lading indicating the discrepancy, the grounds for suspicion or the fact that verification is impossible."
        },
        "noLabel": {
          "en": "Article 76."
        },
        "chapter": {
          "en": "Section 4 Transport Documents"
        }
      },
      {
        "no": 77,
        "text": {
          "en": "Where the carrier, or a person issuing a bill of lading on its behalf, fails to note the apparent condition of the goods on the bill of lading, the goods shall be deemed to have been in good apparent condition."
        },
        "noLabel": {
          "en": "Article 77."
        },
        "chapter": {
          "en": "Section 4 Transport Documents"
        }
      },
      {
        "no": 78,
        "text": {
          "en": "Except where a note is made in accordance with the provisions of Article 76 of this Law, a bill of lading issued by the carrier or by a person issuing it on its behalf is prima facie evidence that the carrier has received the goods as stated in the bill of lading or that the goods have been loaded on board; evidence adduced by the carrier against a bona fide third party, including the consignee, to the effect that the condition of the goods differs from that stated in the bill of lading shall not be admitted."
        },
        "noLabel": {
          "en": "Article 78."
        },
        "chapter": {
          "en": "Section 4 Transport Documents"
        }
      },
      {
        "no": 79,
        "text": {
          "en": "The rights and obligations between the carrier and the consignee or the holder of the bill of lading shall be determined by the bill of lading. Where no bill of lading has been issued, the rights and obligations between the carrier and the consignee shall be governed by the relevant provisions of this Chapter.\nThe consignee or the holder of the bill of lading shall not bear the demurrage, dead freight and other charges relating to loading incurred at the port of loading, unless the bill of lading expressly states that such charges are to be borne by the consignee or the holder of the bill of lading."
        },
        "noLabel": {
          "en": "Article 79."
        },
        "chapter": {
          "en": "Section 4 Transport Documents"
        }
      },
      {
        "no": 80,
        "text": {
          "en": "A straight bill of lading shall not be transferable.\nAn order bill of lading is transferred by endorsement in the name of a specified person or by endorsement in blank.\nA bearer bill of lading is transferable without endorsement."
        },
        "noLabel": {
          "en": "Article 80."
        },
        "chapter": {
          "en": "Section 4 Transport Documents"
        }
      },
      {
        "no": 81,
        "text": {
          "en": "Where the carrier issues a document other than a bill of lading to evidence the receipt of goods for shipment, such document is prima facie evidence of the conclusion of the contract of carriage of goods by sea and of the receipt by the carrier of the goods specified in the document.\nSuch document issued by the carrier shall not be transferable."
        },
        "noLabel": {
          "en": "Article 81."
        },
        "chapter": {
          "en": "Section 4 Transport Documents"
        }
      },
      {
        "no": 82,
        "text": {
          "en": "An electronic transport record means information issued by the carrier by electronic means of communication under a contract of carriage of goods by sea, which evidences the contract of carriage of goods by sea and the receipt or loading of the goods by the carrier, and includes a negotiable electronic transport record and a non-negotiable electronic transport record.\nAn electronic transport record that meets the conditions prescribed by laws and administrative regulations shall have the same effect as a transport document. The legal effect of an electronic transport record shall not be denied solely on the ground that it is in electronic form.\nThe provisions of this Law concerning transport documents shall apply to electronic transport records."
        },
        "noLabel": {
          "en": "Article 82."
        },
        "chapter": {
          "en": "Section 5 Electronic Transport Records"
        }
      },
      {
        "no": 83,
        "text": {
          "en": "The carrier and the shipper may, by agreement, issue and use an electronic transport record."
        },
        "noLabel": {
          "en": "Article 83."
        },
        "chapter": {
          "en": "Section 5 Electronic Transport Records"
        }
      },
      {
        "no": 84,
        "text": {
          "en": "An electronic transport record shall meet the following requirements:\n(a) the recorded information contains the relevant particulars referred to in Article 74 of this Law and is accessible so as to be usable for subsequent reference;\n(b) the recorded information is complete and accurate;\n(c) the issuer can be identified;\n(d) the holder can prove its identity."
        },
        "noLabel": {
          "en": "Article 84."
        },
        "chapter": {
          "en": "Section 5 Electronic Transport Records"
        }
      },
      {
        "no": 85,
        "text": {
          "en": "In addition to complying with the provisions of Article 84 of this Law, a negotiable electronic transport record shall contain information on its negotiability and the procedure for its transfer.\nA negotiable electronic transport record shall be subject to a reliable method or a reliable transaction system so as to ensure the singularity and integrity of the record and to guarantee the exclusive control of the record by the holder.\nThe transfer of, and exclusive control over, a negotiable electronic transport record, the manner of conversion of the form of the record and the criteria for determining a reliable method or transaction system shall be prescribed separately by the national cyberspace administration department together with the competent transport department of the State Council."
        },
        "noLabel": {
          "en": "Article 85."
        },
        "chapter": {
          "en": "Section 5 Electronic Transport Records"
        }
      },
      {
        "no": 86,
        "text": {
          "en": "Upon agreement between the carrier and the shipper or the holder of a transport document, an electronic transport record and a transport document may be converted into each other.\nWhere an electronic transport record and a transport document are converted into each other, the explanatory information on the conversion shall be indicated and the recorded contents shall be kept consistent before and after the conversion. The conversion of the form of the document shall not alter the rights and obligations of the parties.\nUpon completion of the conversion between an electronic transport record and a transport document, the original transport document or electronic transport record shall become invalid immediately."
        },
        "noLabel": {
          "en": "Article 86."
        },
        "chapter": {
          "en": "Section 5 Electronic Transport Records"
        }
      },
      {
        "no": 87,
        "text": {
          "en": "Delivery of the goods by the carrier shall be effected in accordance with the following provisions:\n(a) where a straight bill of lading has been issued, the goods shall be delivered against the bill of lading to the named consignee;\n(b) where an order bill of lading has been issued, the goods shall be delivered against the bill of lading to the endorsee of the bill of lading;\n(c) where a bearer bill of lading has been issued, or where an order bill of lading has been endorsed in blank, the goods shall be delivered against the bill of lading to the holder of the bill of lading;\n(d) where a negotiable electronic transport record has been issued, the goods shall be delivered to the holder of the electronic transport record;\n(e) in other circumstances, the goods shall be delivered against the identity document of the consignee to the consignee."
        },
        "noLabel": {
          "en": "Article 87."
        },
        "chapter": {
          "en": "Section 6 Delivery of Goods"
        }
      },
      {
        "no": 88,
        "text": {
          "en": "Where the carrier delivers the goods to the consignee, the consignee shall notify the carrier in writing of the loss of or damage to the goods; where no such notice is given, such delivery shall be prima facie evidence that the carrier has delivered the goods as stated in the transport document and that the goods were in good condition.\nWhere the loss of or damage to the goods is not apparent, the consignee shall submit a written notice to the carrier within 7 consecutive days from the day following the delivery of the goods not carried in containers, or within 15 consecutive days from the day following the delivery of the goods carried in containers; where no such notice is submitted, the provisions of the preceding paragraph shall apply.\nWhere, at the time of delivery of the goods, the consignee and the carrier have jointly inspected or surveyed the goods, no written notice need be submitted in respect of the loss or damage ascertained."
        },
        "noLabel": {
          "en": "Article 88."
        },
        "chapter": {
          "en": "Section 6 Delivery of Goods"
        }
      },
      {
        "no": 89,
        "text": {
          "en": "Where the carrier does not receive, within 60 consecutive days from the day following the delivery of the goods to the consignee, a written notice submitted by the consignee in respect of the economic loss caused by the delay in delivery of the goods, the carrier shall not be liable for compensation."
        },
        "noLabel": {
          "en": "Article 89."
        },
        "chapter": {
          "en": "Section 6 Delivery of Goods"
        }
      },
      {
        "no": 90,
        "text": {
          "en": "Before the consignee takes delivery of the goods at the port of destination, or before the carrier delivers the goods at the port of destination, a survey institution may be requested to survey the condition of the goods; the party requesting the survey shall pay the survey fees but shall be entitled to recover them from the party liable for the loss of the goods."
        },
        "noLabel": {
          "en": "Article 90."
        },
        "chapter": {
          "en": "Section 6 Delivery of Goods"
        }
      },
      {
        "no": 91,
        "text": {
          "en": "The carrier and the consignee shall provide each other with reasonable facilities for the inspection prescribed in Articles 88 and 90 of this Law."
        },
        "noLabel": {
          "en": "Article 91."
        },
        "chapter": {
          "en": "Section 6 Delivery of Goods"
        }
      },
      {
        "no": 92,
        "text": {
          "en": "Where the goods are delivered by the actual carrier, a written notice submitted by the consignee to the actual carrier in accordance with the provisions of Article 88 of this Law shall have the same effect as a written notice submitted to the carrier, and a written notice submitted to the carrier shall have the same effect as a written notice submitted to the actual carrier."
        },
        "noLabel": {
          "en": "Article 92."
        },
        "chapter": {
          "en": "Section 6 Delivery of Goods"
        }
      },
      {
        "no": 93,
        "text": {
          "en": "Where the goods are not taken delivery of by anyone at the port of discharge, the master may discharge the goods into a warehouse or another suitable place, and the expenses and risks arising therefrom shall be borne by the shipper, provided that the shipper shall be notified in a timely manner.\nWhere the consignee has exercised the rights under the contract of carriage of goods by sea but delays in or refuses to take delivery of the goods, the master may deal with the goods in accordance with the provisions of the preceding paragraph, and the expenses and risks arising therefrom shall be borne by the consignee."
        },
        "noLabel": {
          "en": "Article 93."
        },
        "chapter": {
          "en": "Section 6 Delivery of Goods"
        }
      },
      {
        "no": 94,
        "text": {
          "en": "Where the freight, general average contribution, demurrage, necessary expenses advanced by the carrier for the goods and other expenses payable to the carrier have not been paid in full and no appropriate security has been provided, the carrier may retain the corresponding goods.\nWhere the transport document states that the freight is prepaid or contains a declaration of a similar nature, the carrier shall not retain the goods on the ground that the freight has not been paid, unless the consignee is the shipper."
        },
        "noLabel": {
          "en": "Article 94."
        },
        "chapter": {
          "en": "Section 6 Delivery of Goods"
        }
      },
      {
        "no": 95,
        "text": {
          "en": "Where goods retained by the carrier in accordance with the provisions of Article 94 of this Law are not taken delivery of within 60 days from the day following the arrival of the ship at the port of discharge, the carrier may apply to a court for auction; where the goods are perishable or the expenses of preserving the goods plus the expenses payable to the carrier may exceed the value of the goods, the carrier may apply for an early auction.\nThe proceeds of the auction shall be used to pay the expenses of preserving and auctioning the goods, the freight and other related expenses payable to the carrier; where the amount is insufficient, the carrier shall have the right to recover the difference from the shipper; the surplus, if any, shall be returned to the shipper, and where it cannot be returned and remains unclaimed for one year from the date of the auction, it shall belong to the State."
        },
        "noLabel": {
          "en": "Article 95."
        },
        "chapter": {
          "en": "Section 6 Delivery of Goods"
        }
      },
      {
        "no": 96,
        "text": {
          "en": "During the period of responsibility of the carrier, the shipper may notify the carrier in writing to suspend the transport, return the goods, change the port of discharge or deliver the goods to another consignee, provided that the shipper shall compensate the carrier for the losses suffered as a result.\nUnder any of the following circumstances, the carrier may refuse the shipper's request, provided that the carrier shall immediately notify the shipper:\n(a) the carrier is unable to satisfy the shipper's request due to objective conditions, or satisfying such a request would affect the normal operation of the carrier;\n(b) the carrier anticipates that satisfying the shipper's request will incur additional expenses or cause economic losses to the carrier, requests the shipper to provide corresponding security, and the shipper fails to provide such security;\n(c) the shipper fails to produce the transport document already issued as requested by the carrier."
        },
        "noLabel": {
          "en": "Article 96."
        },
        "chapter": {
          "en": "Section 7 Modification and Cancellation of Contracts"
        }
      },
      {
        "no": 97,
        "text": {
          "en": "Before the ship departs from the port of loading, the shipper may request the termination of the contract. However, unless otherwise agreed in the contract, the shipper shall pay to the carrier half of the agreed freight, and where the goods have already been loaded on board, the shipper shall also bear the expenses of loading, discharging and other related expenses."
        },
        "noLabel": {
          "en": "Article 97."
        },
        "chapter": {
          "en": "Section 7 Modification and Cancellation of Contracts"
        }
      },
      {
        "no": 98,
        "text": {
          "en": "Where, before the ship departs from the port of loading, the contract cannot be performed due to force majeure or other causes not attributable to the carrier or the shipper, either party may terminate the contract, and neither party shall be liable to the other for compensation. Unless otherwise agreed in the contract, where the freight has been paid, the carrier shall refund the freight to the shipper; where the goods have already been loaded on board, the shipper shall bear the loading and discharging expenses; and where a transport document has already been issued, the shipper shall return the transport document to the carrier."
        },
        "noLabel": {
          "en": "Article 98."
        },
        "chapter": {
          "en": "Section 7 Modification and Cancellation of Contracts"
        }
      },
      {
        "no": 99,
        "text": {
          "en": "Where, due to force majeure or other causes not attributable to the carrier or the shipper, the ship cannot discharge the goods at the port of destination agreed in the contract, the master shall, unless otherwise agreed in the contract, have the right to discharge the goods at a safe port or place near the port of destination, and such discharge shall be deemed performance of the contract.\nWhere the master decides to discharge the goods, he or she shall promptly notify the shipper or the consignee and shall take into account the interests of the shipper or the consignee."
        },
        "noLabel": {
          "en": "Article 99."
        },
        "chapter": {
          "en": "Section 7 Modification and Cancellation of Contracts"
        }
      },
      {
        "no": 100,
        "text": {
          "en": "For the purposes of this Law, a multimodal transport contract means a contract under which the multimodal transport operator undertakes to transport the goods from the place of receipt to the place of destination for delivery to the consignee by two or more different modes of transport, including the mode of maritime transport, and to collect the freight for the entire carriage.\nThe multimodal transport operator referred to in the preceding paragraph means the person who, in his or her own name or through another person on his or her behalf, concludes a multimodal transport contract with the shipper."
        },
        "noLabel": {
          "en": "Article 100."
        },
        "chapter": {
          "en": "Section 8 Special Provisions Regarding Multimodal Transport Contract"
        }
      },
      {
        "no": 101,
        "text": {
          "en": "The period of responsibility of the multimodal transport operator for the goods under multimodal transport shall run from the time of receipt of the goods until the time of delivery of the goods."
        },
        "noLabel": {
          "en": "Article 101."
        },
        "chapter": {
          "en": "Section 8 Special Provisions Regarding Multimodal Transport Contract"
        }
      },
      {
        "no": 102,
        "text": {
          "en": "The multimodal transport operator shall be responsible for performing or organising the performance of the multimodal transport contract and shall be responsible for the entire carriage.\nThe multimodal transport operator and the segment carriers participating in the multimodal transport may separately agree by contract on their mutual liabilities in respect of the carriage of each segment under the multimodal transport contract. However, such contract shall not affect the responsibility borne by the multimodal transport operator for the entire carriage."
        },
        "noLabel": {
          "en": "Article 102."
        },
        "chapter": {
          "en": "Section 8 Special Provisions Regarding Multimodal Transport Contract"
        }
      },
      {
        "no": 103,
        "text": {
          "en": "Where the loss of or damage to the goods or the delay in delivery occurs during a particular segment of the multimodal transport, the liability for compensation, the limits of liability and the limitation period of the multimodal transport operator shall be determined in accordance with the relevant laws governing the mode of transport of that segment."
        },
        "noLabel": {
          "en": "Article 103."
        },
        "chapter": {
          "en": "Section 8 Special Provisions Regarding Multimodal Transport Contract"
        }
      },
      {
        "no": 104,
        "text": {
          "en": "Where the segment of transport during which the loss of or damage to the goods or the delay in delivery occurred cannot be ascertained, the multimodal transport operator shall bear liability for compensation in accordance with the provisions of this Chapter on the liability for compensation and the limits of liability of the carrier and the provisions of this Law on limitation of action."
        },
        "noLabel": {
          "en": "Article 104."
        },
        "chapter": {
          "en": "Section 8 Special Provisions Regarding Multimodal Transport Contract"
        }
      },
      {
        "no": 105,
        "text": {
          "en": "A contract for the carriage of passengers by sea means a contract under which the carrier undertakes to carry passengers and their luggage by sea by a suitable ship such as a passenger ship or a cruise ship, and the passengers pay the fare."
        },
        "noLabel": {
          "en": "Article 105."
        },
        "chapter": {
          "en": "Chapter V Contract of Carriage of Passengers by Sea"
        }
      },
      {
        "no": 106,
        "text": {
          "en": "The following terms used in this Chapter have the following meanings:\n(a) carrier means the person who, in his or her own name or through another person on his or her behalf, concludes a contract for the carriage of passengers by sea with a passenger;\n(b) actual carrier means the person who, entrusted or sub-entrusted by the carrier, performs the whole or part of the carriage of passengers and their luggage;\n(c) passenger means a person carried under a contract for the carriage of passengers by sea; a person who, with the consent of the carrier and under a contract of carriage of goods by sea, accompanies the goods on board to escort them shall be deemed a passenger;\n(d) luggage means any article or vehicle carried by the carrier under a contract for the carriage of passengers by sea, excluding live animals;\n(e) cabin luggage means the luggage which a passenger carries, keeps or places in his or her cabin."
        },
        "noLabel": {
          "en": "Article 106."
        },
        "chapter": {
          "en": "Chapter V Contract of Carriage of Passengers by Sea"
        }
      },
      {
        "no": 107,
        "text": {
          "en": "A passenger ticket is evidence of the conclusion of a contract for the carriage of passengers by sea."
        },
        "noLabel": {
          "en": "Article 107."
        },
        "chapter": {
          "en": "Chapter V Contract of Carriage of Passengers by Sea"
        }
      },
      {
        "no": 108,
        "text": {
          "en": "Any clause in a contract for the carriage of passengers by sea that contains any of the following shall be invalid:\n(a) exempting the carrier from the statutory liability that it should bear towards the passenger;\n(b) reducing the limits of liability of the carrier prescribed in this Chapter;\n(c) providing for the contrary of the burden of proof prescribed in this Chapter;\n(d) restricting the passenger's right to claim compensation.\nThe invalidity of a clause of a contract prescribed in the preceding paragraph shall not affect the validity of the other clauses of the contract."
        },
        "noLabel": {
          "en": "Article 108."
        },
        "chapter": {
          "en": "Chapter V Contract of Carriage of Passengers by Sea"
        }
      },
      {
        "no": 109,
        "text": {
          "en": "The period of carriage in the carriage of passengers by sea shall run from the time the passenger boards the ship until the time the passenger disembarks. Where the fare includes the cost of transport to and from the ship, the period of carriage shall include the time during which the carrier transports the passenger by water from the shore to the ship and from the ship to the shore, but shall not include the time the passenger spends in the port station, on the wharf or in other port facilities.\nThe provisions of the preceding paragraph shall apply to the period of carriage of the passenger's cabin luggage. Where the passenger's cabin luggage has been received by the carrier or its servants or agents but has not yet been returned to the passenger, the period of carriage shall include the time the passenger spends in the port station, on the wharf or in other port facilities.\nAs for luggage other than the passenger's cabin luggage, the period of carriage shall run from the time the passenger delivers the luggage to the carrier or its servants or agents until the time the carrier or its servants or agents return it to the passenger."
        },
        "noLabel": {
          "en": "Article 109."
        },
        "chapter": {
          "en": "Chapter V Contract of Carriage of Passengers by Sea"
        }
      },
      {
        "no": 110,
        "text": {
          "en": "Where a passenger boards the ship without a ticket, travels in a class higher than that for which the ticket was purchased, travels beyond the distance covered by the ticket, or travels with a discounted passenger ticket that does not meet the conditions for the discount, the passenger shall pay the difference in the fare in accordance with the provisions, and the carrier may charge an additional fare in accordance with the provisions; where the passenger refuses to pay the fare, the master shall have the right to order the passenger to leave the ship at a suitable place, and the carrier shall have the right to demand payment."
        },
        "noLabel": {
          "en": "Article 110."
        },
        "chapter": {
          "en": "Chapter V Contract of Carriage of Passengers by Sea"
        }
      },
      {
        "no": 111,
        "text": {
          "en": "A passenger shall not carry on his or her person or pack in his or her luggage contraband or inflammable, explosive, toxic, corrosive or radioactive goods and other dangerous goods that may endanger the personal and property safety on board the ship.\nThe carrier shall have the right to unload, destroy or render harmless the contraband or dangerous goods carried on the person of a passenger or packed in his or her luggage, or to deliver them to the relevant department, without bearing liability for compensation.\nWhere a passenger violates the provisions of paragraph 1 of this Article and causes damage, the passenger shall bear liability for compensation."
        },
        "noLabel": {
          "en": "Article 111."
        },
        "chapter": {
          "en": "Chapter V Contract of Carriage of Passengers by Sea"
        }
      },
      {
        "no": 112,
        "text": {
          "en": "During the period of carriage of the passenger and his or her luggage prescribed in Article 109 of this Law, where an accident caused by the fault of the carrier or of its servants or agents acting within the scope of their employment or entrustment results in the personal injury or death of the passenger or the loss of or damage to the luggage, the carrier shall bear liability for compensation.\nThe claimant shall bear the burden of proving the fault of the carrier or of its servants or agents, except in the circumstances prescribed in paragraphs 3 and 4 of this Article.\nWhere the personal injury or death of the passenger or the loss of or damage to the cabin luggage or the luggage carried in the passenger's vehicle results from the sinking, collision, stranding, explosion or fire of the ship or from a defect of the ship, the carrier or its servants or agents shall be presumed to be at fault unless they adduce evidence to the contrary.\nWhere luggage other than the passenger's cabin luggage and the luggage carried in the passenger's vehicle is lost or damaged, whatever the accident that caused it, the carrier or its servants or agents shall be presumed to be at fault unless they adduce evidence to the contrary."
        },
        "noLabel": {
          "en": "Article 112."
        },
        "chapter": {
          "en": "Chapter V Contract of Carriage of Passengers by Sea"
        }
      },
      {
        "no": 113,
        "text": {
          "en": "Where the carrier proves that the personal injury or death of the passenger or the loss of or damage to the luggage was caused by the fault of the passenger himself or herself or by the common fault of the passenger and the carrier, the carrier's liability for compensation may be exempted or reduced accordingly.\nWhere the carrier proves that the personal injury or death of the passenger or the loss of or damage to the luggage was caused by the intentional act of the passenger himself or herself, or that the personal injury or death of the passenger was caused by the passenger's own state of health, the carrier shall not bear liability for compensation."
        },
        "noLabel": {
          "en": "Article 113."
        },
        "chapter": {
          "en": "Chapter V Contract of Carriage of Passengers by Sea"
        }
      },
      {
        "no": 114,
        "text": {
          "en": "The carrier shall not bear liability for compensation for the loss of or damage to money, gold, silver, jewellery, negotiable securities or other valuables of a passenger.\nWhere the passenger and the carrier have agreed that the articles prescribed in the preceding paragraph are to be delivered to the carrier for safekeeping, the carrier shall bear liability for compensation in accordance with the provisions of Article 115 of this Law; where the amount of compensation agreed in writing by the parties is higher than the limit of liability for compensation prescribed in Article 115 of this Law, the carrier shall bear liability for compensation in accordance with the agreed amount."
        },
        "noLabel": {
          "en": "Article 114."
        },
        "chapter": {
          "en": "Chapter V Contract of Carriage of Passengers by Sea"
        }
      },
      {
        "no": 115,
        "text": {
          "en": "The limits of liability for compensation of the carrier in each carriage of passengers by sea shall be as follows:\n(a) for the personal injury or death of a passenger, not more than 175,000 units of account per passenger;\n(b) for the loss of or damage to the passenger's cabin luggage, not more than 1,800 units of account per passenger;\n(c) for the loss of or damage to a passenger's vehicle, including the luggage carried in the vehicle, not more than 10,000 units of account per vehicle;\n(d) for the loss of or damage to luggage of the passenger other than that prescribed in subparagraphs (b) and (c) of this paragraph, not more than 2,700 units of account per passenger.\nThe carrier and the passenger may agree on a deductible for the loss of the passenger's vehicle and for the loss of luggage other than the passenger's vehicle. However, the deductible for the loss of each vehicle shall not exceed 300 units of account, and the deductible for the loss of luggage other than the vehicle of each passenger shall not exceed 135 units of account. In calculating the amount of compensation for the loss of each vehicle or of luggage other than the vehicle of each passenger, the agreed deductible of the carrier shall be deducted.\nThe carrier and the passenger may agree in writing on limits of liability for compensation higher than those prescribed in paragraph 1 of this Article."
        },
        "noLabel": {
          "en": "Article 115."
        },
        "chapter": {
          "en": "Chapter V Contract of Carriage of Passengers by Sea"
        }
      },
      {
        "no": 116,
        "text": {
          "en": "Where it is proved that the personal injury or death of the passenger or the loss of or damage to the luggage resulted from an act or omission of the carrier done with intent to cause such damage, or recklessly and with knowledge that such damage would probably result, the carrier shall not be entitled to avail itself of the provisions of Articles 114 and 115 of this Law limiting liability for compensation.\nWhere it is proved that the personal injury or death of the passenger or the loss of or damage to the luggage resulted from an act or omission of a servant or agent of the carrier done with intent to cause such damage, or recklessly and with knowledge that such damage would probably result, the servant or agent of the carrier shall not be entitled to avail himself or herself of the provisions of Articles 114 and 115 of this Law limiting liability for compensation."
        },
        "noLabel": {
          "en": "Article 116."
        },
        "chapter": {
          "en": "Chapter V Contract of Carriage of Passengers by Sea"
        }
      },
      {
        "no": 117,
        "text": {
          "en": "In the case of apparent damage to the luggage, the passenger shall submit a written notice to the carrier or its servants or agents in accordance with the following provisions:\n(a) for cabin luggage and luggage carried in the passenger's vehicle, before or at the time of the passenger's disembarkation;\n(b) for other luggage, before or at the time the luggage is returned.\nWhere the damage to the luggage is not apparent and is difficult for the passenger to discover at the time of disembarkation or at the time the luggage is returned, and where the luggage is lost, the passenger shall submit a written notice to the carrier or its servants or agents within 15 days from the date of disembarkation or of the return of the luggage or of the date on which it should have been returned.\nWhere the passenger fails to submit a written notice in a timely manner in accordance with the provisions of paragraphs 1 and 2 of this Article, the passenger shall, unless evidence to the contrary is adduced, be deemed to have received the luggage in good condition.\nWhere, at the time the luggage is returned, the passenger has already carried out a joint inspection or examination of the luggage with the carrier, no written notice is required."
        },
        "noLabel": {
          "en": "Article 117."
        },
        "chapter": {
          "en": "Chapter V Contract of Carriage of Passengers by Sea"
        }
      },
      {
        "no": 118,
        "text": {
          "en": "Any claim for compensation brought against the carrier by way of litigation, arbitration or otherwise in respect of the personal injury or death of a passenger or the loss of or damage to luggage shall, whether or not the claimant is a party to the contract, and whether the claim is founded on contract or on infringement, be subject to the provisions of this Chapter on the defences and limits of liability of the carrier.\nWhere a claim for compensation prescribed in the preceding paragraph is brought against a servant or agent of the carrier, the provisions of the preceding paragraph shall apply if the servant or agent proves that he or she acted within the scope of his or her employment or entrustment."
        },
        "noLabel": {
          "en": "Article 118."
        },
        "chapter": {
          "en": "Chapter V Contract of Carriage of Passengers by Sea"
        }
      },
      {
        "no": 119,
        "text": {
          "en": "Where the carrier entrusts the actual carrier with the whole or part of the carriage of the passenger and his or her luggage, the carrier shall remain responsible for the entire carriage in accordance with the provisions of this Chapter. Where the actual carrier performs the carriage, the carrier shall be responsible for the acts of the actual carrier or of the servants or agents of the actual carrier acting within the scope of their employment or entrustment."
        },
        "noLabel": {
          "en": "Article 119."
        },
        "chapter": {
          "en": "Chapter V Contract of Carriage of Passengers by Sea"
        }
      },
      {
        "no": 120,
        "text": {
          "en": "The provisions of this Chapter on the liability of the carrier shall apply to the actual carrier. The provisions of this Chapter on the liability of the servants or agents of the carrier shall apply to the servants or agents of the actual carrier."
        },
        "noLabel": {
          "en": "Article 120."
        },
        "chapter": {
          "en": "Chapter V Contract of Carriage of Passengers by Sea"
        }
      },
      {
        "no": 121,
        "text": {
          "en": "Any special agreement under which the carrier assumes obligations not prescribed in this Chapter or waives rights conferred by this Chapter shall be effective against the actual carrier only if the actual carrier has expressly consented to it in writing; whether or not the actual carrier consents thereto shall not affect the effect of such special agreement on the carrier."
        },
        "noLabel": {
          "en": "Article 121."
        },
        "chapter": {
          "en": "Chapter V Contract of Carriage of Passengers by Sea"
        }
      },
      {
        "no": 122,
        "text": {
          "en": "Where both the carrier and the actual carrier are liable for compensation, they shall bear joint and several liability within the scope of that liability."
        },
        "noLabel": {
          "en": "Article 122."
        },
        "chapter": {
          "en": "Chapter V Contract of Carriage of Passengers by Sea"
        }
      },
      {
        "no": 123,
        "text": {
          "en": "Where claims for compensation are brought respectively against the carrier, the actual carrier and their servants or agents in respect of the personal injury or death of a passenger or the loss of or damage to luggage, the total amount of compensation shall not exceed the limits prescribed in Article 115 of this Law."
        },
        "noLabel": {
          "en": "Article 123."
        },
        "chapter": {
          "en": "Chapter V Contract of Carriage of Passengers by Sea"
        }
      },
      {
        "no": 124,
        "text": {
          "en": "The provisions of Articles 119 to 123 of this Law shall not affect the right of recourse between the carrier and the actual carrier."
        },
        "noLabel": {
          "en": "Article 124."
        },
        "chapter": {
          "en": "Chapter V Contract of Carriage of Passengers by Sea"
        }
      },
      {
        "no": 125,
        "text": {
          "en": "The carrier or the actual carrier shall take out liability insurance or obtain corresponding financial security in respect of its liability for compensation for the personal injury or death of passengers."
        },
        "noLabel": {
          "en": "Article 125."
        },
        "chapter": {
          "en": "Chapter V Contract of Carriage of Passengers by Sea"
        }
      },
      {
        "no": 126,
        "text": {
          "en": "A claim for compensation for the personal injury or death of a passenger may be brought directly against the liability insurer or the financial guarantor. Where the carrier or the actual carrier has lost the right to limit liability for compensation prescribed in this Chapter, this shall not affect the entitlement of its liability insurer or financial guarantor to avail itself of the provisions of this Chapter limiting liability for compensation.\nThe liability insurer or the financial guarantor shall have the right to defend on the ground that the damage was caused by the intentional act of the carrier or the actual carrier, and shall have the right to avail itself of the defences available to the carrier or the actual carrier other than bankruptcy or liquidation."
        },
        "noLabel": {
          "en": "Article 126."
        },
        "chapter": {
          "en": "Chapter V Contract of Carriage of Passengers by Sea"
        }
      },
      {
        "no": 127,
        "text": {
          "en": "The charter parties prescribed by this Law include voyage charter parties, time charter parties and bareboat charter parties. A charter party shall be concluded in written form."
        },
        "noLabel": {
          "en": "Article 127."
        },
        "chapter": {
          "en": "Section 1 General Provisions"
        }
      },
      {
        "no": 128,
        "text": {
          "en": "The provisions of this Chapter on the rights and obligations between the lessor and the charterer shall apply only where the charter party contains no provision or no different provision on the matter."
        },
        "noLabel": {
          "en": "Article 128."
        },
        "chapter": {
          "en": "Section 1 General Provisions"
        }
      },
      {
        "no": 129,
        "text": {
          "en": "A voyage charter party means a contract under which the shipowner undertakes to provide a ship or part of the ship's space to the charterer for the carriage of the agreed goods from one port to another, and the charterer pays the agreed freight.\nWhere a voyage charter party contains no provision or an unclear provision on the rights and obligations between the lessor and the charterer, the provisions of Chapter IV of this Law on the rights and obligations between the parties shall apply in addition to the provisions of this Section.\nAny clause of a voyage charter party that violates the provisions of Articles 48 and 50 of this Law shall be invalid."
        },
        "noLabel": {
          "en": "Article 129."
        },
        "chapter": {
          "en": "Section 2 Voyage Charter Party"
        }
      },
      {
        "no": 130,
        "text": {
          "en": "The contents of a voyage charter party shall mainly include the names of the lessor and the charterer, the name of the ship, the ship's nationality, the deadweight, the capacity, the name of the goods, the port of loading and the port of destination, the laydays, the laytime for loading and discharging, the freight, the demurrage, the dispatch money and other relevant matters."
        },
        "noLabel": {
          "en": "Article 130."
        },
        "chapter": {
          "en": "Section 2 Voyage Charter Party"
        }
      },
      {
        "no": 131,
        "text": {
          "en": "Where a bill of lading is issued for goods carried under a voyage charter party and the holder of the bill of lading is not the charterer, the rights and obligations between the carrier and the holder of the bill of lading shall be governed by the provisions of the bill of lading. However, where the bill of lading states that the terms of the voyage charter party apply, the terms of that voyage charter party shall apply."
        },
        "noLabel": {
          "en": "Article 131."
        },
        "chapter": {
          "en": "Section 2 Voyage Charter Party"
        }
      },
      {
        "no": 132,
        "text": {
          "en": "The lessor shall provide the agreed ship; the ship may be replaced with the consent of the charterer. Where the ship provided or replaced by the lessor does not conform to the agreement in the contract, the charterer shall have the right to reject it or to terminate the contract.\nWhere the agreed ship is not provided due to the fault of the lessor and the charterer suffers losses as a result, the lessor shall bear liability for compensation."
        },
        "noLabel": {
          "en": "Article 132."
        },
        "chapter": {
          "en": "Section 2 Voyage Charter Party"
        }
      },
      {
        "no": 133,
        "text": {
          "en": "Where the lessor fails to provide the ship within the agreed laydays, the charterer shall have the right to terminate the contract. However, where the lessor notifies the charterer of the delay of the ship and the expected date of the ship's arrival at the port of loading, the charterer shall, within 48 hours from receipt of the notice, notify the lessor of its decision whether or not to terminate the contract.\nWhere the delay in providing the ship is due to the fault of the lessor and the charterer suffers losses as a result, the lessor shall bear liability for compensation."
        },
        "noLabel": {
          "en": "Article 133."
        },
        "chapter": {
          "en": "Section 2 Voyage Charter Party"
        }
      },
      {
        "no": 134,
        "text": {
          "en": "The laytime for loading and discharging and the method of calculating it, the demurrage payable after the expiry of the laytime for loading and discharging, and the dispatch money payable for completing loading and discharging ahead of time shall be agreed by both parties."
        },
        "noLabel": {
          "en": "Article 134."
        },
        "chapter": {
          "en": "Section 2 Voyage Charter Party"
        }
      },
      {
        "no": 135,
        "text": {
          "en": "The charterer may sub-charter the chartered ship; after the sub-charter, the rights and obligations agreed in the original contract shall not be affected."
        },
        "noLabel": {
          "en": "Article 135."
        },
        "chapter": {
          "en": "Section 2 Voyage Charter Party"
        }
      },
      {
        "no": 136,
        "text": {
          "en": "The charterer shall provide the agreed goods; the goods may be replaced with the consent of the lessor. However, where the replacement goods are disadvantageous to the lessor, the lessor shall have the right to refuse or to terminate the contract.\nWhere the agreed goods are not provided and the lessor suffers losses as a result, the charterer shall bear liability for compensation."
        },
        "noLabel": {
          "en": "Article 136."
        },
        "chapter": {
          "en": "Section 2 Voyage Charter Party"
        }
      },
      {
        "no": 137,
        "text": {
          "en": "The lessor shall discharge the goods at the port of discharge agreed in the contract. Where the contract contains a clause allowing the charterer to choose the port of discharge, and the charterer fails to notify the designated port of discharge in a timely manner as agreed in the contract, the master may select one of the agreed optional ports of discharge for discharging the goods. Where the charterer fails to notify the designated port of discharge in a timely manner as agreed in the contract and the lessor suffers losses as a result, the charterer shall bear liability for compensation. Where the lessor, without authorisation, selects a port for discharging the goods in breach of the agreement in the contract and the charterer suffers losses as a result, the lessor shall bear liability for compensation."
        },
        "noLabel": {
          "en": "Article 137."
        },
        "chapter": {
          "en": "Section 2 Voyage Charter Party"
        }
      },
      {
        "no": 138,
        "text": {
          "en": "A time charter party means a contract under which the shipowner undertakes to provide the charterer with a ship crewed by the shipowner as agreed, and the charterer uses the ship for the agreed purpose during the agreed period and pays the hire."
        },
        "noLabel": {
          "en": "Article 138."
        },
        "chapter": {
          "en": "Section 3 Time Charter Party"
        }
      },
      {
        "no": 139,
        "text": {
          "en": "The contents of a time charter party shall mainly include the names of the lessor and the charterer, the name of the ship, the ship's nationality, the ship's class, the tonnage, the capacity, the speed of the ship, the fuel consumption, the trading limits, the purpose, the charter period, the time, place and conditions for delivery and redelivery of the ship, the hire and its payment, and other relevant matters."
        },
        "noLabel": {
          "en": "Article 139."
        },
        "chapter": {
          "en": "Section 3 Time Charter Party"
        }
      },
      {
        "no": 140,
        "text": {
          "en": "The lessor shall deliver the ship at the time agreed in the contract.\nWhere the lessor violates the provisions of the preceding paragraph, the charterer shall have the right to terminate the contract. Where the lessor notifies the charterer of the delay of the ship and the expected date of the ship's arrival at the port of delivery, the charterer shall, within 48 hours from receipt of the notice, notify the lessor of its decision whether to terminate the contract or to continue to charter the ship.\nWhere the delay in providing the ship is due to the fault of the lessor and the charterer suffers losses as a result, the lessor shall bear liability for compensation."
        },
        "noLabel": {
          "en": "Article 140."
        },
        "chapter": {
          "en": "Section 3 Time Charter Party"
        }
      },
      {
        "no": 141,
        "text": {
          "en": "The lessor shall, at the time of delivery of the ship, exercise due diligence to make the ship seaworthy. The ship delivered shall be fit for the agreed purpose.\nWhere the lessor violates the provisions of the preceding paragraph, the charterer shall have the right to terminate the contract and to claim compensation for the losses suffered as a result."
        },
        "noLabel": {
          "en": "Article 141."
        },
        "chapter": {
          "en": "Section 3 Time Charter Party"
        }
      },
      {
        "no": 142,
        "text": {
          "en": "Where, during the charter period, the ship does not conform to the agreed seaworthiness or other agreed condition, the lessor shall take such reasonable measures as may be possible to restore the condition of the ship as soon as possible.\nWhere the ship does not conform to the agreed seaworthiness or other agreed condition and cannot operate normally for a continuous period of 24 hours, the charterer shall not pay hire for the operational time lost as a result, unless the condition was caused by the charterer."
        },
        "noLabel": {
          "en": "Article 142."
        },
        "chapter": {
          "en": "Section 3 Time Charter Party"
        }
      },
      {
        "no": 143,
        "text": {
          "en": "The charterer shall ensure that the ship is employed in the agreed maritime transport between safe ports or places within the agreed trading limits.\nWhere the charterer violates the provisions of the preceding paragraph, the lessor shall have the right to terminate the contract and to claim compensation for the losses suffered as a result."
        },
        "noLabel": {
          "en": "Article 143."
        },
        "chapter": {
          "en": "Section 3 Time Charter Party"
        }
      },
      {
        "no": 144,
        "text": {
          "en": "The charterer shall ensure that the ship is used for the carriage of the agreed lawful goods.\nWhere the charterer uses the ship for the carriage of live animals or dangerous goods, the consent of the lessor shall be obtained in advance.\nWhere the charterer violates the provisions of this Article and the lessor suffers losses as a result, the charterer shall bear liability for compensation."
        },
        "noLabel": {
          "en": "Article 144."
        },
        "chapter": {
          "en": "Section 3 Time Charter Party"
        }
      },
      {
        "no": 145,
        "text": {
          "en": "The charterer shall have the right to give instructions to the master in respect of the operation of the ship, provided that such instructions shall not be contrary to the agreement in the time charter party."
        },
        "noLabel": {
          "en": "Article 145."
        },
        "chapter": {
          "en": "Section 3 Time Charter Party"
        }
      },
      {
        "no": 146,
        "text": {
          "en": "The charterer may sub-charter the chartered ship, provided that the charterer shall promptly notify the lessor of the sub-charter. After the sub-charter of the chartered ship, the rights and obligations agreed in the original charter party shall not be affected."
        },
        "noLabel": {
          "en": "Article 146."
        },
        "chapter": {
          "en": "Section 3 Time Charter Party"
        }
      },
      {
        "no": 147,
        "text": {
          "en": "Where the shipowner transfers the ownership of a ship already chartered, the rights and obligations of the parties agreed in the time charter party shall not be affected, provided that the charterer shall be promptly notified. After the transfer of ownership of the ship, the original charter party shall continue to be performed by the transferee and the charterer."
        },
        "noLabel": {
          "en": "Article 147."
        },
        "chapter": {
          "en": "Section 3 Time Charter Party"
        }
      },
      {
        "no": 148,
        "text": {
          "en": "Where, during the term of the contract, the ship engages in salvage at sea, the charterer shall be entitled to 50 per cent of the salvage remuneration after deducting the salvage expenses, compensation for damage, the portion due to the crew and other expenses."
        },
        "noLabel": {
          "en": "Article 148."
        },
        "chapter": {
          "en": "Section 3 Time Charter Party"
        }
      },
      {
        "no": 149,
        "text": {
          "en": "The charterer shall pay the hire in accordance with the agreement in the contract; where the charterer fails to pay the hire in accordance with the agreement in the contract, the lessor shall have the right to terminate the contract and to claim compensation for the losses suffered as a result."
        },
        "noLabel": {
          "en": "Article 149."
        },
        "chapter": {
          "en": "Section 3 Time Charter Party"
        }
      },
      {
        "no": 150,
        "text": {
          "en": "Where the charterer fails to pay the hire or other sums agreed in the contract to the lessor, the lessor shall have a lien on the goods and property on board belonging to the charterer and on the income from the sub-charter of the ship."
        },
        "noLabel": {
          "en": "Article 150."
        },
        "chapter": {
          "en": "Section 3 Time Charter Party"
        }
      },
      {
        "no": 151,
        "text": {
          "en": "When the charterer redelivers the ship to the lessor, the ship shall be in the same good condition as at the time of delivery by the lessor, except for the natural wear and tear of the ship itself.\nWhere the ship has not been maintained in the same good condition as at the time of delivery, the charterer shall be responsible for repairing it or for paying compensation."
        },
        "noLabel": {
          "en": "Article 151."
        },
        "chapter": {
          "en": "Section 3 Time Charter Party"
        }
      },
      {
        "no": 152,
        "text": {
          "en": "Where, upon reasonable calculation, the date of completion of the final voyage is approximately the date of redelivery agreed in the contract but may exceed the date of redelivery agreed in the contract, the charterer shall have the right to use the ship beyond the charter period in order to complete that voyage. During the period of overrun, the charterer shall pay hire at the rate of hire agreed in the contract; where the market rate of hire is higher than the rate of hire agreed in the contract, the charterer shall pay hire at the market rate of hire."
        },
        "noLabel": {
          "en": "Article 152."
        },
        "chapter": {
          "en": "Section 3 Time Charter Party"
        }
      },
      {
        "no": 153,
        "text": {
          "en": "A bareboat charter party means a contract under which the lessor of a ship provides the charterer with a ship without crew, which the charterer possesses, uses and operates during the agreed period, and pays hire to the lessor."
        },
        "noLabel": {
          "en": "Article 153."
        },
        "chapter": {
          "en": "Section 4 Bareboat Charter Party"
        }
      },
      {
        "no": 154,
        "text": {
          "en": "The contents of a bareboat charter party shall mainly include the names of the lessor and the charterer, the name of the ship, the ship's nationality, the ship's class, the tonnage, the capacity, the trading limits, the purpose, the charter period, the time, place and conditions for delivery and redelivery of the ship, the survey of the ship, the maintenance and repair of the ship, the hire and its payment, the insurance of the ship, the time and conditions for termination of the contract, and other relevant matters."
        },
        "noLabel": {
          "en": "Article 154."
        },
        "chapter": {
          "en": "Section 4 Bareboat Charter Party"
        }
      },
      {
        "no": 155,
        "text": {
          "en": "The lessor shall, at the port or place agreed in the contract and at the time agreed in the contract, deliver the ship and the ship's certificates to the charterer. In delivering the ship, the lessor shall exercise due diligence to make the ship seaworthy. The ship delivered shall be fit for the purpose agreed in the contract.\nWhere the lessor violates the provisions of the preceding paragraph, the charterer shall have the right to terminate the contract and to claim compensation for the losses suffered as a result."
        },
        "noLabel": {
          "en": "Article 155."
        },
        "chapter": {
          "en": "Section 4 Bareboat Charter Party"
        }
      },
      {
        "no": 156,
        "text": {
          "en": "During the bareboat charter period, the charterer shall be responsible for the maintenance and repair of the ship."
        },
        "noLabel": {
          "en": "Article 156."
        },
        "chapter": {
          "en": "Section 4 Bareboat Charter Party"
        }
      },
      {
        "no": 157,
        "text": {
          "en": "During the bareboat charter period, the charterer shall insure the ship for the value of the ship agreed in the contract, in a manner of insurance agreed by the lessor, and shall bear the insurance premium."
        },
        "noLabel": {
          "en": "Article 157."
        },
        "chapter": {
          "en": "Section 4 Bareboat Charter Party"
        }
      },
      {
        "no": 158,
        "text": {
          "en": "During the bareboat charter period, where the interests of the lessor are affected or losses are suffered as a result of the possession, use and operation of the ship by the charterer, the charterer shall be responsible for eliminating the effects or for compensating for the losses.\nWhere the ship is arrested as a result of a dispute over the ownership of the ship or of debts owed by the lessor, the lessor shall ensure that the interests of the charterer are not affected; where the charterer suffers losses as a result, the lessor shall bear liability for compensation."
        },
        "noLabel": {
          "en": "Article 158."
        },
        "chapter": {
          "en": "Section 4 Bareboat Charter Party"
        }
      },
      {
        "no": 159,
        "text": {
          "en": "During the bareboat charter period, the charterer shall not, without the written consent of the lessor, assign the rights and obligations under the contract or sub-charter the ship by way of bareboat charter."
        },
        "noLabel": {
          "en": "Article 159."
        },
        "chapter": {
          "en": "Section 4 Bareboat Charter Party"
        }
      },
      {
        "no": 160,
        "text": {
          "en": "Without the prior written consent of the charterer, the lessor shall not create a mortgage on the ship during the bareboat charter period.\nWhere the lessor violates the provisions of the preceding paragraph and the charterer suffers losses as a result, the lessor shall bear liability for compensation."
        },
        "noLabel": {
          "en": "Article 160."
        },
        "chapter": {
          "en": "Section 4 Bareboat Charter Party"
        }
      },
      {
        "no": 161,
        "text": {
          "en": "The charterer shall pay the hire as agreed in the contract. Where the charterer fails to pay the hire at the time agreed in the contract for more than seven consecutive days, the lessor shall have the right to terminate the contract and to claim compensation for the losses suffered as a result.\nWhere the ship is lost or missing, the hire shall cease to be paid from the date of the loss of the ship or of the receipt of the last news of it, and hire paid in advance shall be refunded in proportion."
        },
        "noLabel": {
          "en": "Article 161."
        },
        "chapter": {
          "en": "Section 4 Bareboat Charter Party"
        }
      },
      {
        "no": 162,
        "text": {
          "en": "The provisions of Article 143, paragraph 1 of Article 144, Article 151 and Article 152 of this Law shall apply to bareboat charter parties."
        },
        "noLabel": {
          "en": "Article 162."
        },
        "chapter": {
          "en": "Section 4 Bareboat Charter Party"
        }
      },
      {
        "no": 163,
        "text": {
          "en": "Where a bareboat charter party contains a hire-purchase clause, the ownership of the ship shall vest in the charterer when the charterer has paid the hire-purchase payments in full to the lessor as agreed in the contract."
        },
        "noLabel": {
          "en": "Article 163."
        },
        "chapter": {
          "en": "Section 4 Bareboat Charter Party"
        }
      },
      {
        "no": 164,
        "text": {
          "en": "A contract of maritime towage means a contract under which the towage operator tows the tow by sea from one place to another by means of a tug, and the tow party pays the towage fee.\nThe provisions of this Chapter shall not apply to tug services provided to ships within a port area."
        },
        "noLabel": {
          "en": "Article 164."
        },
        "chapter": {
          "en": "Chapter VII Contract of Sea Towage"
        }
      },
      {
        "no": 165,
        "text": {
          "en": "A contract of maritime towage shall be concluded in written form. The contents of a contract of maritime towage shall mainly include the names and domiciles of the towage operator and the tow party, the names and principal dimensions of the tug and the tow, the horsepower of the tug, the place of departure and the destination, the date of commencement of the towage, the towage fee and the method of its payment, and other relevant matters."
        },
        "noLabel": {
          "en": "Article 165."
        },
        "chapter": {
          "en": "Chapter VII Contract of Sea Towage"
        }
      },
      {
        "no": 166,
        "text": {
          "en": "Before and at the time of commencement of the towage, the towage operator shall exercise due diligence to make the tug seaworthy and fit for towage, to man the tug properly, to provide towage gear and supplies and other equipment and installations necessary for the voyage.\nBefore and at the time of commencement of the towage, the tow party shall make preparations for the towage of the tow, exercise due diligence to make the tow fit for towage, truthfully inform the towage operator of the condition of the tow, and provide, in accordance with the provisions, the certificates and relevant documents issued by the relevant survey institution certifying that the tow is fit for towage."
        },
        "noLabel": {
          "en": "Article 166."
        },
        "chapter": {
          "en": "Chapter VII Contract of Sea Towage"
        }
      },
      {
        "no": 167,
        "text": {
          "en": "Where, before the commencement of the towage, the contract cannot be performed due to force majeure or other causes not attributable to either party, either party may terminate the contract, and neither party shall be liable for compensation to the other. Unless otherwise agreed in the contract, the towage fee already paid shall be refunded by the towage operator to the tow party."
        },
        "noLabel": {
          "en": "Article 167."
        },
        "chapter": {
          "en": "Chapter VII Contract of Sea Towage"
        }
      },
      {
        "no": 168,
        "text": {
          "en": "Where, after the commencement of the towage, the contract cannot continue to be performed due to force majeure or other causes not attributable to either party, either party may terminate the contract, and neither party shall be liable for compensation to the other. Unless otherwise agreed in the contract, the towage fee shall be determined according to the part of the towage actually completed."
        },
        "noLabel": {
          "en": "Article 168."
        },
        "chapter": {
          "en": "Chapter VII Contract of Sea Towage"
        }
      },
      {
        "no": 169,
        "text": {
          "en": "Where the tow cannot be towed to the destination due to force majeure or other causes not attributable to either party, unless otherwise agreed in the contract, the towage operator may deliver the tow to the tow party or its agent at a place adjacent to the destination or at a safe port or anchorage selected by the master of the tug, and the contract shall be deemed to have been performed."
        },
        "noLabel": {
          "en": "Article 169."
        },
        "chapter": {
          "en": "Chapter VII Contract of Sea Towage"
        }
      },
      {
        "no": 170,
        "text": {
          "en": "Where the tow party fails to pay the towage fee and other reasonable expenses as agreed, the towage operator shall have a lien on the tow."
        },
        "noLabel": {
          "en": "Article 170."
        },
        "chapter": {
          "en": "Chapter VII Contract of Sea Towage"
        }
      },
      {
        "no": 171,
        "text": {
          "en": "Where losses are suffered by the towage operator or the tow party in the course of maritime towage and are caused by the fault of one party, the party at fault shall bear liability for compensation; where the losses are caused by the fault of both parties, each party shall bear liability for compensation in proportion to the degree of its fault.\nNotwithstanding the provisions of the preceding paragraph, the towage operator shall not be liable for compensation where it proves that the losses of the tow party were caused by any of the following:\n(a) fault of the master, the crew or the pilot of the tug, or of other servants or agents of the towage operator, in the navigation or management of the tug;\n(b) fault of the tug in salvage at sea or in attempting to salvage persons or property.\nThe provisions of this Article shall apply only where the contract of maritime towage contains no provision or no different provision."
        },
        "noLabel": {
          "en": "Article 171."
        },
        "chapter": {
          "en": "Chapter VII Contract of Sea Towage"
        }
      },
      {
        "no": 172,
        "text": {
          "en": "Where, in the course of maritime towage, the fault of the towage operator or of the tow party causes the personal injury or death of, or property loss to, a third party, the towage operator and the tow party shall bear joint and several liability for compensation to the third party. Unless otherwise agreed in the contract, where the compensation paid by one party exceeds the proportion it should bear, it shall have the right of recourse against the other party."
        },
        "noLabel": {
          "en": "Article 172."
        },
        "chapter": {
          "en": "Chapter VII Contract of Sea Towage"
        }
      },
      {
        "no": 173,
        "text": {
          "en": "Where the owner of a tug tows a barge owned or operated by it for the carriage of goods from one port to another by sea, such carriage shall be deemed carriage of goods by sea."
        },
        "noLabel": {
          "en": "Article 173."
        },
        "chapter": {
          "en": "Chapter VII Contract of Sea Towage"
        }
      },
      {
        "no": 174,
        "text": {
          "en": "Collision of ships means an accident in which damage is caused by the contact of ships on the sea or in navigable waters connected with the sea.\nThe provisions of this Chapter shall apply to a collision between a ship and any other craft, not being a ship, that is not used for military or government service."
        },
        "noLabel": {
          "en": "Article 174."
        },
        "chapter": {
          "en": "Chapter VIII Collision of Ships"
        }
      },
      {
        "no": 175,
        "text": {
          "en": "Where ships collide, the masters of the ships concerned shall, on condition that the safety of their own ships and of the persons on board is not seriously endangered, do their utmost to rescue the other ship and the persons on board.\nThe masters of the colliding ships shall, as far as possible, notify the other ship of the name of their ship, the port of registry, the port of departure and the port of destination."
        },
        "noLabel": {
          "en": "Article 175."
        },
        "chapter": {
          "en": "Chapter VIII Collision of Ships"
        }
      },
      {
        "no": 176,
        "text": {
          "en": "Where a collision of ships is caused by force majeure or other causes not attributable to any party, or by causes that cannot be ascertained, the parties to the collision shall not be liable for compensation to each other."
        },
        "noLabel": {
          "en": "Article 176."
        },
        "chapter": {
          "en": "Chapter VIII Collision of Ships"
        }
      },
      {
        "no": 177,
        "text": {
          "en": "Where a collision of ships is caused by the fault of one ship, the ship at fault shall bear liability for compensation."
        },
        "noLabel": {
          "en": "Article 177."
        },
        "chapter": {
          "en": "Chapter VIII Collision of Ships"
        }
      },
      {
        "no": 178,
        "text": {
          "en": "Where ships collide and the colliding ships are both at fault, each ship shall bear liability for compensation in proportion to the degree of its fault; where the degrees of fault are equal or the proportions of fault cannot be determined, they shall bear liability for compensation equally.\nThe ships both at fault shall, in respect of the loss of or damage to the ships and the goods and other property on board caused by the collision, bear liability for compensation in the proportions prescribed in the preceding paragraph. Where the collision causes property loss to a third party, the liability for compensation of each ship shall not exceed the proportion it should bear.\nThe ships both at fault shall bear joint and several liability for compensation in respect of the personal injury or death of a third party caused by the collision. Where the compensation paid by one ship exceeds the proportion prescribed in paragraph 1 of this Article, that ship shall have the right of recourse against the other ship at fault."
        },
        "noLabel": {
          "en": "Article 178."
        },
        "chapter": {
          "en": "Chapter VIII Collision of Ships"
        }
      },
      {
        "no": 179,
        "text": {
          "en": "Where a ship, through improper manoeuvring or failure to comply with the navigation regulations, does not actually come into collision with another ship but causes losses to the other ship or to the persons, goods or other property on board, the provisions of this Chapter shall apply."
        },
        "noLabel": {
          "en": "Article 179."
        },
        "chapter": {
          "en": "Chapter VIII Collision of Ships"
        }
      },
      {
        "no": 180,
        "text": {
          "en": "The provisions of this Chapter shall apply to salvage rendered to a ship or other property in danger on the sea or in navigable waters connected with the sea.\nThe provisions of this Chapter shall apply to a salvage relationship between a ship and any other craft, not being a ship, that is not used for military or government service.\nExcept for the provisions of Article 185 of this Law on the cancellation or modification of salvage contracts and the provisions of Articles 186 and 187 on the prevention or mitigation of damage to the ecological environment, the other provisions of this Chapter shall apply only where the salvage contract contains no provision or no different provision."
        },
        "noLabel": {
          "en": "Article 180."
        },
        "chapter": {
          "en": "Chapter IX Salvage at Sea"
        }
      },
      {
        "no": 181,
        "text": {
          "en": "The following terms used in this Chapter have the following meanings:\n(a) property means any property not permanently and intentionally attached to the shoreline, including freight at risk;\n(b) salvage remuneration means any salvage reward, bonus or compensation payable by the salved party to the salvor in accordance with the provisions of this Chapter."
        },
        "noLabel": {
          "en": "Article 181."
        },
        "chapter": {
          "en": "Chapter IX Salvage at Sea"
        }
      },
      {
        "no": 182,
        "text": {
          "en": "The provisions of this Chapter shall not apply to fixed or floating platforms and mobile offshore drilling units already in position at sea engaged in the exploration, exploitation or production of seabed mineral resources."
        },
        "noLabel": {
          "en": "Article 182."
        },
        "chapter": {
          "en": "Chapter IX Salvage at Sea"
        }
      },
      {
        "no": 183,
        "text": {
          "en": "The master shall be obliged to render every possible assistance to persons in danger at sea in so far as this does not seriously endanger the safety of the ship and the persons on board."
        },
        "noLabel": {
          "en": "Article 183."
        },
        "chapter": {
          "en": "Chapter IX Salvage at Sea"
        }
      },
      {
        "no": 184,
        "text": {
          "en": "A salvage contract is concluded when the salvor and the salved party reach an agreement on salvage at sea.\nThe master of a ship in danger shall have the right to conclude salvage contracts on behalf of the shipowner. The master or the shipowner of a ship in danger shall have the right to conclude salvage contracts on behalf of the owners of the property on board."
        },
        "noLabel": {
          "en": "Article 184."
        },
        "chapter": {
          "en": "Chapter IX Salvage at Sea"
        }
      },
      {
        "no": 185,
        "text": {
          "en": "Under any of the following circumstances, where a party files a lawsuit or the parties agree to arbitration, the court or arbitral institution hearing the dispute may rescind or modify the salvage contract:\n(a) the contract was concluded under duress or under the influence of danger and its terms are manifestly unfair;\n(b) the salvage remuneration payable under the contract is manifestly excessive or manifestly insufficient in relation to the salvage services actually rendered."
        },
        "noLabel": {
          "en": "Article 185."
        },
        "chapter": {
          "en": "Chapter IX Salvage at Sea"
        }
      },
      {
        "no": 186,
        "text": {
          "en": "During salvage operations, the salvor shall owe the following obligations to the salved party:\n(a) carrying out the salvage with due care;\n(b) preventing or minimising damage to the ecological environment with due care;\n(c) seeking the assistance of other salvors where reasonably necessary;\n(d) accepting a reasonable request of the salved party that other salvors participate in the salvage operations, provided that where such a request is unreasonable, the amount of salvage remuneration of the original salvor shall not be affected."
        },
        "noLabel": {
          "en": "Article 186."
        },
        "chapter": {
          "en": "Chapter IX Salvage at Sea"
        }
      },
      {
        "no": 187,
        "text": {
          "en": "During salvage operations, the salved party shall owe the following obligations to the salvor:\n(a) cooperating fully with the salvor;\n(b) preventing or minimising damage to the ecological environment with due care;\n(c) accepting, in a timely manner, the reasonable request of the salvor for the handover of the salved ship or other property when it has been brought to a place of safety."
        },
        "noLabel": {
          "en": "Article 187."
        },
        "chapter": {
          "en": "Chapter IX Salvage at Sea"
        }
      },
      {
        "no": 188,
        "text": {
          "en": "Where the salvage of a ship in danger and other property by the salvor has produced a useful result, the salvor shall be entitled to salvage remuneration; where no useful result has been produced, the salvor shall not be entitled to salvage remuneration, unless otherwise provided in Article 191 of this Law or other laws."
        },
        "noLabel": {
          "en": "Article 188."
        },
        "chapter": {
          "en": "Chapter IX Salvage at Sea"
        }
      },
      {
        "no": 189,
        "text": {
          "en": "In determining the salvage remuneration, the encouragement of salvage operations shall be reflected and the following factors shall be taken into comprehensive consideration:\n(a) the value of the ship and other property salved;\n(b) the skill and efforts of the salvor in preventing or minimising damage to the ecological environment;\n(c) the measure of success obtained by the salvor;\n(d) the nature and degree of the danger;\n(e) the skill and efforts of the salvor in salving the ship, other property and human life;\n(f) the time used, the expenses incurred and the losses suffered by the salvor;\n(g) the risk of liability and other risks facing the salvor or the salvage equipment;\n(h) the promptness of the salvage services provided by the salvor;\n(i) the availability and use of ships and other equipment for salvage operations;\n(j) the state of readiness, efficiency and value of the salvage equipment.\nThe salvage remuneration shall not exceed the value of the ship and other property salved."
        },
        "noLabel": {
          "en": "Article 189."
        },
        "chapter": {
          "en": "Chapter IX Salvage at Sea"
        }
      },
      {
        "no": 190,
        "text": {
          "en": "The value of the ship and other property salved means the estimated value or the actual proceeds of sale of the ship and other property after salvage, after deducting the relevant taxes and customs, quarantine and inspection expenses and the expenses incurred in discharging, storing, valuing and selling the same.\nThe value salved prescribed in the preceding paragraph shall not include the value of the personal effects of the crew and the cabin luggage of passengers that have been salved."
        },
        "noLabel": {
          "en": "Article 190."
        },
        "chapter": {
          "en": "Chapter IX Salvage at Sea"
        }
      },
      {
        "no": 191,
        "text": {
          "en": "Where, in respect of salvage operations carried out on a ship or goods on board that threatened damage to the ecological environment, the salvage remuneration obtained by the salvor in accordance with the provisions of Article 189 of this Law is less than the special compensation that may be obtained in accordance with the provisions of this Article, the salvor shall be entitled to special compensation equivalent to the salvage expenses from the shipowner.\nWhere the salvage operations prescribed in the preceding paragraph carried out by the salvor have the effect of preventing or minimising damage to the ecological environment, the special compensation payable by the shipowner to the salvor in accordance with the provisions of the preceding paragraph may be increased, and the increase may reach 30 per cent of the salvage expenses. Where the court or arbitral institution hearing the dispute considers it appropriate, having regard to the provisions of paragraph 1 of Article 189 of this Law, it may award or rule a further increase in the amount of special compensation; however, in no circumstances shall the increase exceed 100 per cent of the salvage expenses.\nThe salvage expenses referred to in this Article mean the reasonable expenses directly incurred by the salvor in the salvage operations and the reasonable expenses for the actual use of salvage equipment and the deployment of salvage personnel. In determining the salvage expenses, the provisions of subparagraphs (h) to (j) of paragraph 1 of Article 189 of this Law shall be taken into consideration.\nIn no circumstances shall the total special compensation provided for in this Article be paid unless and to the extent that it exceeds the salvage remuneration that the salvor is entitled to obtain in accordance with the provisions of Article 189 of this Law, and the amount paid shall be the amount by which the special compensation exceeds the salvage remuneration.\nWhere the salvor has failed, through its fault, to prevent or minimise damage to the ecological environment, the salvor may be deprived, in whole or in part, of its right to special compensation.\nThe provisions of this Article shall not affect the right of recourse of the shipowner against other salved parties."
        },
        "noLabel": {
          "en": "Article 191."
        },
        "chapter": {
          "en": "Chapter IX Salvage at Sea"
        }
      },
      {
        "no": 192,
        "text": {
          "en": "The amount of salvage remuneration shall be borne by the respective owners of the salved ship and other property in proportion to the value of each of the ship and other items of property salved to the total value salved."
        },
        "noLabel": {
          "en": "Article 192."
        },
        "chapter": {
          "en": "Chapter IX Salvage at Sea"
        }
      },
      {
        "no": 193,
        "text": {
          "en": "The salvage remuneration of the salvors participating in the same salvage operation shall be determined by agreement among the salvors in accordance with the criteria prescribed in Article 189 of this Law; where agreement cannot be reached, they may file a lawsuit with a court or, by agreement among them, apply for arbitration."
        },
        "noLabel": {
          "en": "Article 193."
        },
        "chapter": {
          "en": "Chapter IX Salvage at Sea"
        }
      },
      {
        "no": 194,
        "text": {
          "en": "A salvor who has saved human life in salvage operations shall not claim remuneration from the persons saved, but shall be entitled to a fair share of the salvage remuneration paid to the salvor who saved the ship or other property or prevented or minimised damage to the ecological environment."
        },
        "noLabel": {
          "en": "Article 194."
        },
        "chapter": {
          "en": "Chapter IX Salvage at Sea"
        }
      },
      {
        "no": 195,
        "text": {
          "en": "The following salvage operations shall not be entitled to salvage remuneration:\n(a) salvage operations carried out in the normal performance of obligations under a towage contract or other service contract, except where services of an exceptional character outside the performance of such obligations are rendered;\n(b) salvage operations carried out despite the express and reasonable refusal of the master, the shipowner or the owner of other property in danger."
        },
        "noLabel": {
          "en": "Article 195."
        },
        "chapter": {
          "en": "Chapter IX Salvage at Sea"
        }
      },
      {
        "no": 196,
        "text": {
          "en": "Where the salvage operations have become necessary or more difficult through the fault of the salvor, or where the salvor has been guilty of fraud or other dishonest conduct, the salvage remuneration payable to the salvor shall be reduced or forfeited."
        },
        "noLabel": {
          "en": "Article 196."
        },
        "chapter": {
          "en": "Chapter IX Salvage at Sea"
        }
      },
      {
        "no": 197,
        "text": {
          "en": "Upon the completion of the salvage operations, the salved party shall, at the request of the salvor, provide satisfactory security for the salvage remuneration.\nWithout prejudice to the provisions of the preceding paragraph, the shipowner of the salved ship shall, before the salved goods are returned, use its best endeavours to ensure that the owner of the goods provides satisfactory security for the salvage remuneration for which the owner of the goods is liable.\nBefore satisfactory security for the salved ship or other property has been provided at the request of the salvor, the salved ship and other property shall not, without the consent of the salvor, be removed from the port or place at which they first arrived after the completion of the salvage operations."
        },
        "noLabel": {
          "en": "Article 197."
        },
        "chapter": {
          "en": "Chapter IX Salvage at Sea"
        }
      },
      {
        "no": 198,
        "text": {
          "en": "The court or arbitral institution hearing a claim for salvage remuneration may, in the light of the specific circumstances and on reasonable conditions, order or award that the salved party make an appropriate advance payment to the salvor.\nWhere the salved party has made an advance payment in accordance with the provisions of the preceding paragraph, the amount of security provided by it in accordance with the provisions of Article 197 of this Law shall be reduced accordingly."
        },
        "noLabel": {
          "en": "Article 198."
        },
        "chapter": {
          "en": "Chapter IX Salvage at Sea"
        }
      },
      {
        "no": 199,
        "text": {
          "en": "Where, in respect of a salved ship or other property that has been salved for 90 days, the salved party neither pays the salvage remuneration nor provides satisfactory security, the salvor may apply to a court for an order of compulsory auction; where the salved ship or other property cannot be preserved, is difficult to preserve or is likely to be subject to preservation expenses exceeding its value, the salvor may apply for an early auction.\nThe proceeds of the auction shall, after deducting all expenses incurred in the preservation and auction, be applied to the payment of the salvage remuneration in accordance with the provisions of this Law; the surplus, if any, shall be returned to the salved party, and where it cannot be returned and remains unclaimed for one year from the date of the auction, it shall belong to the State; where the amount is insufficient, the salvor shall have the right to recover the difference from the salved party."
        },
        "noLabel": {
          "en": "Article 199."
        },
        "chapter": {
          "en": "Chapter IX Salvage at Sea"
        }
      },
      {
        "no": 200,
        "text": {
          "en": "The provisions of this Chapter shall apply to the right of the salvor to salvage remuneration in respect of salvage operations carried out between ships belonging to the same shipowner."
        },
        "noLabel": {
          "en": "Article 200."
        },
        "chapter": {
          "en": "Chapter IX Salvage at Sea"
        }
      },
      {
        "no": 201,
        "text": {
          "en": "Where salvage operations are carried out or controlled by the relevant competent authority of the State, the salvor shall be entitled to the rights and compensation in respect of salvage operations prescribed in this Chapter."
        },
        "noLabel": {
          "en": "Article 201."
        },
        "chapter": {
          "en": "Chapter IX Salvage at Sea"
        }
      },
      {
        "no": 202,
        "text": {
          "en": "General average means the extraordinary sacrifice or expenditure intentionally and reasonably made or incurred for the common safety for the purpose of preserving the ship, cargo and other property from a common danger in the same maritime adventure.\nLosses sustained by the ship or cargo through delay, whether during or after the voyage, including loss of freight and loss of market, and other indirect losses, shall not be allowed as general average.\nLoss or expense caused by the leakage of pollutants from the ship, cargo or other property in the same maritime adventure shall not be allowed as general average."
        },
        "noLabel": {
          "en": "Article 202."
        },
        "chapter": {
          "en": "Chapter X General Average"
        }
      },
      {
        "no": 203,
        "text": {
          "en": "Where a ship is damaged by accident, sacrifice or other extraordinary circumstance and, in order to complete the voyage in safety, puts into a port of refuge or a place of refuge or puts back to the port or place of loading for necessary repairs, the port charges paid, the wages and provisions of the crew and the fuel and stores consumed by the ship during the extra period of detention at such port or place, and the loss or expense incurred in discharging, storing, reloading or moving the cargo, fuel, stores and other property on board for the purpose of the repairs, shall be allowed as general average."
        },
        "noLabel": {
          "en": "Article 203."
        },
        "chapter": {
          "en": "Chapter X General Average"
        }
      },
      {
        "no": 204,
        "text": {
          "en": "Extra expense incurred in substitution for an extraordinary expenditure that would have been allowable as general average may be allowed as general average as a substituted expense; however, the amount allowed as general average for the substituted expense shall not exceed the extraordinary expenditure of general average that it has replaced."
        },
        "noLabel": {
          "en": "Article 204."
        },
        "chapter": {
          "en": "Chapter X General Average"
        }
      },
      {
        "no": 205,
        "text": {
          "en": "A party claiming contribution in general average shall bear the burden of proving that the loss claimed ought to be allowed as general average."
        },
        "noLabel": {
          "en": "Article 205."
        },
        "chapter": {
          "en": "Chapter X General Average"
        }
      },
      {
        "no": 206,
        "text": {
          "en": "The fact that the accident giving rise to the extraordinary sacrifice or expenditure in general average may have been caused by the fault of one of the parties to the adventure shall not affect the right of that party to claim contribution in general average; however, the party not at fault, or the party at fault, may make a claim for compensation or raise a defence in respect of that fault."
        },
        "noLabel": {
          "en": "Article 206."
        },
        "chapter": {
          "en": "Chapter X General Average"
        }
      },
      {
        "no": 207,
        "text": {
          "en": "The amount of general average sacrifice of the ship, cargo and freight shall be determined in accordance with the following provisions:\n(a) the amount of general average sacrifice of the ship shall be calculated on the basis of the reasonable cost of repairs actually paid, after deducting a reasonable allowance for new material replacing old;\nWhere the ship has not yet been repaired, the amount shall be calculated on the basis of the reasonable depreciation resulting from the sacrifice, but shall not exceed the estimated cost of repairs.\nWhere the ship has suffered an actual total loss or the cost of repairs exceeds the value of the ship after repair, the amount of general average sacrifice shall be calculated as the estimated sound value of the ship, less the estimated cost of repairs of damage not allowable as general average and the value of the ship after the damage.\n(b) the amount of general average sacrifice of cargo shall be calculated, where the cargo is lost, as the value of the cargo at the time of shipment plus insurance and freight, less the freight that has not been incurred by reason of the sacrifice;\nWhere the cargo is damaged and is sold before an agreement is reached on the extent of the damage, the amount shall be calculated as the difference between the value of the cargo at the time of shipment plus insurance and freight and the net proceeds of the sale of the cargo.\n(c) the amount of general average sacrifice of freight shall be calculated as the amount of freight lost by reason of the sacrifice of the cargo, less the operating expenses that would have been incurred in earning that freight but have not been incurred by reason of the sacrifice."
        },
        "noLabel": {
          "en": "Article 207."
        },
        "chapter": {
          "en": "Chapter X General Average"
        }
      },
      {
        "no": 208,
        "text": {
          "en": "General average shall be contributed by the benefited parties in proportion to their respective contributory values.\nThe contributory values of the ship, cargo and freight in general average shall be determined respectively in accordance with the following provisions:\n(a) the contributory value of the ship in general average shall be calculated as the sound value of the ship at the termination of the voyage, less the amount of damage not allowable as general average, or as the actual value of the ship at the termination of the voyage, plus the amount of general average sacrifice;\n(b) the contributory value of the cargo in general average shall be calculated as the value of the cargo at the time of shipment plus insurance and freight, less the amount of damage not allowable as general average and the freight at the risk of the carrier;\nWhere the cargo is sold before arrival at the port of destination, the contributory value shall be calculated as the net proceeds of the sale plus the amount of general average sacrifice.\nThe luggage and personal effects of passengers shall not contribute to general average.\n(c) the contributory value of freight shall be calculated as the freight at the risk of the carrier and receivable at the termination of the voyage, less the operating expenses incurred after the general average accident in completing the voyage for the purpose of earning that freight, plus the amount of general average sacrifice."
        },
        "noLabel": {
          "en": "Article 208."
        },
        "chapter": {
          "en": "Chapter X General Average"
        }
      },
      {
        "no": 209,
        "text": {
          "en": "Undeclared or misdeclared cargo shall contribute to general average; the extraordinary sacrifice sustained by such cargo shall not be allowed as general average.\nWhere the value declared is improperly lower than the actual value of the cargo, contribution to general average shall be made on the basis of the actual value; where general average sacrifice occurs, the amount of the sacrifice shall be calculated on the basis of the declared value."
        },
        "noLabel": {
          "en": "Article 209."
        },
        "chapter": {
          "en": "Chapter X General Average"
        }
      },
      {
        "no": 210,
        "text": {
          "en": "Interest shall be allowed on general average sacrifice and on general average expenditure advanced."
        },
        "noLabel": {
          "en": "Article 210."
        },
        "chapter": {
          "en": "Chapter X General Average"
        }
      },
      {
        "no": 211,
        "text": {
          "en": "At the request of an interested party, each contributing party shall provide general average security.\nWhere general average security is provided by way of a deposit, the deposit shall be delivered to the average adjuster and deposited in a bank in the name of a custodian.\nThe provision, use or refund of the deposit shall not affect the ultimate liability of the parties for contribution."
        },
        "noLabel": {
          "en": "Article 211."
        },
        "chapter": {
          "en": "Chapter X General Average"
        }
      },
      {
        "no": 212,
        "text": {
          "en": "The adjustment of general average shall be governed by the adjustment rules agreed in the contract; where no adjustment rules are agreed in the contract, the provisions of this Chapter shall apply."
        },
        "noLabel": {
          "en": "Article 212."
        },
        "chapter": {
          "en": "Chapter X General Average"
        }
      },
      {
        "no": 213,
        "text": {
          "en": "A shipowner or salvor may, in respect of a maritime claim prescribed in Article 216 of this Law, limit liability for compensation in accordance with the provisions of this Chapter.\nThe provisions of this Chapter relating to shipowners shall apply to charterers, ship operators and ship managers."
        },
        "noLabel": {
          "en": "Article 213."
        },
        "chapter": {
          "en": "Chapter XI Limitation of Liability for Maritime Claims"
        }
      },
      {
        "no": 214,
        "text": {
          "en": "Where a maritime claim prescribed in Article 216 of this Law is made against a person other than the shipowner or salvor, and the shipowner or salvor is liable for the acts or faults of that person, that person may limit liability for compensation in accordance with the provisions of this Chapter."
        },
        "noLabel": {
          "en": "Article 214."
        },
        "chapter": {
          "en": "Chapter XI Limitation of Liability for Maritime Claims"
        }
      },
      {
        "no": 215,
        "text": {
          "en": "Where the insured may limit liability for compensation in accordance with the provisions of this Chapter, the insurer liable for the maritime claim shall be entitled to the same limitation of liability in accordance with the provisions of this Chapter."
        },
        "noLabel": {
          "en": "Article 215."
        },
        "chapter": {
          "en": "Chapter XI Limitation of Liability for Maritime Claims"
        }
      },
      {
        "no": 216,
        "text": {
          "en": "Except as otherwise provided in Articles 217 and 218 of this Law, the person liable may, irrespective of the basis on which liability for compensation is founded, limit liability for compensation in accordance with the provisions of this Chapter in respect of the following maritime claims:\n(a) claims in respect of loss of life or personal injury, or loss of or damage to property, occurring on board the ship or directly connected with the operation of the ship or with salvage operations, including damage to port works, harbour basins, navigable channels and navigational aids, and claims in respect of the corresponding loss arising therefrom;\n(b) claims in respect of loss resulting from delayed delivery in the carriage of goods by sea or from delayed arrival in the carriage of passengers and their luggage;\n(c) claims in respect of other loss resulting from an act infringing rights other than contractual rights, directly connected with the operation of the ship or with salvage operations;\n(d) claims by a person other than the person liable in respect of measures taken by that person to prevent or minimise loss for which the person liable may limit liability for compensation in accordance with the provisions of this Chapter, and claims in respect of further loss caused by such measures.\nLiability for compensation may be limited in respect of the claims listed in the preceding paragraph, irrespective of the manner in which they are made. However, where a claim under subparagraph (d) concerns remuneration agreed to be paid by the person liable under a contract, the limitation of liability provided for in this Article shall not be invoked."
        },
        "noLabel": {
          "en": "Article 216."
        },
        "chapter": {
          "en": "Chapter XI Limitation of Liability for Maritime Claims"
        }
      },
      {
        "no": 217,
        "text": {
          "en": "The provisions of this Chapter shall not apply to the following:\n(a) claims for salvage remuneration or for general average contribution;\n(b) claims for compensation for oil pollution damage from ships prescribed in Section 2 of Chapter XII of this Law;\n(c) claims for the costs of the raising, removal, destruction or rendering harmless of sunken, wrecked, stranded or abandoned ships and of objects and goods on board;\n(d) claims for compensation for nuclear damage prescribed in an international convention on limitation of liability for nuclear damage concluded or acceded to by the People's Republic of China;\n(e) claims for compensation for nuclear damage caused by a nuclear-powered ship;\n(f) claims brought by an employee of the shipowner or salvor where, under the relevant law, the shipowner or salvor is not entitled to limit liability for compensation in respect of such claims, or that law provides for a limit of liability higher than that prescribed in this Chapter."
        },
        "noLabel": {
          "en": "Article 217."
        },
        "chapter": {
          "en": "Chapter XI Limitation of Liability for Maritime Claims"
        }
      },
      {
        "no": 218,
        "text": {
          "en": "Where it is proved that the loss giving rise to the claim resulted from an act or omission of the person liable done with intent to cause such loss, or recklessly and with knowledge that such loss would probably result, that person shall not be entitled to limit liability for compensation in accordance with the provisions of this Chapter."
        },
        "noLabel": {
          "en": "Article 218."
        },
        "chapter": {
          "en": "Chapter XI Limitation of Liability for Maritime Claims"
        }
      },
      {
        "no": 219,
        "text": {
          "en": "Except as otherwise provided in Article 220 of this Law, the limits of liability for maritime claims shall be calculated as follows:\n(a) claims in respect of loss of life or personal injury\n(i) for a ship of 300 gross tonnage to 500 gross tonnage, the limit of liability shall be 500,000 units of account;\n(ii) for a ship of more than 500 gross tonnage, the provisions of item (i) of this subparagraph shall apply to the portion of up to 500 gross tonnage, and for the portion exceeding 500 gross tonnage, the following amounts shall be added:\nfor the portion from 501 gross tonnage to 2,000 gross tonnage, 1,000 units of account shall be added for each gross tonnage;\nfor the portion from 2,001 gross tonnage to 30,000 gross tonnage, 800 units of account shall be added for each gross tonnage;\nfor the portion from 30,001 gross tonnage to 70,000 gross tonnage, 600 units of account shall be added for each gross tonnage;\nfor the portion exceeding 70,000 gross tonnage, 400 units of account shall be added for each gross tonnage.\n(b) claims in respect of property damage other than personal injury or death\n(i) for a ship of 300 gross tonnage to 500 gross tonnage, the limit of liability shall be 250,000 units of account;\n(ii) for a ship of more than 500 gross tonnage, the provisions of item (i) of this subparagraph shall apply to the portion of up to 500 gross tonnage, and for the portion exceeding 500 gross tonnage, the following amounts shall be added:\nfor the portion from 501 gross tonnage to 2,000 gross tonnage, 500 units of account shall be added for each gross tonnage;\nfor the portion from 2,001 gross tonnage to 30,000 gross tonnage, 400 units of account shall be added for each gross tonnage;\nfor the portion from 30,001 gross tonnage to 70,000 gross tonnage, 300 units of account shall be added for each gross tonnage;\nfor the portion exceeding 70,000 gross tonnage, 200 units of account shall be added for each gross tonnage.\n(c) where the limit prescribed in subparagraph (a) is insufficient to pay all the claims in respect of loss of life or personal injury, the shortfall shall rank together with the claims in respect of property damage other than personal injury or death and shall be paid from the amount under subparagraph (b) in proportion.\n(d) without prejudice to subparagraph (c) concerning claims in respect of loss of life or personal injury, claims in respect of damage to port works, harbour basins, navigable channels and navigational aids shall be paid in priority to the other claims under subparagraph (b).\n(e) the limit of liability of a salvor who carries out salvage operations not from a ship, or on board the ship salved, shall be calculated on the basis of a ship of 1,500 gross tonnage.\nFor ships of less than 300 gross tonnage and ships engaged in coastal operations, the limits of liability shall be prescribed by the competent department of transport under the State Council and shall come into force after approval by the State Council.\nThe same limit of liability shall apply to other craft, not used for military or government service, that collide with a ship."
        },
        "noLabel": {
          "en": "Article 219."
        },
        "chapter": {
          "en": "Chapter XI Limitation of Liability for Maritime Claims"
        }
      },
      {
        "no": 220,
        "text": {
          "en": "The limit of liability for compensation for the loss of life or personal injury of passengers in the carriage of passengers by sea shall be calculated by multiplying 175,000 units of account by the passenger carrying capacity specified in the ship's certificate."
        },
        "noLabel": {
          "en": "Article 220."
        },
        "chapter": {
          "en": "Chapter XI Limitation of Liability for Maritime Claims"
        }
      },
      {
        "no": 221,
        "text": {
          "en": "The limits of liability prescribed in Articles 219 and 220 of this Law shall apply to the aggregate of the claims arising out of the same distinct occurrence and made against the shipowner or salvor and the persons for whose acts or faults the shipowner or salvor is liable."
        },
        "noLabel": {
          "en": "Article 221."
        },
        "chapter": {
          "en": "Chapter XI Limitation of Liability for Maritime Claims"
        }
      },
      {
        "no": 222,
        "text": {
          "en": "Where the person liable seeks to limit liability for compensation in accordance with the provisions of this Law, that person may constitute a limitation fund with the court having jurisdiction. The amount of the fund shall be the limit prescribed in Article 219 or Article 220 of this Law, as the case may be, plus the corresponding interest from the date of the occurrence until the date on which the fund is constituted.\nA fund constituted by any one of the persons liable under this Chapter shall be deemed to be constituted by all the persons liable."
        },
        "noLabel": {
          "en": "Article 222."
        },
        "chapter": {
          "en": "Chapter XI Limitation of Liability for Maritime Claims"
        }
      },
      {
        "no": 223,
        "text": {
          "en": "After a limitation fund has been constituted by the person liable, no person entitled to make a claim under Article 216 of this Law shall exercise any right against any property of the person liable; where the ship or other property of the person liable who has constituted the limitation fund has already been subjected to preservation measures, or where security has already been provided by the person constituting the fund, the court shall promptly lift the preservation measures or return the security."
        },
        "noLabel": {
          "en": "Article 223."
        },
        "chapter": {
          "en": "Chapter XI Limitation of Liability for Maritime Claims"
        }
      },
      {
        "no": 224,
        "text": {
          "en": "Where a person entitled to the limitation of liability provided for in this Chapter makes a counterclaim against the claimant in respect of the same occurrence, the amounts of the two claims shall be set off against each other, and the limit of liability prescribed in this Chapter shall apply only to the difference between the two amounts."
        },
        "noLabel": {
          "en": "Article 224."
        },
        "chapter": {
          "en": "Chapter XI Limitation of Liability for Maritime Claims"
        }
      },
      {
        "no": 225,
        "text": {
          "en": "The provisions of this Chapter shall apply to compensation for oil pollution damage from ships in the sea areas under the jurisdiction of the People's Republic of China and in navigable waters connected with the sea.\nThe scope of compensation for oil pollution damage from ships includes:\n(a) damage caused by oil pollution from a ship to property other than that ship, and the loss of income resulting therefrom;\n(b) the expenses incurred in preventive measures taken to prevent or minimise oil pollution damage from a ship, and the loss caused by such preventive measures;\n(c) the loss of income resulting from damage to the ecological environment caused by oil pollution;\n(d) the expenses of reasonable reinstatement measures already taken or to be taken in respect of the polluted ecological environment."
        },
        "noLabel": {
          "en": "Article 225."
        },
        "chapter": {
          "en": "Section 1 General Provisions"
        }
      },
      {
        "no": 226,
        "text": {
          "en": "The shipowner of the ship from which oil has escaped shall bear liability for compensation for oil pollution damage from the ship.\nWhere the shipowner proves that the oil pollution damage resulted wholly from any one of the following circumstances and that no reasonable measures taken in a timely manner could have avoided the damage to the ecological environment, the shipowner shall not bear liability for compensation:\n(a) war, armed conflict, terrorist activity or an irresistible natural disaster;\n(b) the intent of a third party;\n(c) the negligence or other wrongful act of the department responsible for the maintenance of lighthouses or other navigational aids in the performance of its duties.\nWhere the shipowner proves that the oil pollution damage was caused wholly or partly by the fault of the person who suffered it, the liability of the shipowner to that person for compensation may be excluded wholly or partly."
        },
        "noLabel": {
          "en": "Article 226."
        },
        "chapter": {
          "en": "Section 1 General Provisions"
        }
      },
      {
        "no": 227,
        "text": {
          "en": "The shipowner may limit liability for compensation in accordance with the provisions of this Chapter. However, where the oil pollution damage from the ship resulted from an act or omission of the shipowner done with intent to cause such damage, or recklessly and with knowledge that such damage would probably result, the shipowner shall not limit liability for compensation in accordance with the provisions of this Chapter."
        },
        "noLabel": {
          "en": "Article 227."
        },
        "chapter": {
          "en": "Section 1 General Provisions"
        }
      },
      {
        "no": 228,
        "text": {
          "en": "Where oil pollution damage is caused by two or more ships, the shipowners shall bear joint and several liability for the damage that cannot reasonably be separated.\nThe provisions of the preceding paragraph shall not affect the right of a shipowner against whom a claim is made to limit liability for compensation in accordance with the provisions of this Chapter."
        },
        "noLabel": {
          "en": "Article 228."
        },
        "chapter": {
          "en": "Section 1 General Provisions"
        }
      },
      {
        "no": 229,
        "text": {
          "en": "The State shall establish a system of insurance for liability for oil pollution damage from ships. A shipowner shall, in accordance with the relevant provisions of the State, take out insurance for civil liability for oil pollution damage from ships or obtain corresponding financial security.\nA claim for compensation for oil pollution damage from a ship may be brought directly against the liability insurer or the financial guarantor of the shipowner, provided that the liability of the liability insurer or financial guarantor for compensation shall not exceed the limits of liability prescribed in Articles 233 and 239 of this Law. The loss by the shipowner of the right to limit liability for compensation provided for in this Chapter shall not affect the right of its liability insurer or financial guarantor to invoke the provisions of this Chapter to limit liability for compensation.\nIn respect of a claim for compensation for oil pollution damage from a ship prescribed in the preceding paragraph, the liability insurer or financial guarantor shall be entitled to raise a defence on the ground that the damage was caused by the intent of the shipowner, and shall be entitled to invoke any ground of defence available to the shipowner other than bankruptcy or liquidation.\nThe State shall, in accordance with the law, improve and implement the system of funds for compensation for oil pollution damage from ships."
        },
        "noLabel": {
          "en": "Article 229."
        },
        "chapter": {
          "en": "Section 1 General Provisions"
        }
      },
      {
        "no": 230,
        "text": {
          "en": "The provisions of this Chapter shall not affect the right of the shipowner to seek recourse against a third party."
        },
        "noLabel": {
          "en": "Article 230."
        },
        "chapter": {
          "en": "Section 1 General Provisions"
        }
      },
      {
        "no": 231,
        "text": {
          "en": "The provisions of this Section shall apply to liability for oil pollution damage caused by a ship carrying oil in bulk.\nThe provisions of this Section shall apply to a ship built or adapted for the carriage of oil in bulk as cargo, and to a ship capable of carrying oil in bulk and other cargoes, during the period in which it is actually carrying oil in bulk as cargo and during any voyage thereafter, unless it is proved that no residue of oil in bulk cargo remains on board the ship.\nFor the purposes of this Section, oil means any persistent hydrocarbon mineral oil carried as cargo or used as fuel for the ship, including lubricating oil."
        },
        "noLabel": {
          "en": "Article 231."
        },
        "chapter": {
          "en": "Section 2 Liability for Oil Pollution Damage from Ships"
        }
      },
      {
        "no": 232,
        "text": {
          "en": "The following persons shall not bear liability for compensation for oil pollution damage from a ship, unless the damage resulted from an act or omission of the person concerned done with intent to cause such damage, or recklessly and with knowledge that such damage would probably result:\n(a) an employee or agent of the shipowner;\n(b) a pilot or any other person providing services to the ship other than a member of the crew;\n(c) the charterer, ship operator or ship manager of the ship;\n(d) any person carrying out salvage operations with the consent of the shipowner or on the instructions of a competent government department;\n(e) any person other than the shipowner who takes preventive measures;\n(f) an employee or agent of a person prescribed in subparagraphs (c) to (e) of this Article."
        },
        "noLabel": {
          "en": "Article 232."
        },
        "chapter": {
          "en": "Section 2 Liability for Oil Pollution Damage from Ships"
        }
      },
      {
        "no": 233,
        "text": {
          "en": "Where a ship carrying oil causes oil pollution damage, the shipowner shall calculate the limit of liability for each occurrence as follows:\n(a) for a ship of not more than 5,000 gross tonnage, the limit of liability shall be 4,510,000 units of account;\n(b) for a ship of 5,001 gross tonnage or more, the provisions of the preceding subparagraph shall apply to the portion of up to 5,000 gross tonnage, and for the portion exceeding 5,000 gross tonnage, 631 units of account shall be added for each additional gross tonnage; however, the limit of liability shall in no case exceed 89,770,000 units of account."
        },
        "noLabel": {
          "en": "Article 233."
        },
        "chapter": {
          "en": "Section 2 Liability for Oil Pollution Damage from Ships"
        }
      },
      {
        "no": 234,
        "text": {
          "en": "Where the shipowner, or its liability insurer or financial guarantor, invokes the provisions of this Section on limitation of liability for compensation, a limitation fund shall be constituted with the court having jurisdiction.\nA fund constituted by any one of the persons liable prescribed in the preceding paragraph shall be deemed to be constituted by all the persons liable."
        },
        "noLabel": {
          "en": "Article 234."
        },
        "chapter": {
          "en": "Section 2 Liability for Oil Pollution Damage from Ships"
        }
      },
      {
        "no": 235,
        "text": {
          "en": "Where a limitation fund has been constituted and the shipowner is entitled to limit liability for compensation, a claimant for compensation for oil pollution damage shall not apply to the court for the exercise of preservation measures against the property of the shipowner; property preservation measures already taken shall be lifted, and any deposit or other security already provided by the shipowner in order to avoid or obtain the lifting of the preservation measures shall be returned."
        },
        "noLabel": {
          "en": "Article 235."
        },
        "chapter": {
          "en": "Section 2 Liability for Oil Pollution Damage from Ships"
        }
      },
      {
        "no": 236,
        "text": {
          "en": "Claimants for compensation for oil pollution damage shall share in the distribution of the limitation fund in proportion to the amount of compensation for the damage.\nWhere, before the distribution of the limitation fund, the shipowner, or its liability insurer or financial guarantor, has paid compensation to a claimant for oil pollution damage, or where compensation has been paid by a third party, the person making the payment shall be subrogated to the rights of that claimant to the extent of the amount paid.\nThe expenses of preventive measures taken by the shipowner and the loss caused by such preventive measures shall rank equally with the claims of other claimants for oil pollution damage in the distribution of the limitation fund."
        },
        "noLabel": {
          "en": "Article 236."
        },
        "chapter": {
          "en": "Section 2 Liability for Oil Pollution Damage from Ships"
        }
      },
      {
        "no": 237,
        "text": {
          "en": "The provisions of this Section shall apply to liability for oil pollution damage caused by non-persistent fuel oil carried on board a ship prescribed in Section 2 of this Chapter and by fuel oil carried on board ships other than those prescribed in Section 2.\nFor the purposes of this Section, fuel oil means hydrocarbon mineral oil used as fuel for a ship, including lubricating oil.\nThe provisions of this Section relating to the shipowner shall apply to the bareboat charterer, the ship operator and the ship manager."
        },
        "noLabel": {
          "en": "Article 237."
        },
        "chapter": {
          "en": "Section 3 Liability for Bunker Fuel Oil Pollution Damage from Ships"
        }
      },
      {
        "no": 238,
        "text": {
          "en": "The following persons shall not bear liability for compensation for fuel oil pollution damage prescribed in this Section, unless the damage resulted from an act or omission of the person concerned done with intent to cause such damage, or recklessly and with knowledge that such damage would probably result:\n(a) an employee or agent of the shipowner;\n(b) a pilot or any other person providing services to the ship other than a member of the crew;\n(c) the voyage charterer or the time charterer of the ship;\n(d) any person carrying out salvage operations with the consent of the shipowner or on the instructions of a competent government department;\n(e) any person other than the shipowner who takes preventive measures;\n(f) an employee or agent of a person prescribed in subparagraphs (c) to (e) of this Article."
        },
        "noLabel": {
          "en": "Article 238."
        },
        "chapter": {
          "en": "Section 3 Liability for Bunker Fuel Oil Pollution Damage from Ships"
        }
      },
      {
        "no": 239,
        "text": {
          "en": "The limits of liability for compensation for fuel oil pollution damage prescribed in this Section shall be governed by the provisions of Chapter XI of this Law.\nWhere the same occurrence causes both fuel oil pollution damage and other damage prescribed in Article 216 of this Law for which liability for compensation may be limited, the person liable shall be entitled, in accordance with the provisions of Article 219 of this Law, to limit liability for compensation within the same limit of liability."
        },
        "noLabel": {
          "en": "Article 239."
        },
        "chapter": {
          "en": "Section 3 Liability for Bunker Fuel Oil Pollution Damage from Ships"
        }
      },
      {
        "no": 240,
        "text": {
          "en": "A contract of marine insurance means a contract under which the insurer is liable, as agreed, to indemnify the insured for loss of the subject matter insured and for liability incurred by the insured as a result of a maritime accident insured against, and the insured pays a premium to the insurer.\nA maritime accident insured against means any maritime accident agreed between the insurer and the insured, including an accident occurring on an inland river or on land in connection with navigation at sea."
        },
        "noLabel": {
          "en": "Article 240."
        },
        "chapter": {
          "en": "Section 1 General Provisions"
        }
      },
      {
        "no": 241,
        "text": {
          "en": "The contents of a contract of marine insurance mainly include the following:\n(a) the name of the insurer;\n(b) the name of the insured;\n(c) the subject matter insured;\n(d) the insured value;\n(e) the insured amount;\n(f) the risks covered and the risks excluded;\n(g) the insurance period;\n(h) the premium."
        },
        "noLabel": {
          "en": "Article 241."
        },
        "chapter": {
          "en": "Section 1 General Provisions"
        }
      },
      {
        "no": 242,
        "text": {
          "en": "The following may be the subject matter insured:\n(a) ships;\n(b) goods;\n(c) income from the operation of the ship, including freight, hire and passage money;\n(d) anticipated profit on goods;\n(e) wages and other remuneration of the crew;\n(f) liability to third parties;\n(g) other property that may suffer loss, and liability and expenses that may arise, as a result of the occurrence of a peril insured against.\nThe insurer may reinsure the subject matter insured referred to in the preceding paragraph. Unless otherwise agreed in the contract, the original insured shall not be entitled to the benefit of the reinsurance."
        },
        "noLabel": {
          "en": "Article 242."
        },
        "chapter": {
          "en": "Section 1 General Provisions"
        }
      },
      {
        "no": 243,
        "text": {
          "en": "The insured value of the subject matter insured shall be agreed upon in writing by the insurer and the insured; where the subject matter insured suffers a loss, the agreed insured value shall be the basis for calculating indemnity.\nWhere the insurer and the insured have not agreed upon the insured value, the insured value shall be calculated in accordance with the following provisions:\n(a) the insured value of a ship is the value of the ship at the time when the insurance liability commences, being the aggregate of the value of the hull, machinery and equipment, and the value of the fuel, stores, rigging, provisions and fresh water on board, plus the premium;\n(b) the insured value of goods is the aggregate of the invoice price of the goods at the place of shipment at the time when the insurance liability commences, or the actual value of non-trade goods at the place of shipment at that time, plus freight and premium;\n(c) the insured value of freight is the aggregate of the total freight receivable by the carrier at the time when the insurance liability commences plus the premium;\n(d) the insured value of other subject matter insured is the aggregate of the actual value of the subject matter insured at the time when the insurance liability commences plus the premium."
        },
        "noLabel": {
          "en": "Article 243."
        },
        "chapter": {
          "en": "Section 1 General Provisions"
        }
      },
      {
        "no": 244,
        "text": {
          "en": "The insured amount shall be agreed upon by the insurer and the insured. The insured amount shall not exceed the insured value; where the insured amount exceeds the insured value, the excess shall be invalid."
        },
        "noLabel": {
          "en": "Article 244."
        },
        "chapter": {
          "en": "Section 1 General Provisions"
        }
      },
      {
        "no": 245,
        "text": {
          "en": "The relevant provisions of this Chapter shall apply to a contract of insurance on a ship under construction.\nA contract of insurance on a ship under construction means a contract under which the insurer is liable, as agreed, to indemnify the insured for loss and liability caused by a peril insured against to which the ship is exposed in the course of its construction, sea trials and delivery at the shipyard, and the insured pays the premium.\nA ship under construction includes the materials, machinery and equipment used for the construction of the ship in conformity with the shipbuilding contract."
        },
        "noLabel": {
          "en": "Article 245."
        },
        "chapter": {
          "en": "Section 1 General Provisions"
        }
      },
      {
        "no": 246,
        "text": {
          "en": "Where the insured makes a request for insurance, the insurer agrees to underwrite the risk and the parties reach agreement on the terms of the contract of marine insurance, the contract is concluded. The insurer shall, in a timely manner, issue a policy or other insurance document to the insured, and shall state in the policy or other insurance document the contents of the contract agreed upon by both parties."
        },
        "noLabel": {
          "en": "Article 246."
        },
        "chapter": {
          "en": "Section 2 Conclusion, Termination and Assignment of Contract"
        }
      },
      {
        "no": 247,
        "text": {
          "en": "Before the contract is concluded, the insured shall truthfully disclose to the insurer the material circumstances which he or she knows, or ought to know in the ordinary course of business, and which affect the insurer's determination of the premium rate or of whether to agree to underwrite the risk.\nWhere the insurer knows, or ought to know in the ordinary course of business, the relevant circumstances and has made no inquiry, the insured is not required to disclose them."
        },
        "noLabel": {
          "en": "Article 247."
        },
        "chapter": {
          "en": "Section 2 Conclusion, Termination and Assignment of Contract"
        }
      },
      {
        "no": 248,
        "text": {
          "en": "Where, due to the intent of the insured, the material circumstances prescribed in paragraph 1 of Article 247 of this Law are not truthfully disclosed to the insurer, the insurer shall be entitled to rescind the contract and shall not refund the premium. Where a peril insured against occurs before the rescission of the contract and causes loss, the insurer shall not be liable for indemnity.\nWhere, not due to the intent of the insured, the material circumstances prescribed in paragraph 1 of Article 247 of this Law are not truthfully disclosed to the insurer, the insurer shall be entitled to rescind the contract or to require a corresponding increase in the premium. Where the insurer rescinds the contract before the insurance liability commences, it shall refund the whole of the premium but shall be entitled to charge a commission. Where the insurer rescinds the contract after the insurance liability commences, it shall refund to the insured the premium for the period from the date of rescission of the contract to the date of expiry of the insurance period, except that, where a voyage insurance contract is rescinded, the insurer may not refund the premium. As to loss caused by a peril insured against occurring before the rescission of the contract, the insurer shall be liable for indemnity, unless the material circumstances not disclosed or wrongly disclosed had an effect on the occurrence of the peril insured against.\nThe right to rescind the contract provided for in this Article shall be extinguished if it is not exercised within 30 days from the date on which the insurer knows or ought to know of the ground for rescission."
        },
        "noLabel": {
          "en": "Article 248."
        },
        "chapter": {
          "en": "Section 2 Conclusion, Termination and Assignment of Contract"
        }
      },
      {
        "no": 249,
        "text": {
          "en": "Where a contract of marine insurance uses the standard clauses provided by the insurer, in respect of clauses which exempt the insurer from liability or reduce its liability and other clauses in which the insured has a major interest, the insurer shall, at the time of concluding the contract, give a reminder sufficient to draw the attention of the insured. Where the insured requests an explanation, the insurer shall explain such clauses clearly.\nWhere the insurer fails to perform the obligation of reminder or explanation in accordance with the preceding paragraph, with the result that the insured has not noticed or understood the clauses in which he or she has a major interest, the insured may assert that such clauses do not form part of the contract, unless the insured knows or ought to know the contents of such clauses."
        },
        "noLabel": {
          "en": "Article 249."
        },
        "chapter": {
          "en": "Section 2 Conclusion, Termination and Assignment of Contract"
        }
      },
      {
        "no": 250,
        "text": {
          "en": "Where, at the time of concluding the contract, the insured already knew or ought to have known that the subject matter insured had already suffered loss as a result of the occurrence of a peril insured against, the insurer shall not be liable for indemnity but shall be entitled to charge the premium; where the insurer already knew or ought to have known that the subject matter insured could no longer suffer loss as a result of the occurrence of a peril insured against, the insured shall be entitled to recover the premium already paid."
        },
        "noLabel": {
          "en": "Article 250."
        },
        "chapter": {
          "en": "Section 2 Conclusion, Termination and Assignment of Contract"
        }
      },
      {
        "no": 251,
        "text": {
          "en": "Where the insured concludes contracts repeatedly with two or more insurers in respect of the same subject matter insured, the same insurable interest and the same peril insured against, so that the aggregate insured amount in respect of the subject matter insured exceeds the insured value, the insured may, unless otherwise agreed in the contract, claim indemnity from any insurer, provided that the aggregate amount of indemnity obtained by the insured shall not exceed the damaged value of the subject matter insured.\nEach insurer shall be liable for indemnity in proportion to the insured amount underwritten by it to the aggregate insured amount; where the amount of indemnity paid by any insurer exceeds the liability for indemnity that it ought to bear, it shall be entitled to recover from the insurers that have not paid the amount of indemnity in accordance with the liability for indemnity that they ought to bear.\nThe insured value referred to in paragraph 1 of this Article shall be the highest insured value among the insurance contracts; the damaged value means the amount of damage calculated on the basis of the highest insured value among the insurance contracts."
        },
        "noLabel": {
          "en": "Article 251."
        },
        "chapter": {
          "en": "Section 2 Conclusion, Termination and Assignment of Contract"
        }
      },
      {
        "no": 252,
        "text": {
          "en": "Before the insurance liability commences, the insured may request rescission of the contract, but shall pay a commission to the insurer, and the insurer shall refund the premium."
        },
        "noLabel": {
          "en": "Article 252."
        },
        "chapter": {
          "en": "Section 2 Conclusion, Termination and Assignment of Contract"
        }
      },
      {
        "no": 253,
        "text": {
          "en": "Unless otherwise provided by law or otherwise agreed in the contract, after the insurance liability commences, neither the insured nor the insurer may rescind the contract.\nWhere, as agreed in the contract, the contract may be rescinded after the insurance liability commences, and the insured requests rescission, the insurer shall be entitled to charge the premium for the period from the date on which the insurance liability commences to the date of rescission of the contract and shall refund the remainder; where the insurer requests rescission, it shall refund to the insured the premium for the period from the date of rescission of the contract to the date of expiry of the insurance period."
        },
        "noLabel": {
          "en": "Article 253."
        },
        "chapter": {
          "en": "Section 2 Conclusion, Termination and Assignment of Contract"
        }
      },
      {
        "no": 254,
        "text": {
          "en": "In the case of insurance of the carriage of goods by sea and voyage insurance of a ship, after the insurance liability commences, the insured may not request rescission of the contract."
        },
        "noLabel": {
          "en": "Article 254."
        },
        "chapter": {
          "en": "Section 2 Conclusion, Termination and Assignment of Contract"
        }
      },
      {
        "no": 255,
        "text": {
          "en": "A contract of insurance of the carriage of goods by sea may be assigned by the insured by endorsement or in other ways, and the rights and obligations under the contract shall pass accordingly. Where the premium has not been paid at the time of assignment of the contract, the insured and the assignee of the contract shall be jointly and severally liable for payment."
        },
        "noLabel": {
          "en": "Article 255."
        },
        "chapter": {
          "en": "Section 2 Conclusion, Termination and Assignment of Contract"
        }
      },
      {
        "no": 256,
        "text": {
          "en": "Assignment of a contract of insurance of a ship as a result of the transfer of the ship shall be subject to the consent of the insurer. Without the consent of the insurer, the contract of insurance of the ship shall be rescinded from the time of the transfer of the ship; where the transfer of the ship occurs in the course of a voyage, the contract of insurance of the ship shall be rescinded at the end of the voyage.\nAfter the rescission of the contract, the insurer shall refund to the insured the premium for the period from the date of rescission of the contract to the date of expiry of the insurance period."
        },
        "noLabel": {
          "en": "Article 256."
        },
        "chapter": {
          "en": "Section 2 Conclusion, Termination and Assignment of Contract"
        }
      },
      {
        "no": 257,
        "text": {
          "en": "A contract of open cover means a contract under which the insurer is liable, as agreed, to insure the goods to be shipped in instalments by the insured within a certain future period, and the insured pays the premium.\nA contract of open cover shall be concluded in writing."
        },
        "noLabel": {
          "en": "Article 257."
        },
        "chapter": {
          "en": "Section 2 Conclusion, Termination and Assignment of Contract"
        }
      },
      {
        "no": 258,
        "text": {
          "en": "At the request of the insured, the insurer shall issue separate insurance documents for the goods shipped in instalments under a contract of open cover.\nWhere the contents of the separate insurance documents issued by the insurer are inconsistent with the contents of the contract of open cover, the separate insurance documents issued shall prevail."
        },
        "noLabel": {
          "en": "Article 258."
        },
        "chapter": {
          "en": "Section 2 Conclusion, Termination and Assignment of Contract"
        }
      },
      {
        "no": 259,
        "text": {
          "en": "Under a contract of open cover, the insured shall, before each shipment, truthfully declare to the insurer the particulars of the goods shipped in instalments, including the description and quantity of the goods, the name of the ship and the route, the insured value and the insured amount.\nWhere, due to the intent of the insured, the goods shipped are not declared or are wrongly declared, the insurer shall not be liable for indemnity for loss caused by a peril insured against in that shipment of goods, but shall be entitled to charge the premium.\nWhere, not due to the intent of the insured, the goods shipped are not declared or are wrongly declared, the insured shall be entitled to make a supplementary declaration or correction, and such supplementary declaration or correction shall not affect the right of the insured to claim indemnity from the insurer, except that the insurer shall be entitled to take the insured value prescribed in paragraph 2 of Article 243 of this Law as the basis for calculating indemnity.\nThe provisions of this Article shall apply only where the contract of open cover is silent or contains no different agreement."
        },
        "noLabel": {
          "en": "Article 259."
        },
        "chapter": {
          "en": "Section 2 Conclusion, Termination and Assignment of Contract"
        }
      },
      {
        "no": 260,
        "text": {
          "en": "Unless otherwise agreed in the contract, the insured shall pay the premium immediately after the conclusion of the contract; before the insured pays the premium, the insurer may refuse to issue the insurance document."
        },
        "noLabel": {
          "en": "Article 260."
        },
        "chapter": {
          "en": "Section 3 Obligations of the Insured"
        }
      },
      {
        "no": 261,
        "text": {
          "en": "Where the insured breaches a warranty clause agreed in the contract, the insurer shall be entitled to rescind the contract or to require modification of the terms of cover or an increase in the premium. Where the insurer rescinds the contract, it shall notify the insured in writing, and the contract shall be rescinded when the notice reaches the insured.\nAs to loss caused by a peril insured against occurring before the insured breaches the warranty clause, the insurer shall be liable for indemnity.\nAs to loss caused by a peril insured against occurring after the insured breaches the warranty clause and before the notice of rescission reaches the insured, the insurer shall not be liable, unless the insured can prove that any of the following circumstances exists:\n(a) the breach of the warranty clause by the insured had no effect on the occurrence of the peril insured against;\n(b) the peril insured against occurred after the insured had rectified the breach of the warranty clause."
        },
        "noLabel": {
          "en": "Article 261."
        },
        "chapter": {
          "en": "Section 3 Obligations of the Insured"
        }
      },
      {
        "no": 262,
        "text": {
          "en": "Where a peril insured against occurs, the insured shall notify the insurer immediately and take necessary and reasonable measures to prevent or minimise loss. Where the insured receives a special notice from the insurer concerning reasonable measures to be taken to prevent or minimise loss, the insured shall act in accordance with the requirements of the notice of the insurer.\nThe insurer shall not be liable for indemnity for the aggravated loss caused by the breach of the preceding paragraph by the insured."
        },
        "noLabel": {
          "en": "Article 262."
        },
        "chapter": {
          "en": "Section 3 Obligations of the Insured"
        }
      },
      {
        "no": 263,
        "text": {
          "en": "After a peril insured against has occurred and caused loss, the insurer shall pay indemnity to the insured in a timely manner."
        },
        "noLabel": {
          "en": "Article 263."
        },
        "chapter": {
          "en": "Section 4 Liability of the Insurer"
        }
      },
      {
        "no": 264,
        "text": {
          "en": "The indemnity paid by the insurer for loss caused by a peril insured against shall be limited to the insured amount. Where the insured amount is lower than the insured value, in the case of partial loss of the subject matter insured, the insurer shall be liable for indemnity in proportion to the insured amount to the insured value."
        },
        "noLabel": {
          "en": "Article 264."
        },
        "chapter": {
          "en": "Section 4 Liability of the Insurer"
        }
      },
      {
        "no": 265,
        "text": {
          "en": "Where loss is caused by several perils insured against occurring during the insurance period, the insurer shall indemnify even if the aggregate amount of the loss exceeds the insured amount. However, where a total loss occurs after a partial loss and without the subject matter insured having been repaired, the insurer shall indemnify as for a total loss."
        },
        "noLabel": {
          "en": "Article 265."
        },
        "chapter": {
          "en": "Section 4 Liability of the Insurer"
        }
      },
      {
        "no": 266,
        "text": {
          "en": "Necessary and reasonable expenses incurred by the insured to prevent or minimise loss recoverable under the contract, reasonable expenses such as survey and valuation expenses incurred to ascertain the nature and extent of the peril insured against, and expenses incurred to comply with a special notice of the insurer shall be paid by the insurer separately from the indemnity for the loss of the subject matter insured.\nThe payment by the insurer of the expenses prescribed in the preceding paragraph shall be limited to an amount equivalent to the insured amount.\nWhere the insured amount is lower than the insured value, the insurer shall, unless otherwise agreed in the contract, pay the expenses prescribed in this Article in proportion to the insured amount to the insured value."
        },
        "noLabel": {
          "en": "Article 266."
        },
        "chapter": {
          "en": "Section 4 Liability of the Insurer"
        }
      },
      {
        "no": 267,
        "text": {
          "en": "Where the insured amount is lower than the contributory value of general average, the insurer shall indemnify the general average contribution in proportion to the insured amount to the contributory value."
        },
        "noLabel": {
          "en": "Article 267."
        },
        "chapter": {
          "en": "Section 4 Liability of the Insurer"
        }
      },
      {
        "no": 268,
        "text": {
          "en": "The insurer shall not be liable for indemnity for loss intentionally caused by the insured."
        },
        "noLabel": {
          "en": "Article 268."
        },
        "chapter": {
          "en": "Section 4 Liability of the Insurer"
        }
      },
      {
        "no": 269,
        "text": {
          "en": "Unless otherwise agreed in the contract, the insurer shall not be liable for indemnity for loss of goods caused by any of the following:\n(a) delay in the voyage, delay in delivery or fluctuation in market prices;\n(b) natural diminution, inherent defect and natural characteristics of the goods;\n(c) improper packing."
        },
        "noLabel": {
          "en": "Article 269."
        },
        "chapter": {
          "en": "Section 4 Liability of the Insurer"
        }
      },
      {
        "no": 270,
        "text": {
          "en": "Unless otherwise agreed in the contract, the insurer shall not be liable for indemnity for loss of the insured ship caused by any of the following:\n(a) unseaworthiness of the ship at the commencement of the voyage, except where, in the case of time insurance of a ship, the insured did not know and ought not to have known of it;\n(b) natural wear and tear or corrosion of the ship.\nThe preceding paragraph shall apply to insurance of freight."
        },
        "noLabel": {
          "en": "Article 270."
        },
        "chapter": {
          "en": "Section 4 Liability of the Insurer"
        }
      },
      {
        "no": 271,
        "text": {
          "en": "Where the subject matter insured is lost after the occurrence of a peril insured against, or is so seriously damaged as to completely lose its original form and utility, or can no longer be owned by the insured, such loss constitutes an actual total loss."
        },
        "noLabel": {
          "en": "Article 271."
        },
        "chapter": {
          "en": "Section 5 Loss of and Damage to the Subject Matter Insured and Abandonment"
        }
      },
      {
        "no": 272,
        "text": {
          "en": "Where a peril insured against occurs to a ship and it is considered that an actual total loss is unavoidable, or that the expenses required to be paid to avoid an actual total loss would exceed the insured value, such loss constitutes a constructive total loss.\nWhere a peril insured against occurs to goods and it is considered that an actual total loss is unavoidable, or that the aggregate of the expenses required to be paid to avoid an actual total loss and the expenses of continuing to carry the goods to the place of destination would exceed the insured value, such loss constitutes a constructive total loss."
        },
        "noLabel": {
          "en": "Article 272."
        },
        "chapter": {
          "en": "Section 5 Loss of and Damage to the Subject Matter Insured and Abandonment"
        }
      },
      {
        "no": 273,
        "text": {
          "en": "Loss which is neither an actual total loss nor a constructive total loss is a partial loss."
        },
        "noLabel": {
          "en": "Article 273."
        },
        "chapter": {
          "en": "Section 5 Loss of and Damage to the Subject Matter Insured and Abandonment"
        }
      },
      {
        "no": 274,
        "text": {
          "en": "Where a ship fails to arrive at the place of destination within a reasonable time from the place where it was last heard of and, unless otherwise agreed in the contract, its whereabouts remain unknown upon the expiry of 60 days, the ship is deemed to be missing. A missing ship shall be deemed to be an actual total loss."
        },
        "noLabel": {
          "en": "Article 274."
        },
        "chapter": {
          "en": "Section 5 Loss of and Damage to the Subject Matter Insured and Abandonment"
        }
      },
      {
        "no": 275,
        "text": {
          "en": "Where a constructive total loss occurs to the subject matter insured and the insured requests the insurer to indemnify on the basis of a total loss, the insured shall abandon the subject matter insured to the insurer within a reasonable time. The insurer may accept or not accept the abandonment, but shall notify the insured of its decision whether or not to accept the abandonment within a reasonable time. Where the insurer fails to notify the insured within a reasonable time whether it accepts the abandonment, it shall be deemed not to have accepted the abandonment.\nThe abandonment shall not be subject to any condition. Once accepted by the insurer, the abandonment shall not be withdrawn."
        },
        "noLabel": {
          "en": "Article 275."
        },
        "chapter": {
          "en": "Section 5 Loss of and Damage to the Subject Matter Insured and Abandonment"
        }
      },
      {
        "no": 276,
        "text": {
          "en": "Where the insurer accepts the abandonment, all the rights and obligations of the insured in respect of the abandoned property shall be transferred to the insurer."
        },
        "noLabel": {
          "en": "Article 276."
        },
        "chapter": {
          "en": "Section 5 Loss of and Damage to the Subject Matter Insured and Abandonment"
        }
      },
      {
        "no": 277,
        "text": {
          "en": "After the occurrence of a peril insured against, the insurer may, before paying indemnity to the insured, require the insured to provide certificates and information relating to the ascertainment of the nature of the peril insured against and the extent of the loss."
        },
        "noLabel": {
          "en": "Article 277."
        },
        "chapter": {
          "en": "Section 6 Payment of Indemnity"
        }
      },
      {
        "no": 278,
        "text": {
          "en": "Where loss falling within the scope of the insurance liability occurs to the subject matter insured and is caused by a third party, the right of the insured to claim indemnity from the third party shall, from the date on which the insurer pays the indemnity, be transferred to the insurer accordingly.\nThe insured shall provide the insurer with the necessary documents and the information that the insurer needs to know, and shall use its best endeavours to assist the insurer in pursuing recourse against the third party."
        },
        "noLabel": {
          "en": "Article 278."
        },
        "chapter": {
          "en": "Section 6 Payment of Indemnity"
        }
      },
      {
        "no": 279,
        "text": {
          "en": "Where the insured, without the consent of the insurer, waives the right to claim indemnity from the third party, or where the fault of the insured renders the insurer unable to exercise the right of recourse, the insurer may reduce the indemnity accordingly."
        },
        "noLabel": {
          "en": "Article 279."
        },
        "chapter": {
          "en": "Section 6 Payment of Indemnity"
        }
      },
      {
        "no": 280,
        "text": {
          "en": "When paying indemnity, the insurer may correspondingly deduct from the amount of indemnity payable the indemnity that the insured has already obtained from the third party.\nWhere the indemnity obtained by the insurer from the third party exceeds the indemnity paid by it, the excess shall be refunded to the insured."
        },
        "noLabel": {
          "en": "Article 280."
        },
        "chapter": {
          "en": "Section 6 Payment of Indemnity"
        }
      },
      {
        "no": 281,
        "text": {
          "en": "After the occurrence of a peril insured against, the insurer shall be entitled to abandon its rights in the subject matter insured and to pay in full the indemnity agreed in the contract, so as to be released from its obligations in respect of the subject matter insured.\nWhere the insurer exercises the right prescribed in the preceding paragraph, it shall notify the insured within seven days from the date of receipt of the notice of the insured concerning the loss; the necessary and reasonable expenses paid by the insured to prevent or minimise the loss before receipt of the notice shall be reimbursed by the insurer."
        },
        "noLabel": {
          "en": "Article 281."
        },
        "chapter": {
          "en": "Section 6 Payment of Indemnity"
        }
      },
      {
        "no": 282,
        "text": {
          "en": "Except as provided in Article 281 of this Law, where a total loss occurs to the subject matter insured and the insurer pays the whole of the insured amount, the insurer shall acquire all the rights in the subject matter insured; however, in the case of under-insurance, the insurer shall acquire part of the rights in the subject matter insured in proportion to the insured amount to the insured value."
        },
        "noLabel": {
          "en": "Article 282."
        },
        "chapter": {
          "en": "Section 6 Payment of Indemnity"
        }
      },
      {
        "no": 283,
        "text": {
          "en": "Where a maritime dispute arises, the parties may bring an action or apply for arbitration in accordance with the law."
        },
        "noLabel": {
          "en": "Article 283."
        },
        "chapter": {
          "en": "Chapter XIV Limitation of Time"
        }
      },
      {
        "no": 284,
        "text": {
          "en": "The limitation period for the right of claim for indemnity in the carriage of goods by sea shall be one year. Where indemnity is claimed from the carrier or the actual carrier, the limitation period shall be counted from the date on which the goods are delivered or ought to have been delivered; where indemnity is claimed from the shipper, the consignee or the holder of a transport document, the limitation period shall be counted from the date on which the person having the right of claim knows or ought to know that his or her right has been infringed.\nWhere the limitation period prescribed in the preceding paragraph has expired, or less than 90 days remain before its expiry, the limitation period for the right of recourse of a person held liable against a third party shall be 90 days, counted from the date on which the person claiming recourse settles the original claim for indemnity."
        },
        "noLabel": {
          "en": "Article 284."
        },
        "chapter": {
          "en": "Chapter XIV Limitation of Time"
        }
      },
      {
        "no": 285,
        "text": {
          "en": "The limitation period for the right of claim for indemnity in the carriage of passengers by sea shall be two years and shall be calculated respectively in accordance with the following provisions:\n(a) a claim relating to the death of a passenger shall, where the death occurs during the carriage, be counted from the date on which the passenger ought to have disembarked; where the passenger dies after disembarkation as a result of an injury sustained during the carriage, it shall be counted from the date of the death of the passenger, provided that such period shall not exceed three years from the date on which the passenger disembarked;\n(b) a claim relating to personal injury to a passenger or to the loss of or damage to luggage shall be counted from the date on which the passenger disembarked or ought to have disembarked."
        },
        "noLabel": {
          "en": "Article 285."
        },
        "chapter": {
          "en": "Chapter XIV Limitation of Time"
        }
      },
      {
        "no": 286,
        "text": {
          "en": "The limitation period for a claim relating to a charter party shall be two years, counted from the date on which the person having the right of claim knows or ought to know that his or her right has been infringed."
        },
        "noLabel": {
          "en": "Article 286."
        },
        "chapter": {
          "en": "Chapter XIV Limitation of Time"
        }
      },
      {
        "no": 287,
        "text": {
          "en": "The limitation period for a claim relating to a contract of maritime towage shall be one year, counted from the date on which the person having the right of claim knows or ought to know that his or her right has been infringed."
        },
        "noLabel": {
          "en": "Article 287."
        },
        "chapter": {
          "en": "Chapter XIV Limitation of Time"
        }
      },
      {
        "no": 288,
        "text": {
          "en": "The limitation period for a claim relating to the collision of ships shall be two years, counted from the date on which the collision occurs.\nThe limitation period for the right of recourse prescribed in paragraph 3 of Article 178 of this Law shall be one year, counted from the date on which the parties pay compensation for the damage jointly and severally.\nThe limitation period for a right of claim or a right of recourse arising under Article 179 of this Law shall be governed by the provisions of this Article."
        },
        "noLabel": {
          "en": "Article 288."
        },
        "chapter": {
          "en": "Chapter XIV Limitation of Time"
        }
      },
      {
        "no": 289,
        "text": {
          "en": "The limitation period for a claim relating to salvage at sea shall be two years, counted from the date on which the salvage operations terminate."
        },
        "noLabel": {
          "en": "Article 289."
        },
        "chapter": {
          "en": "Chapter XIV Limitation of Time"
        }
      },
      {
        "no": 290,
        "text": {
          "en": "The limitation period for a claim relating to general average contribution shall be one year, counted from the date on which the adjustment of general average is completed, provided that it shall not exceed six years from the date on which the common maritime adventure terminates."
        },
        "noLabel": {
          "en": "Article 290."
        },
        "chapter": {
          "en": "Chapter XIV Limitation of Time"
        }
      },
      {
        "no": 291,
        "text": {
          "en": "The limitation period for the right of claim for indemnity against the insurer under a contract of marine insurance shall be two years, counted from the date on which the person having the right of claim knows or ought to know of the occurrence of the peril insured against."
        },
        "noLabel": {
          "en": "Article 291."
        },
        "chapter": {
          "en": "Chapter XIV Limitation of Time"
        }
      },
      {
        "no": 292,
        "text": {
          "en": "The limitation period for a claim relating to oil pollution damage from a ship shall be three years, counted from the date on which the damage occurs, provided that it shall not exceed six years from the date on which the incident causing the damage occurs."
        },
        "noLabel": {
          "en": "Article 292."
        },
        "chapter": {
          "en": "Chapter XIV Limitation of Time"
        }
      },
      {
        "no": 293,
        "text": {
          "en": "Where, during the last six months of the limitation period, a person is unable to exercise his or her right of claim due to force majeure or other obstacles, the limitation period shall be suspended. The limitation period shall expire when six months have elapsed from the date on which the cause of the suspension is removed."
        },
        "noLabel": {
          "en": "Article 293."
        },
        "chapter": {
          "en": "Chapter XIV Limitation of Time"
        }
      },
      {
        "no": 294,
        "text": {
          "en": "The limitation period shall be interrupted where the claimant demands performance, brings an action, applies for arbitration, or the respondent agrees to perform the obligation.\nWhere the claimant applies for the arrest of a ship, the limitation period shall be interrupted from the date of the application for the arrest of the ship.\nThe limitation period shall be counted anew from the time of the interruption or of the conclusion of the relevant proceedings."
        },
        "noLabel": {
          "en": "Article 294."
        },
        "chapter": {
          "en": "Chapter XIV Limitation of Time"
        }
      },
      {
        "no": 295,
        "text": {
          "en": "The parties to a contract may choose the law applicable to the contract, except as otherwise provided by law. Where the parties to the contract have made no choice, the law of the country with which the contract is most closely connected shall apply.\nThe provisions of Chapter IV of this Law shall apply to a contract for the international carriage of goods by sea where the port of loading or the port of discharge is located within the territory of the People's Republic of China."
        },
        "noLabel": {
          "en": "Article 295."
        },
        "chapter": {
          "en": "Chapter XV Application of Law in Relation to Foreign-related Matters"
        }
      },
      {
        "no": 296,
        "text": {
          "en": "Ownership of a ship shall be governed by the law of the State of the flag.\nWhere the flag is changed, the ownership of the ship after the change shall be governed by the law of the new State of the flag, except where the change of flag arises from a bareboat charter.\nThe ownership of a ship under construction shall, where the ship has been registered, be governed by the law of the State of registry; where it has not been registered, it shall be governed by the law of the place where the ship is built."
        },
        "noLabel": {
          "en": "Article 296."
        },
        "chapter": {
          "en": "Chapter XV Application of Law in Relation to Foreign-related Matters"
        }
      },
      {
        "no": 297,
        "text": {
          "en": "A mortgage on a ship shall be governed by the law of the State of the flag.\nWhere a mortgage on a ship is created before or during a bareboat charter, it shall be governed by the law of the State of the original registry of the ship.\nA mortgage on a ship under construction shall, where the ship has been registered, be governed by the law of the State of registry; where it has not been registered, it shall be governed by the law of the place where the ship is built."
        },
        "noLabel": {
          "en": "Article 297."
        },
        "chapter": {
          "en": "Chapter XV Application of Law in Relation to Foreign-related Matters"
        }
      },
      {
        "no": 298,
        "text": {
          "en": "A maritime lien shall be governed by the law of the forum."
        },
        "noLabel": {
          "en": "Article 298."
        },
        "chapter": {
          "en": "Chapter XV Application of Law in Relation to Foreign-related Matters"
        }
      },
      {
        "no": 299,
        "text": {
          "en": "A lien on a ship shall be governed by the law of the place where the ship is retained."
        },
        "noLabel": {
          "en": "Article 299."
        },
        "chapter": {
          "en": "Chapter XV Application of Law in Relation to Foreign-related Matters"
        }
      },
      {
        "no": 300,
        "text": {
          "en": "The order of satisfaction among maritime liens, liens on a ship and mortgages on a ship shall be governed by the law of the forum."
        },
        "noLabel": {
          "en": "Article 300."
        },
        "chapter": {
          "en": "Chapter XV Application of Law in Relation to Foreign-related Matters"
        }
      },
      {
        "no": 301,
        "text": {
          "en": "Liability for collision of ships shall be governed by the law of the place where the tortious act is committed. Where the collision of ships occurs on the high seas, the law of the forum shall apply. Where ships of the same nationality collide, the liability between the colliding ships shall be governed by the law of the State of the flag.\nWhere, after a collision of ships has occurred, the parties choose by agreement the law to be applied, their agreement shall prevail."
        },
        "noLabel": {
          "en": "Article 301."
        },
        "chapter": {
          "en": "Chapter XV Application of Law in Relation to Foreign-related Matters"
        }
      },
      {
        "no": 302,
        "text": {
          "en": "Adjustment of general average shall be governed by the law of the place of adjustment.\nThe parties may choose by agreement the law applicable to claims for general average contribution; where the parties have made no such choice, the law of the place where the voyage terminates shall apply."
        },
        "noLabel": {
          "en": "Article 302."
        },
        "chapter": {
          "en": "Chapter XV Application of Law in Relation to Foreign-related Matters"
        }
      },
      {
        "no": 303,
        "text": {
          "en": "Limitation of liability for maritime claims shall be governed by the law of the forum."
        },
        "noLabel": {
          "en": "Article 303."
        },
        "chapter": {
          "en": "Chapter XV Application of Law in Relation to Foreign-related Matters"
        }
      },
      {
        "no": 304,
        "text": {
          "en": "Liability for oil pollution damage from ships shall be governed by the law of the place where the result of the oil pollution damage occurs."
        },
        "noLabel": {
          "en": "Article 304."
        },
        "chapter": {
          "en": "Chapter XV Application of Law in Relation to Foreign-related Matters"
        }
      },
      {
        "no": 305,
        "text": {
          "en": "The application of foreign laws in accordance with the provisions of this Chapter shall not prejudice the public interests of the People's Republic of China."
        },
        "noLabel": {
          "en": "Article 305."
        },
        "chapter": {
          "en": "Chapter XV Application of Law in Relation to Foreign-related Matters"
        }
      },
      {
        "no": 306,
        "text": {
          "en": "The unit of account referred to in this Law means the Special Drawing Right as prescribed by the International Monetary Fund; the amount in RMB thereof shall be the amount in RMB calculated on the date of the judgment of the court, the date of the award of the arbitral institution or the date of the agreement of the parties, at the exchange rate between the Special Drawing Right and RMB published by the International Monetary Fund."
        },
        "noLabel": {
          "en": "Article 306."
        },
        "chapter": {
          "en": "Chapter XVI Supplementary Provisions"
        }
      },
      {
        "no": 307,
        "text": {
          "en": "Where an international treaty concluded or acceded to by the People's Republic of China contains provisions different from those of this Law, the provisions of the international treaty shall apply, except for the clauses in respect of which the People's Republic of China has declared reservations.\nWhere neither the laws of the People's Republic of China nor the international treaties concluded or acceded to by the People's Republic of China contain provisions, international usage may be applied. The application of international usage shall not prejudice the public interests of the People's Republic of China."
        },
        "noLabel": {
          "en": "Article 307."
        },
        "chapter": {
          "en": "Chapter XVI Supplementary Provisions"
        }
      },
      {
        "no": 308,
        "text": {
          "en": "The State supports cooperation in international maritime transport affairs and promotes the sound development of the shipping industry.\nWhere any State or region adopts discriminatory prohibitions, restrictions or other similar measures against the People's Republic of China in the fields related to maritime transport and shipbuilding, the People's Republic of China may, in light of the actual circumstances, adopt corresponding measures against the State or region concerned."
        },
        "noLabel": {
          "en": "Article 308."
        },
        "chapter": {
          "en": "Chapter XVI Supplementary Provisions"
        }
      },
      {
        "no": 309,
        "text": {
          "en": "Shipowners, ship operators, ship managers or charterers may voluntarily form a mutual insurance organisation as members, collect membership dues in accordance with the articles of association, and bear liability for indemnity in respect of loss suffered, liability incurred or expenses paid by members in the operation of ships."
        },
        "noLabel": {
          "en": "Article 309."
        },
        "chapter": {
          "en": "Chapter XVI Supplementary Provisions"
        }
      },
      {
        "no": 310,
        "text": {
          "en": "This Law shall come into force on 1 May 2026."
        },
        "noLabel": {
          "en": "Article 310."
        },
        "chapter": {
          "en": "Chapter XVI Supplementary Provisions"
        }
      }
    ]
  };

})(typeof window !== 'undefined' ? window : globalThis);